L["A bar of its own for the faction you're watching. While it's on, the experience bar no longer turns to reputation when you gain some."] = "Una barra propia para la facción que sigues. Mientras está activa, la barra de experiencia ya no cambia a reputación cuando ganas algo."
L["A big number in the middle of your screen counts down any pull your group starts, in place of the game's bar. Move it in unlock mode. In a dungeon or raid the game may keep its own bar for a countdown someone else starts."] = "Un número grande en el centro de la pantalla cuenta atrás cada pull que inicie tu grupo, en lugar de la barra del juego. Muévelo en modo desbloqueo. En una mazmorra o banda, el juego puede mantener su propia barra para una cuenta atrás que inicie otra persona."
L["A bird on the world map at each flight master you can use: blue for Alliance, red for Horde, gold for both."] = "Un pájaro en el mapa del mundo en cada maestro de vuelo que puedes usar: azul para la Alianza, rojo para la Horda, dorado para ambas."
L["A border and shadow around each line."] = "Un borde y una sombra alrededor de cada línea."
L["A border and shadow around the background."] = "Un borde y una sombra alrededor del fondo."
L["A border and shadow around the boxes."] = "Un borde y una sombra alrededor de las casillas."
L["A border and shadow around the meter's own window."] = "Un borde y una sombra alrededor de la ventana del medidor."
L["A border and shadow around the panel behind the bar. When off, the panel is a plain fill."] = "Un borde y una sombra alrededor del panel detrás de la barra. Desactivado, el panel es un relleno simple."
L["A border and shadow around the second meter's window."] = "Un borde y una sombra alrededor de la ventana del segundo medidor."
L["A bright line along the cooldown shade's moving edge."] = "Una línea brillante a lo largo del borde móvil de la sombra del tiempo de reutilización."
L["A buff's exact name"] = "El nombre exacto de un beneficio"
L["A buff's time turns orange and gently pulses in its last 5 seconds."] = "El tiempo de un beneficio se vuelve naranja y pulsa suavemente en sus últimos 5 segundos."
L["A button on the game's class trainer window that learns every spell you can afford in one click. The DaylightUI style NPC window's trainer page has its own, so this is for the game's window (NPC window > Trainer window off)."] = "Un botón en la ventana del instructor de clase del juego que aprende con un clic todos los hechizos que puedes pagar. La sección Instructor de la ventana de PNJ estilo DaylightUI tiene la suya, así que este es para la ventana del juego (Ventana de PNJ > Ventana del instructor desactivada)."
L["A clean chat panel with class colors, timestamps and copyable links."] = "Un panel de chat limpio con colores de clase, marcas de tiempo y enlaces copiables."
L["A color over the icon while the mouse is over it."] = "Un color sobre el icono mientras el ratón está encima."
L["A color over the icon while you press it."] = "Un color sobre el icono mientras lo pulsas."
L["A copy of the one in use, layout and all."] = "Una copia del que está en uso, con su diseño y todo."
L["A countdown icon for each totem you have down."] = "Un icono con cuenta atrás para cada tótem que tengas colocado."
L["A crown on top of the portrait ring (or over the name tab) for the party or raid leader."] = "Una corona encima del anillo del retrato (o sobre la pestaña del nombre) para el líder del grupo o de la banda."
L["A dark edge around the letters on DaylightUI's frames, so text stays readable over a busy world."] = "Un borde oscuro alrededor de las letras de los marcos de DaylightUI, para que el texto siga siendo legible sobre un mundo recargado."
L["A dash ( - )"] = "Un guion ( - )"
L["A debuff you can remove, as tiles show it."] = "Un perjuicio que puedes disipar, tal como lo muestran las casillas."
L["A done objective stays, dimmed with a tick. When off, it disappears once it's done."] = "Un objetivo completado se mantiene, atenuado y con una marca. Desactivado, desaparece al completarse."
L["A dot ( · )"] = "Un punto ( · )"
L["A dragon wrapped around the end of an elite's or boss's bar, in gold, or silver for a rare."] = "Un dragón enroscado en el extremo de la barra de un élite o de un jefe, en dorado, o en plateado para un raro."
L["A frame dropped in unlock mode, a spell placed in the Cooldown Manager editor, a click-cast bound. The game has no sound of its own for these."] = "Un marco soltado en modo desbloqueo, un hechizo colocado en el editor del gestor de reutilización, un lanzamiento con clic asignado. El juego no tiene sonido propio para estas acciones."
L["A framed panel behind the bar."] = "Un panel con marco detrás de la barra."
L["A friendly player's <guild> under their name, smaller."] = "La <hermandad> de un jugador aliado bajo su nombre, en tamaño menor."
L["A gradient per point (Gradients page)"] = "Un degradado por punto (sección Degradados)"
L["A green sliver on the health bar for heals on their way, as the unit frames show them."] = "Un fino trazo verde en la barra de salud para las sanaciones en camino, tal como las muestran los marcos de unidad."
L["A group you deleted comes back, with its items."] = "Un grupo que borraste vuelve, con sus objetos."
L["A kill or item for a quest shows for a moment at the top of the screen, small, with a progress bar. Turn it off to see the game's yellow line instead. Move it in unlock mode."] = "Un enemigo abatido o un objeto de misión se muestra un momento en la parte superior de la pantalla, en pequeño, con una barra de progreso. Desactívalo para ver en su lugar la línea amarilla del juego. Muévelo en modo desbloqueo."
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute) and paladins (Hammer of Wrath)."] = "Una línea en las barras de salud enemigas donde empiezan a funcionar tus golpes de gracia. El tramo de la barra hasta ella se ilumina con tu color de acento cuando el enemigo está así de bajo. Tu clase: guerreros (Ejecutar) y paladines (Martillo de ira)."
L["A mana, rage or energy bar under the health. When off, the frame is all health."] = "Una barra de maná, ira o energía bajo la salud. Desactivada, el marco solo muestra salud."
L["A mark just left of the bar of anything your quests still need. Not inside instances."] = "Una marca justo a la izquierda de la barra de todo lo que tus misiones aún necesitan. No dentro de estancias."
L["A marker over the quest you picked and breadcrumbs on the ground leading to it. With the QuestieDB addon, an arrow to the nearest objective too."] = "Un marcador sobre la misión que has elegido y un camino en el suelo que lleva hasta ella. Con el complemento QuestieDB, también una flecha hacia el objetivo más cercano."
L["A member's border turns red while something is attacking them."] = "El borde de un miembro se vuelve rojo mientras algo lo ataca."
L["A member's ring (or name tab without a portrait) turns red while something is attacking them."] = "El anillo de un miembro (o la pestaña del nombre sin retrato) se vuelve rojo mientras algo lo ataca."
L["A name for the new group:"] = "Un nombre para el nuevo grupo:"
L["A name for the new profile (a copy of %s):"] = "Un nombre para el nuevo perfil (una copia de %s):"
L["A new profession"] = "Una nueva profesión"
L["A new profile, made from %s with your picks."] = "Un nuevo perfil, creado a partir de %s con tus elecciones."
L["A new whisper shows its first words above the tiles for a few seconds. Click it to answer."] = "Un nuevo susurro muestra sus primeras palabras encima de las casillas durante unos segundos. Haz clic en él para responder."
L["A new zone's name rises in at the top of the screen with a thin line under it, then the subzone and PvP status; a subzone shows just its name, small. It replaces the game's zone text. Follows Motion effects (General > Appearance)."] = "El nombre de una nueva zona aparece en la parte superior de la pantalla con una fina línea debajo, y después la subzona y el estado JcJ; una subzona muestra solo su nombre, en pequeño. Sustituye al texto de zona del juego. Sigue los efectos de movimiento (General > Apariencia)."
L["A note about this player"] = "Una nota sobre este jugador"
L["A note for %s:"] = "Una nota para %s:"
L["A pale sliver on the health bar for an absorb shield, as the unit frames show them."] = "Un fino trazo pálido en la barra de salud para un escudo de absorción, tal como lo muestran los marcos de unidad."
L["A panel behind the whole bar, so its buttons sit on one strip."] = "Un panel detrás de toda la barra, para que sus botones queden sobre una misma franja."
L["A panel behind the whole bar."] = "Un panel detrás de toda la barra."
L["A player's <guild> under their name, smaller."] = "La <hermandad> de un jugador bajo su nombre, en tamaño menor."
L["A player's casts in their class color, or their class's gradient with a two-color fill. Creatures' casts keep the fill style. Not with the Daylight gradient."] = "Los lanzamientos de un jugador en el color de su clase, o el degradado de su clase con un relleno de dos colores. Los lanzamientos de las criaturas mantienen el estilo de relleno. No se usa con el degradado Daylight."
L["A player's name in their class color; other units in their reaction's color."] = "El nombre de un jugador en el color de su clase; las demás unidades en el color de su reacción."
L["A pressed button's icon sinks in a little and springs back as you let go."] = "El icono de un botón pulsado se hunde un poco y vuelve a su sitio al soltarlo."
L["A profile per character or talent set, and a share string for your whole setup."] = "Un perfil por personaje o conjunto de talentos, y una cadena para compartir toda tu configuración."
L["A pulsing border while the spell's proc alert is up."] = "Un borde pulsante mientras está activa la alerta de activación del hechizo."
L["A quest ready to hand in shows its title alone. A timed quest never folds."] = "Una misión lista para entregar muestra solo su título. Una misión cronometrada nunca se pliega."
L["A quest you've failed, like a timed one that ran out."] = "Una misión fallida, como una cronometrada que se ha agotado."
L["A ring over the outer end. Class icons show for players; NPCs show their face. Needs a frame at least 20 tall."] = "Un anillo sobre el extremo exterior. Los iconos de clase se muestran para los jugadores; los PNJ muestran su rostro. Necesita un marco de al menos 20 de alto."
L["A round badge with their portrait, or a slim bar with the portrait beside it and the name above."] = "Una insignia redonda con su retrato, o una barra fina con el retrato al lado y el nombre encima."
L["A second damage meter in its own window, for two lists at once: healing beside damage, say. Hover it for the same buttons."] = "Un segundo medidor de daño en su propia ventana, para dos listas a la vez: sanación junto a daño, por ejemplo. Pasa el cursor sobre él para ver los mismos botones."
L["A set already has that name."] = "Ya existe un conjunto con ese nombre."
L["A shield: the bar empties as it soaks damage, with the amount left on it. Or by its time, like any buff."] = "Un escudo: la barra se vacía a medida que absorbe daño, con la cantidad restante. O según su tiempo, como cualquier beneficio."
L["A skill going up shows its new rank, out of its cap: Tailoring 152 / 225. More skill-ups move the same line on."] = "Una habilidad que sube muestra su nuevo rango sobre su máximo: Sastrería 152 / 225. Las siguientes subidas de habilidad mueven la misma línea."
L["A slash ( / )"] = "Una barra oblicua ( / )"
L["A slim bar under the tooltip of a player or creature."] = "Una barra fina bajo la información emergente de un jugador o criatura."
L["A slot at or under this much durability gets an amber dot and says Repair soon."] = "Una ranura con esta durabilidad o menos recibe un punto ámbar y muestra «Reparar pronto»."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner of bank items, until the item is bound to you."] = "Un pequeño BoE (ligado al equiparlo) o BoU (ligado al equiparlo) en la esquina superior izquierda de los objetos del banco, hasta que el objeto quede vinculado a ti."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound to you."] = "Un pequeño BoE (ligado al equiparlo) o BoU (ligado al usarlo) en la esquina superior izquierda, hasta que el objeto quede vinculado a ti."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound."] = "Un pequeño BoE (ligado al equiparlo) o BoU (ligado al usarlo) en la esquina superior izquierda, hasta que el objeto quede vinculado."
L["A small Copy button at the top-right of the chat. It opens the tab's text so you can select it and press Ctrl+C. /dui copy does the same."] = "Un pequeño botón Copiar en la esquina superior derecha del chat. Abre el texto de la pestaña para que puedas seleccionarlo y pulsar Ctrl+C. /dui copy hace lo mismo."
L["A small badge at the foot of the portrait (or the frame's corner without one), colored by how hard the unit is for you."] = "Una pequeña insignia al pie del retrato (o en la esquina del marco si no tiene), coloreada según lo difícil que sea la unidad para ti."
L["A small badge at the foot of the portrait, colored by how hard the unit is for you. Needs the portrait or the name tab."] = "Una pequeña insignia al pie del retrato, coloreada según lo difícil que sea la unidad para ti. Necesita el retrato o la pestaña del nombre."
L["A small bar beside each party member who has a pet out. Your own pet keeps its own frame."] = "Una pequeña barra junto a cada miembro del grupo que tenga una mascota invocada. Tu propia mascota conserva su propio marco."
L["A small crown on the raid leader's tile."] = "Una pequeña corona en la casilla del líder de la banda."
L["A small crown tab beside your party or raid frames while you lead the group or assist in a raid. It opens ready check, role check, a pull timer, target and world markers, and Everyone is assist. When off, these are only in the game's slash commands."] = "Una pequeña pestaña de corona junto a tus marcos de grupo o de banda mientras diriges el grupo o asistes en una banda. Abre la comprobación de listos, la comprobación de roles, un temporizador de pull, los marcadores de objetivo y del mundo, y «Todos asistentes». Desactivada, estas opciones solo están en los comandos slash del juego."
L["A small dot in front of each quest you're tracking."] = "Un pequeño punto delante de cada misión que sigues."
L["A small dot in the top right corner on bank items that are part of one of your equipment sets."] = "Un pequeño punto en la esquina superior derecha de los objetos del banco que forman parte de uno de tus conjuntos de equipo."
L["A small dot in the top right corner on items that are part of one of your equipment sets."] = "Un pequeño punto en la esquina superior derecha de los objetos que forman parte de uno de tus conjuntos de equipo."
L["A small number in your accent color after a tab's name: how many new messages landed in it since you last looked."] = "Un pequeño número en tu color de acento tras el nombre de una pestaña: cuántos mensajes nuevos han llegado desde la última vez que miraste."
L["A small gray line at the bottom of spell and item tooltips with its ID: handy for macros, other addons and bug reports. Buff and debuff icons use the game's own tooltip, which can't show it."] = "Una pequeña línea gris al pie de los avisos emergentes de hechizos y objetos con su ID: útil para macros, otros addons e informes de errores. Los iconos de beneficios y perjuicios usan la información emergente del juego, que no puede mostrarla."
L["A small icon in a corner for a debuff you can remove, edged in its type's color."] = "Un pequeño icono en una esquina para un perjuicio que puedes disipar, con borde del color de su tipo."
L["A small mana, rage or energy number on the power bar."] = "Un pequeño número de maná, ira o energía en la barra de poder."
L["A small pet bar beside each party member whose pet is out."] = "Una pequeña barra de mascota junto a cada miembro del grupo cuya mascota esté invocada."
L["A small skull on the portrait once your damage over time is enough to finish the target."] = "Una pequeña calavera en el retrato cuando tu daño en el tiempo basta para acabar con el objetivo."
L["A small skull past the bar's end once your damage over time is enough to finish that enemy."] = "Una pequeña calavera tras el extremo de la barra cuando tu daño en el tiempo basta para acabar con ese enemigo."
L["A small soft drop shadow under text."] = "Una pequeña sombra suave bajo el texto."
L["A small speech bubble at the top-right of the chat that counts your unread whispers and opens all your conversations. /dui whispers does the same."] = "Una pequeña burbuja de diálogo en la esquina superior derecha del chat que cuenta tus susurros sin leer y abre todas tus conversaciones. /dui whispers hace lo mismo."
L["A small square left of the frame: red while your pet is unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "Un pequeño cuadrado a la izquierda del marco: rojo cuando tu mascota está descontenta, amarillo mientras está satisfecha, verde mientras está feliz. Pasa el cursor para ver su daño, lealtad y dieta."
L["A small tag after an elite, dungeon, raid or PvP quest's title, here and in the quest log on the map."] = "Una pequeña etiqueta tras el título de una misión de élite, de mazmorra, de banda o JcJ, aquí y en el registro de misiones del mapa."
L["A small time at the bottom of the map. Hover it for both local and server time."] = "Una pequeña hora en la parte inferior del mapa. Pasa el cursor para ver la hora local y la del servidor."
L["A small zone name over each group of quests, the zone you're in first."] = "Un pequeño nombre de zona sobre cada grupo de misiones, la zona en la que estás primero."
L["A soft chime when talents are applied, a talent set is switched, a spell is learned at a trainer or a letter is sent."] = "Un carillón suave cuando se aplican talentos, se cambia un conjunto de talentos, se aprende un hechizo con un instructor o se envía una carta."
L["A soft glow behind a message that says your name or one of your words."] = "Un suave resplandor detrás de un mensaje que contiene tu nombre o una de tus palabras."
L["A soft glow in the threat color around the health bar."] = "Un suave resplandor en el color de amenaza alrededor de la barra de salud."
L["A soft light behind the arrow, in its color."] = "Una luz suave detrás de la flecha, en su color."
L["A soft light in the line's color runs across it as it comes in or adds up."] = "Una luz suave del color de la línea la recorre cuando aparece o se suma."
L["A soft light round the frame in the debuff's type color."] = "Una luz suave alrededor del marco en el color del tipo del perjuicio."
L["A soft light round the tile in the debuff's type color."] = "Una luz suave alrededor de la casilla en el color del tipo del perjuicio."
L["A soft shadow round each button."] = "Una sombra suave alrededor de cada botón."
L["A soft sound when your name or one of your words shows up."] = "Un sonido suave cuando aparece tu nombre o una de tus palabras."
L["A soft, minimal interface."] = "Una interfaz suave y minimalista."
L["A soft, warm chime when a tracked quest is ready to hand in."] = "Un carillón suave y cálido cuando una misión seguida está lista para entregar."
L["A space"] = "Un espacio"
L["A spell that just lit up, like Overpower or Execute."] = "Un hechizo que acaba de iluminarse, como Abrumar o Ejecutar."
L["A spell with charges: the bar is cut into one piece per charge."] = "Un hechizo con cargas: la barra se divide en un segmento por carga."
L["A spell's icon pops and lights up once when it comes off a real cooldown (never for the global cooldown). Needs Motion effects (General > Appearance)."] = "El icono de un hechizo salta y se ilumina una vez cuando sale de un tiempo de reutilización real (nunca por el tiempo de reutilización global). Necesita los efectos de movimiento (General > Apariencia)."
L["A spell's icon turns gray while it's on cooldown. The global cooldown doesn't count."] = "El icono de un hechizo se vuelve gris mientras está en tiempo de reutilización. El tiempo de reutilización global no cuenta."
L["A square minimap in the panel. Scroll to zoom."] = "Un minimapa cuadrado en el panel. Desplázate para acercar o alejar."
L["A stun, fear, polymorph and the like, as a bigger icon beside the bar's end."] = "Un aturdimiento, miedo, polimorfia y similares, en forma de icono más grande junto al extremo de la barra."
L["A symbol on the world map at each boat dock and zeppelin tower. Hover it to see where it goes."] = "Un símbolo en el mapa del mundo en cada muelle de barco y torre de zepelín. Pasa el cursor para ver adónde lleva."
L["A symbol on the world map at each dungeon and raid entrance. Hover it for the name."] = "Un símbolo en el mapa del mundo en cada entrada de mazmorra y de banda. Pasa el cursor para ver el nombre."
L["A thin bar under the name."] = "Una barra fina bajo el nombre."
L["A thin line across the bars where your threat would pull it: 110% of the tank's in melee, 130% at range. Not shown on a boss, whose numbers the game keeps hidden."] = "Una línea fina atravesando las barras donde tu amenaza haría que el enemigo te atacara: 110% de la del tanque en cuerpo a cuerpo, 130% a distancia. No se muestra en un jefe, cuyas cifras el juego oculta."
L["A thin line in your accent color along the top of the chat."] = "Una línea fina en tu color de acento a lo largo de la parte superior del chat."
L["A thin mana strip along the bottom of the power bar while a form hides your mana."] = "Una franja fina de maná en la parte inferior de la barra de poder mientras una forma oculta tu maná."
L["A thin mana, rage or energy bar at the foot of each tile."] = "Una barra fina de maná, ira o energía al pie de cada casilla."
L["A thin outline on chat text."] = "Un contorno fino en el texto del chat."
L["A thin power bar under each pet's health."] = "Una barra de poder fina bajo la salud de cada mascota."
L["A thin strip under the minimap: gold, gear, bag space, friends online. Hover one for details, click it to open its window."] = "Una franja fina bajo el minimapa: oro, equipo, espacio en las bolsas, amigos en línea. Pasa el cursor sobre un elemento para ver los detalles; haz clic para abrir su ventana."
L["A thinner outline leaves more of each pip for the color. Set to 0 for none."] = "Un contorno más fino deja más espacio para el color en cada pastilla. Ponlo en 0 para no tener contorno."
L["A tooltip for something in the world (a creature, a player, a mailbox) fades away slowly after the mouse leaves it, as the game does. When off, it's gone at once."] = "La información emergente de un elemento del mundo (una criatura, un jugador, un buzón) se desvanece lentamente cuando el ratón se aleja, como en el juego. Desactivada, desaparece de inmediato."
L["A trail of small diamonds from your feet to the marker, drifting toward it. Like the marker, it fades away once you're in the quest's area on the map."] = "Un rastro de pequeños rombos desde tus pies hasta el marcador, desplazándose hacia él. Como el marcador, se desvanece una vez que estás en la zona de la misión en el mapa."
L["A two-minute tour of everything DaylightUI does, picking as you go. Nothing is saved until you finish."] = "Un recorrido de dos minutos por todo lo que hace DaylightUI, eligiendo a medida que avanzas. No se guarda nada hasta que termines."
L["A warm line of light spreads across the top of the screen, your new level rolls in and what you gained fades in under it, in place of the game's banner. Follows Motion effects (General > Appearance)."] = "Una línea de luz cálida se extiende por la parte superior de la pantalla, tu nuevo nivel aparece desplazándose y lo que has ganado se muestra con un fundido debajo, en lugar del banner del juego. Sigue los efectos de movimiento (General > Apariencia)."
L["A warning when your health or mana drops low."] = "Un aviso cuando tu salud o tu maná bajan mucho."
L["A word or phrase"] = "Una palabra o frase"
L["A word when a fight starts and ends."] = "Una palabra cuando empieza y termina un combate."
L["AFK"] = "AFK"
L["AP"] = "PA"
L["AVOIDABLE"] = "EVITABLE"
L["AWAY"] = "AUSENTE"
L["Abandon"] = "Abandonar"
L["Abandon \"%s\"?"] = "¿Abandonar «%s»?"
L["Abandon?"] = "¿Abandonar?"
L["About 1 in %d of your attacks hits for double damage."] = "Aproximadamente 1 de cada %d de tus ataques inflige el doble de daño."
L["About 1 in %d of your shots hits for double damage."] = "Aproximadamente 1 de cada %d de tus disparos inflige el doble de daño."
L["About 1 in %d of your spells lands a critical hit for half again as much."] = "Aproximadamente 1 de cada %d de tus hechizos inflige un golpe crítico, un 50% más."
L["Above"] = "Encima"
L["Above or below the frame, the bar is as wide as the frame. Off: the Width below."] = "Encima o debajo del marco, la barra tiene el mismo ancho que el marco. Desactivado: se usa el Ancho de abajo."
L["Above or below the frame: moves the bar sideways from the middle."] = "Encima o debajo del marco: desplaza la barra lateralmente desde el centro."
L["Above or below the frame: moves the bar up or down."] = "Encima o debajo del marco: mueve la barra hacia arriba o hacia abajo."
L["Above the frame"] = "Encima del marco"
L["Above the health bar"] = "Encima de la barra de salud"
L["Above the name tab by default, running inward. Yours come first."] = "Encima de la pestaña del nombre por defecto, hacia dentro. Los tuyos primero."
L["Above your debuffs, from the right."] = "Encima de tus perjuicios, desde la derecha."
L["Absorb shields"] = "Escudos de absorción"
L["Absorbs"] = "Absorciones"
L["Accent"] = "Acento"
L["Accent color"] = "Color de acento"
L["Accent follows Appearance, including the Daylight gradient."] = "El acento sigue a la Apariencia, incluido el degradado Daylight."
L["Accent follows the accent color on the Appearance page. Class uses your class's gradient (set on the Gradients page). Reputation keeps its standing's colors."] = "El acento sigue al color de acento de la sección Apariencia. Clase usa el degradado de tu clase (ajustado en la sección Degradados). Reputación conserva los colores de su rango."
L["Accent follows the accent you picked on the General page, gradient and all."] = "El acento sigue al que elegiste en la sección General, degradado incluido."
L["Accent follows your accent color (General > Appearance), or pick your own."] = "El acento sigue a tu color de acento (General > Apariencia), o elige el tuyo."
L["Accent line on top"] = "Línea de acento arriba"
L["Accept"] = "Aceptar"
L["Accept key"] = "Tecla de aceptar"
L["Accept quests automatically"] = "Aceptar misiones automáticamente"
L["Account"] = "Cuenta"
L["Achievement announcements."] = "Anuncios de logros."
L["Achievement color"] = "Color de los logros"
L["Achievements"] = "Logros"
L["Across"] = "A lo ancho"
L["Across the bar"] = "A lo ancho de la barra"
L["Across the bar keeps it inside. Any other spot puts it there, on or round the frame, so a long name has room. You can also drag it in Design mode."] = "A lo ancho de la barra lo mantiene dentro. Cualquier otra posición lo coloca allí, sobre o alrededor del marco, para que quepa un nombre largo. También puedes arrastrarlo en el modo Diseño."
L["Across the bar keeps the alignment below. Beside the tile needs space between tiles."] = "A lo ancho de la barra mantiene la alineación de abajo. Junto a la casilla necesita espacio entre casillas."
L["Across, you shown, by role, icons in corners"] = "En línea, tú mostrado, por rol, iconos en las esquinas"
L["Action Bar 1"] = "Barra de acción 1"
L["Action Bar 1 in %s"] = "Barra de acción 1 en %s"
L["Action Bar 2"] = "Barra de acción 2"
L["Action Bar 3"] = "Barra de acción 3"
L["Action Bar 4"] = "Barra de acción 4"
L["Action Bar 5"] = "Barra de acción 5"
L["Action Bar 6"] = "Barra de acción 6"
L["Action Bar 7"] = "Barra de acción 7"
L["Action Bar 8"] = "Barra de acción 8"
L["Action Bars"] = "Barras de acción"
L["Action bars"] = "Barras de acción"
L["Action bars, short"] = "Barras"
L["Activate"] = "Activar"
L["Activate this set first."] = "Activa primero este conjunto."
L["Active spell"] = "Hechizo activo"
L["Active spell color"] = "Color del hechizo activo"
L["Active spell opacity"] = "Opacidad del hechizo activo"
L["Add"] = "Añadir"
L["Add a friend: a BattleTag (Name#1234) or a character's name."] = "Añade un amigo: un BattleTag (Nombre#1234) o el nombre de un personaje."
L["Add a group"] = "Añadir un grupo"
L["Add friend"] = "Añadir amigo"
L["Add to favorites"] = "Añadir a favoritos"
L["AddOns"] = "Addons"
L["Added with Add piece in Design mode. Drag it on the preview to move it. Up to three parts in one line, each in its own color."] = "Añadido con Añadir elemento en el modo Diseño. Arrástralo sobre la vista previa para moverlo. Hasta tres partes en una línea, cada una en su propio color."
L["Added with Add piece in Design mode: one more row of auras, with its own filter."] = "Añadido con Añadir elemento en el modo Diseño: una fila más de auras, con su propio filtro."
L["Addon button drawer"] = "Cajón de botones de addons"
L["Addon options (Ace3)"] = "Opciones de addons (Ace3)"
L["Addons' minimap buttons and the game's addon menu are gathered into one drawer. The button in the map's bottom-right corner opens it."] = "Los botones del minimapa de los addons y el menú de addons del juego se agrupan en un cajón. El botón de la esquina inferior derecha del mapa lo abre."
L["Adds a warm band inside the black outline, lit along the top. When off, the border is a plain dark line."] = "Añade una banda cálida dentro del contorno negro, iluminada por arriba. Desactivado, el borde es una simple línea oscura."
L["Adds about %.0f damage per second to your melee attacks."] = "Añade unos %.0f de daño por segundo a tus ataques cuerpo a cuerpo."
L["Adds about %.0f damage per second to your shots."] = "Añade unos %.0f de daño por segundo a tus disparos."
L["Adds up to %.0f to your heals."] = "Añade hasta %.0f a tus sanaciones."
L["Adds up to %.0f to your spells' damage."] = "Añade hasta %.0f al daño de tus hechizos."
L["Adventure"] = "Aventura"
L["Affliction"] = "Aflicción"
L["After /reload, the last messages in each chat tab come back, above a gray line."] = "Tras /reload, los últimos mensajes de cada pestaña del chat vuelven a aparecer, encima de una línea gris."
L["After a login or /reload the UI starts invisible and glides in. Anything set to fade ends faded."] = "Tras iniciar sesión o hacer /reload, la interfaz empieza invisible y aparece deslizándose. Todo lo configurado para desvanecerse acaba desvanecido."
L["After a player's guild name."] = "Tras el nombre de hermandad de un jugador."
L["After combat"] = "Tras el combate"
L["After the fight"] = "Tras el combate"
L["Aggro"] = "Amenaza"
L["Aggro color"] = "Color de amenaza"
L["Aggro colors"] = "Colores de amenaza"
L["Agility"] = "Agilidad"
L["Ah, a fresh face. Goldshire isn't what it was, with kobolds in every mine. Still, a man has to keep his shop."] = "¡Ah, una cara nueva! Villadorada ya no es lo que era, con kobolds en cada mina. Aun así, un hombre tiene que mantener su tienda."
L["Alfa Slab One"] = "Alfa Slab One"
L["Alignment"] = "Alineación"
L["All"] = "Todo"
L["All %d spells snapped together"] = "Los %d hechizos están unidos"
L["All activities"] = "Todas las actividades"
L["Show all"] = "Mostrar todo"
L["%d activities"] = "%d actividades"
L["All addons: %.3f ms"] = "Todos los addons: %.3f ms"
L["All bars"] = "Todas las barras"
L["All characters"] = "Todos los personajes"
L["All debuffs"] = "Todos los perjuicios"
L["All donators"] = "Todos los donantes"
L["All four extra aura groups are in use: remove one first."] = "Los cuatro grupos de auras adicionales están en uso: elimina primero uno."
L["All four extra texts are in use: remove one first."] = "Los cuatro textos adicionales están en uso: elimina primero uno."
L["All frames are back in their default places."] = "Todos los marcos han vuelto a su lugar por defecto."
L["All points"] = "Todos los puntos"
L["All quests"] = "Todas las misiones"
L["All set"] = "Todo listo"
