L["An Item Level line on weapon and armor tooltips, in soft gold."] = "Una línea de Nivel de objeto en los avisos emergentes de armas y armaduras, en dorado suave."
L["An arrow on your screen that points to the nearest mob or object you still need for the quest you picked, then to the quest giver once it's ready, with the yards under it. Nothing goes on the map. Needs the QuestieDB addon."] = "Una flecha en pantalla que apunta al enemigo u objeto más cercano que aún necesitas para la misión que elegiste, y luego a quien da la misión cuando esté lista, con los metros debajo. No se añade nada al mapa. Necesita el addon QuestieDB."
L["An item link shows your equipped item beside it, as the game's own compare setting says. Off, only while Shift is held."] = "Un enlace de objeto muestra a su lado el objeto que llevas equipado, según indica el ajuste de comparación del propio juego. Desactivado, solo mientras se mantiene Mayús."
L["An item's green Equip lines in a few words (\"Improves your chance to hit by 1%\" reads \"+1% Hit\"), and every stat in a color of its own: each school, hit, crit, spell power, healing, the base stats. Procs and use effects stay as they are."] = "Las líneas verdes «Equipar:» de un objeto en pocas palabras («Mejora tu probabilidad de golpear un 1%» se muestra como «+1% Golpe»), y cada estadística en su propio color: cada escuela, golpe, crítico, poder con hechizos, sanación y estadísticas básicas. Las activaciones y los efectos de uso se mantienen como están."
L["An objective you've finished."] = "Un objetivo que has completado."
