L["Class and profession trainers open in the NPC window too, with what you can learn now and what's coming up. Pick a spell, then press Train or Train all: a click or a key alone never spends gold. Turn it off to use the game's trainer window."] = "Los instructores de clase y de profesión también se abren en la ventana de PNJ, con lo que puedes aprender ahora y lo que viene después. Elige un hechizo y pulsa Aprender o Aprender todo: un clic o una sola tecla nunca gasta oro. Desactívalo para usar la ventana de instructor del juego."
L["Class and reaction"] = "Clase y reacción"
L["Class and reaction: players by class color, others by friendly, neutral or hostile. Dark: a near-black bar with the missing health in the class or reaction color."] = "Clase y reacción: los jugadores según el color de su clase, los demás según sean amistosos, neutrales u hostiles. Oscuro: una barra casi negra con la salud que falta en el color de clase o de reacción."
