L["Cuts both ends of each line at an angle. When off, the ends are straight."] = "Corta ambos extremos de cada línea en diagonal. Desactivado, los extremos son rectos."
L["Cuts each tile's right end at an angle, like your own frame; the bars follow it."] = "Corta el extremo derecho de cada casilla en diagonal, como tu propio marco; las barras lo siguen."
L["Cuts one end of each pet bar at an angle. When off, the ends are straight."] = "Corta un extremo de cada barra de mascota en diagonal. Desactivado, los extremos son rectos."
L["Cuts the end of the bar at an angle. When off, the end is straight."] = "Corta el extremo de la barra en diagonal. Desactivado, el extremo es recto."
L["Cuts the end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "Corta el extremo de la barra de lanzamiento de tu foco en diagonal. Desactivado, su extremo es recto. No mientras esté colocada dentro del marco."
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "Corta el extremo de la barra de lanzamiento de tu objetivo en diagonal. Desactivado, su extremo es recto. No mientras esté colocada dentro del marco."
L["Cuts the frame's inner end at an angle; the bars follow it."] = "Corta el extremo interior del marco en diagonal; las barras lo siguen."
L["Cuts the left end at an angle; the bars follow it."] = "Corta el extremo izquierdo en diagonal; las barras lo siguen."
L["Cuts the right end at an angle; the bars and an attached cast bar follow it."] = "Corta el extremo derecho en diagonal; las barras y una barra de lanzamiento adjunta lo siguen."
L["Cuts the right end at an angle; the bars follow it."] = "Corta el extremo derecho en diagonal; las barras lo siguen."
L["Cutscenes and intro movies end at once. Hold Shift as one starts to watch it."] = "Las escenas y los vídeos de introducción terminan al instante. Mantén pulsado Mayús al iniciarse uno para verlo."
