L["DND"] = "DND"
L["DPS / Tank"] = "DPS / Tanque"
L["DPS / Tank (as it comes)"] = "DPS / Tanque (tal cual)"
L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tanque sosegado para las misiones: tus barras de acción y tu propio marco se desvanecen un rato después de un combate (vuelven bajo el ratón, en combate o cuando estás herido), el medidor de daño empieza plegado (un clic en la pestaña del panel lo hace aparecer), el minimapa es un poco más pequeño y la barra de PE muestra su porcentaje. Nada se desvanece en mazmorras, bandas, campos de batalla o arenas (General > Apariencia, Desvanecer solo en mundo abierto). Elígelo arriba para usarlo. Si el perfil actual tiene barras de acción movidas, ofrece llevarlas consigo."
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tanque con tu grupo y tu banda como casillas cuadradas debajo de ti (tú incluido, con la salud perdida en ellas y las disipaciones bien visibles), y tu marco y el de tu objetivo un poco elevados. Todo lo que ajusta está en las secciones Grupo y Banda; mueve cualquiera de ellos en modo de desbloqueo. Elígelo arriba para usarlo. Si el perfil actual tiene barras de acción movidas, ofrece llevarlas consigo."
L["Damage"] = "Daño"
L["Damage / Tank"] = "Daño / Tanque"
L["Damage Meter"] = "Medidor de daño"
L["Damage dealers get a role icon too. When off, only tanks and healers get one."] = "Los DPS también tienen un icono de rol. Desactivado, solo los tanques y los sanadores tienen uno."
L["Damage done"] = "Daño infligido"
