L["Damage numbers"] = "Números de daño"
L["Damage shields, as a pale stretch after any incoming heals."] = "Escudos que absorben daño, como un tramo pálido tras las sanaciones entrantes."
L["Damage taken"] = "Daño recibido"
L["Damage you deal"] = "Daño que infliges"
