L["Dark end, then light end. The bar next to them is a preview."] = "Extremo oscuro, luego extremo claro. La barra de al lado es una vista previa."
L["Dark tooltips with class colors, item quality borders and a health bar."] = "Aviso emergente oscuro con colores de clase, bordes según la calidad de los objetos y una barra de salud."
