L["Daylight"] = "Daylight"
L["Daylight UI couldn't skin %s %s: it's left as it is."] = "Daylight UI no pudo aplicar el estilo a %s %s: se deja tal cual."
L["Daylight UI's chat box in the bottom-left corner, with whispers as conversations beside it. Chat style: Classic keeps the game's own chat windows instead."] = "El cuadro de chat de Daylight UI en la esquina inferior izquierda, con los susurros como conversaciones a su lado. Estilo de chat: Clásico mantiene en su lugar las ventanas de chat del juego."
L["Daylight UI's journal, marker and arrow stay either way. You can change it later on the Quests options page."] = "El registro, el marcador y la flecha de Daylight UI se mantienen en cualquier caso. Podrás cambiarlo más tarde en la sección de opciones de Misiones."
L["Daylight gradient"] = "Degradado Daylight"
L["Daylight is the warm band inside a dark outline, Flat a plain outline. With None the icon fills the whole button."] = "Daylight es la franja cálida dentro de un contorno oscuro, y Plano un contorno simple. Con Ninguno, el icono ocupa todo el botón."
L["Daylight look"] = "Apariencia Daylight"
L["Daylight: Daylight UI's own chat box, with its own tabs. Classic: the game's chat windows and tabs in the Daylight look. Switching is instant, and both keep every message."] = "Daylight: el cuadro de chat propio de Daylight UI, con sus propias pestañas. Clásico: las ventanas y pestañas de chat del juego con la apariencia Daylight. El cambio es instantáneo y ambos conservan todos los mensajes."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Default uses the style set for every frame (Extras > Frame style). Each style keeps its own heights."] = "Daylight: el marco con su nombre en una pestaña encima y la barra de poder dentro. Cinta: una barra fina con el nombre y la salud flotando encima y el poder como una línea fina debajo. Predeterminado usa el estilo definido para todos los marcos (Extras > Estilo de marcos). Cada estilo conserva sus propias alturas."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Each frame can pick its own on its page."] = "Daylight: el marco con su nombre en una pestaña encima y la barra de poder dentro. Cinta: una barra fina con el nombre y la salud flotando encima y el poder como una línea fina debajo. Cada marco puede elegir el suyo en su sección."
L["DaylightMogul's mailbox is in use."] = "El buzón de DaylightMogul está en uso."
L["DaylightMogul's profession window is in use."] = "La ventana de profesión de DaylightMogul está en uso."
L["DaylightMogul's vendor window is in use."] = "La ventana de comerciante de DaylightMogul está en uso."
L["DaylightUI"] = "DaylightUI"
L["DaylightUI (General)"] = "DaylightUI (General)"
L["DaylightUI Discord"] = "Discord de DaylightUI"
L["DaylightUI has a new setup guide. Take the tour to see everything it can do, or keep your setup as it is."] = "DaylightUI tiene una nueva guía de configuración. Haz el recorrido para ver todo lo que puede hacer, o mantén tu configuración tal como está."
L["DaylightUI is set up on this character. Reload to put it in place?"] = "DaylightUI está configurado en este personaje. ¿Recargar para aplicarlo?"
L["DaylightUI look for speech bubbles (say, yell, party). Instances keep the game's bubbles, since addons can't change them there."] = "Apariencia de DaylightUI para las burbujas de diálogo (decir, gritar, grupo). Las estancias mantienen las burbujas del juego, ya que los addons no pueden cambiarlas allí."
L["DaylightUI moved the quest tracker to fit the panel. Reload to put it in place?"] = "DaylightUI movió el seguimiento de misiones para ajustarlo al panel. ¿Recargar para aplicarlo?"
L["DaylightUI put this profile's Edit Mode layout in place. Reload to use it?"] = "DaylightUI aplicó el diseño del Modo de edición de este perfil. ¿Recargar para usarlo?"
L["DaylightUI replaces your frames, bars, bags, chat and more with a soft, minimal look. Let's set this character up."] = "DaylightUI sustituye tus marcos, barras, bolsas, chat y más por un aspecto suave y minimalista. Configuremos este personaje."
L["DaylightUI saved the crowd control alert's position. Reload to put it in place?"] = "DaylightUI ha guardado la posición del aviso de control. ¿Recargar para colocarla?"
L["DaylightUI saved the loot window's position. Reload to put it in place?"] = "DaylightUI guardó la posición de la ventana de botín. ¿Recargar para aplicarla?"
L["DaylightUI saved the quest tracker's position. Reload to put it in place?"] = "DaylightUI guardó la posición del seguimiento de misiones. ¿Recargar para aplicarla?"
L["DaylightUI saved these positions. Reload to put them in place?"] = "DaylightUI ha guardado estas posiciones. ¿Recargar para colocarlas?"
