L["Drag it to an action bar."] = "Arrástralo a una barra de acción."
L["Drag the pieces of the preview to move them: each stays where you let go, or catches on a dot right beside it. Click one, and the arrow keys nudge it (Shift for bigger steps). Every move changes the same settings as the cards below."] = "Arrastra los elementos de la vista previa para moverlos: cada uno se queda donde lo sueltes, o se engancha en un punto justo a su lado. Haz clic en uno, y las flechas lo desplazan (Mayús para pasos más grandes). Cada movimiento cambia los mismos ajustes que las tarjetas de abajo."
L["Drag to move it, or click for its settings."] = "Arrastra para moverlo, o haz clic para ver sus ajustes."
L["Drag to move. Drop it beside another piece to hook it on, drag it away to free it. Delete removes it."] = "Arrastra para mover. Suéltalo junto a otro elemento para engancharlo, aléjalo para liberarlo. Suprimir lo quita."
