L["Durability"] = "Durabilidad"
L["Durability %s"] = "Durabilidad %s"
L["During a ready check, a tick, a cross or a question mark on each member: ready, not ready, or no answer yet. They stay a few seconds after the check ends."] = "Durante una comprobación de disponibilidad, una marca, una cruz o un signo de interrogación en cada miembro: listo, no listo o aún sin respuesta. Permanecen unos segundos tras terminar la comprobación."
L["ENEMY TAKEN"] = "DAÑO RECIBIDO (ENEMIGOS)"
L["Each bar in its player's class color, or all in one color."] = "Cada barra en el color de clase de su jugador, o todas de un solo color."
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar."] = "La mano de cada barra (o el ataque en cola) y el tiempo hasta el siguiente golpe, escritos en la barra."
L["Each bar's shape and when it shows. Changes apply at once. Move bars in unlock mode."] = "La forma de cada barra y cuándo se muestra. Los cambios se aplican al instante. Mueve las barras en modo de desbloqueo."
L["Each bar's size, shape and when it shows. Pick the bar with Settings for."] = "El tamaño y la forma de cada barra y cuándo se muestra. Elige la barra con «Ajustes para»."
L["Each character uses a profile (one per talent set, with dual spec). Everything on every page changes the profile in use."] = "Cada personaje usa un perfil (uno por conjunto de talentos, con doble especialización). Todo lo que hay en cada sección modifica el perfil en uso."
L["Each character's bags are saved when you log out, and its bank each time you visit a banker. See them anywhere with the chest button in your bags, or /dui bank. When off, the button goes away and nothing new is saved."] = "Las bolsas de cada personaje se guardan al cerrar sesión, y su banco cada vez que visitas a un banquero. Consúltalas en cualquier lugar con el botón de cofre de tus bolsas, o /dui bank. Desactivado, el botón desaparece y no se guarda nada nuevo."
L["Each combo point you build on your target."] = "Cada punto de combo que acumulas en tu objetivo."
L["Each icon darkens like a clock as its time runs out."] = "Cada icono se oscurece como un reloj a medida que se agota su tiempo."
L["Each icon's width and height."] = "Anchura y altura de cada icono."
L["Each item's name and item level next to its icon. When off, only the icons show, with the item level in each corner and more room for the model."] = "El nombre y el nivel de objeto de cada objeto junto a su icono. Desactivado, solo se muestran los iconos, con el nivel de objeto en cada esquina y más espacio para el modelo."
L["Each its own"] = "Cada uno el suyo"
L["Each main-hand swing hits for %.0f to %.0f before armor."] = "Cada golpe de mano principal inflige de %.0f a %.0f antes de armadura."
L["Each member's health written on their tile."] = "La salud de cada miembro escrita en su casilla."
L["Each member's name on their tile."] = "El nombre de cada miembro en su casilla."
L["Each new message fades in instead of appearing at once. Never in a fight."] = "Cada mensaje nuevo aparece gradualmente en lugar de mostrarse de golpe. Nunca en combate."
L["Each objective line under a quest."] = "Cada línea de objetivo bajo una misión."
L["Each person who whispers you gets a tab next to the others, and the whisper shows in your main tab as well. When off, whispers only show in the main tab."] = "Cada persona que te susurra obtiene una pestaña junto a las demás, y el susurro también se muestra en tu pestaña principal. Desactivado, los susurros solo se muestran en la pestaña principal."
L["Each pip leans like the frames' angled ends. When off, their ends are straight."] = "Cada segmento se inclina como los extremos en diagonal de los marcos. Desactivado, sus extremos son rectos."
L["Each pip's end cut at an angle, like the health bar's."] = "El extremo de cada segmento cortado en diagonal, como el de la barra de salud."
L["Each quest's level in front of its title, like [15]."] = "El nivel de cada misión delante de su título, como [15]."
L["Each quest's title in the tracker."] = "El título de cada misión en el seguimiento."
L["Each shot hits for %.0f to %.0f before armor."] = "Cada disparo inflige de %.0f a %.0f antes de armadura."
L["Each square darkens like a clock as your spell runs out."] = "Cada cuadrado se oscurece como un reloj a medida que se agota tu hechizo."
L["Each talent set has its own layout. Edit layout and Copy from work on this one."] = "Cada conjunto de talentos tiene su propio diseño. «Editar diseño» y «Copiar desde» actúan sobre este."
L["Each text updates as it changes. Hover for details: gold on every character, each piece of gear, each bag, who's online."] = "Cada texto se actualiza al cambiar. Pasa el ratón para ver detalles: el oro de cada personaje, cada pieza de equipo, cada bolsa, quién está en línea."
L["Each threat bar in its player's class color, or all in one color."] = "Cada barra de amenaza en el color de clase de su jugador, o todas de un solo color."
L["Early start"] = "Inicio anticipado"
L["Earned"] = "Obtenido"
L["Earned this session"] = "Obtenido en esta sesión"
L["Eases class, reaction and power colors toward gray for a gentler look."] = "Atenúa los colores de clase, de reacción y de poder hacia el gris para un aspecto más suave."
