L["Enemy pets and totems get a look of their own, totems in their element's color. In battlegrounds they're all red: the game hides which totem it is. When off, the game's setting for their plates is turned off too."] = "Las mascotas y los tótems enemigos tienen un aspecto propio, los tótems en el color de su elemento. En campos de batalla son todos rojos: el juego oculta de qué tótem se trata. Desactivado, también se desactiva el ajuste del juego para sus placas de nombre."
L["Enemy plates: the health bar, the name under it, casts, your debuffs and crowd control. Friendly plates are simpler."] = "Placas de nombre enemigas: la barra de salud, el nombre debajo, los lanzamientos, tus perjuicios y el control de masas. Las placas de nombre aliadas son más sencillas."
