L["Enter or Space"] = "Intro o Espacio"
L["Enter says yes when someone asks you something: a group invite, a shared quest, a summon, a resurrect. Never on anything that binds, rolls or costs, and never in combat. Making an inn your home takes your Accept key too."] = "Intro responde sí cuando alguien te pide algo: una invitación de grupo, una misión compartida, una invocación, una resurrección. Nunca en lo que vincula, tira dados o cuesta algo, y nunca en combate. Hacer de una posada tu hogar también usa tu tecla de aceptar."
L["Entering and leaving combat"] = "Entrar y salir de combate"
L["Epic (purple) and up"] = "Épico (morado) y superiores"
