L["Every area's fade in one place: in combat, on mouseover, or always shown."] = "El desvanecimiento de cada zona en un solo lugar: en combate, al pasar el ratón o siempre visible."
L["Every bag in one window, with search, sorting and categories."] = "Todas las bolsas en una sola ventana, con búsqueda, orden y categorías."
L["Every color in the quest tracker."] = "Todos los colores del seguimiento de misiones."
L["Every debuff on you, over your frame. Off by default: your buff bars show them too."] = "Todos los perjuicios sobre ti, encima de tu marco. Desactivado por defecto: tus barras de beneficios también los muestran."
L["Every empty slot"] = "Cada ranura vacía"
L["Every font"] = "Todas las fuentes"
L["Every hand's bar in your class color, or your class's gradient with a two-color fill. A queued attack keeps its own color. Not with the Daylight gradient."] = "La barra de cada mano en el color de tu clase, o el degradado de tu clase con un relleno de dos colores. Un ataque en cola conserva su propio color. No con el degradado Daylight."
L["Every header in this one color."] = "Todos los encabezados en este único color."
L["Every health bar's color when Health bar color is One color."] = "Color de todas las barras de salud cuando «Color de la barra de salud» está en «Un color»."
L["Every item you dragged onto a group, or moved with Alt-right-click, goes back to its own group."] = "Cada objeto que arrastraste a un grupo, o que moviste con Alt+clic derecho, vuelve a su propio grupo."
L["Every line in the tooltips. General uses the font on General > Appearance."] = "Todas las líneas de los avisos emergentes. «General» usa la fuente de General > Apariencia."
L["Every line stays until the newest one's time is up, then they all go. When off, each line leaves on its own."] = "Todas las líneas permanecen hasta que expira la más reciente, y luego desaparecen todas. Desactivado, cada línea se va por sí sola."
L["Every other row on a faint stripe, in the stats and the long lists, so lines are easier to follow."] = "Una de cada dos filas con rayas tenues, en las estadísticas y en las listas largas, para seguir mejor las líneas."
L["Every part of DaylightUI and what it does. Switch off any you don't want; that applies when you reload."] = "Cada parte de DaylightUI y lo que hace. Desactiva las que no quieras; se aplica al recargar."
L["Every part's fade in one place. Each is the same setting as on that part's own page."] = "El desvanecimiento de cada parte en un solo lugar. Cada uno es el mismo ajuste que en la sección propia de esa parte."
L["Every power bar's color when Power bar color is One color."] = "Color de todas las barras de poder cuando «Color de la barra de poder» está en «Un color»."
L["Every quest in your log"] = "Todas las misiones de tu registro"
L["Every quest title's color while Quest title color is set to One color."] = "Color de todos los títulos de misión mientras «Color del título de misión» esté en «Un color»."
L["Every reward earned."] = "Cada recompensa obtenida."
L["Every setting for this piece"] = "Todos los ajustes de esta pieza"
L["Every text in the loot feed. General uses the font on General > Appearance."] = "Todos los textos del flujo de botín. «General» usa la fuente de General > Apariencia."
L["Every text in the quest tracker. General uses the font on General > Appearance."] = "Todos los textos del seguimiento de misiones. «General» usa la fuente de General > Apariencia."
L["Every texture"] = "Todas las texturas"
L["Every tracked quest, only the zone you're in, or every quest in your log without tracking them. The controls over the list switch the first two."] = "Todas las misiones seguidas, solo la zona en la que estás, o todas las misiones de tu registro sin seguirlas. Los controles sobre la lista alternan entre las dos primeras."
