L["Fade out of combat"] = "Desvanecer fuera de combate"
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP)."] = "Desvanecer fuera de combate: se desvanece un momento después de un combate y vuelve en combate. Desvanecer en combate: se desvanece un momento después de empezar un combate y vuelve después. Desvanecer hasta el paso del ratón: permanece desvanecido hasta que pasas el ratón por encima. Solo al cambiar algo: desaparece fuera de combate, vuelve en combate y reaparece un instante cuando algo cambia (un beneficio ganado o perdido, tu salud, el progreso de una misión, experiencia)."
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP). Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = "Desvanecer fuera de combate: se desvanece un momento después de un combate y vuelve en combate. Desvanecer en combate: se desvanece un momento después de empezar un combate y vuelve después. Desvanecer hasta el paso del ratón: permanece desvanecido hasta que pasas el ratón por encima. Solo al cambiar algo: desaparece fuera de combate, vuelve en combate y reaparece un instante cuando algo cambia (un beneficio ganado o perdido, tu salud, el progreso de una misión, experiencia). Oculto (en combate, fuera de combate o siempre): desaparece, y sus botones no se pueden pulsar."
L["Fade the UI while talking"] = "Desvanecer la interfaz al hablar"
L["Fade the icon"] = "Desvanecer el icono"
L["Fade to"] = "Desvanecer hasta"
L["Fade until mouseover"] = "Desvanecer hasta el paso del ratón"
L["Fade when out of range"] = "Desvanecer fuera de alcance"
L["Faded opacity"] = "Opacidad desvanecida"
L["Fades only while your health is full; comes back as soon as it drops. Show on mouseover still works."] = "Se desvanece solo mientras tu salud esté completa; vuelve en cuanto baje. «Mostrar al pasar el ratón» sigue funcionando."
L["Fades only while your pet's health is full; comes back as soon as it drops. Show on mouseover still works."] = "Se desvanece solo mientras la salud de tu mascota esté completa; vuelve en cuanto baje. «Mostrar al pasar el ratón» sigue funcionando."
