L["Game default sends the numbers straight up. Soft drifts them out to the sides, Punchy flings them wide off the target, Clean keeps them tight and close, out of the way in a raid. Moving a slider below makes it Custom."] = "«Predeterminado del juego» envía los números directamente hacia arriba. «Suave» los hace derivar hacia los lados, «Contundente» los lanza lejos del objetivo, «Limpio» los mantiene juntos y cerca, discretos en banda. Mover un control deslizante de abajo lo cambia a «Personalizado»."
