L["Hide shows the spell only while it's on cooldown. It keeps its gap: the other spells don't move."] = "«Ocultar» muestra el hechizo solo mientras está en reutilización. Mantiene su hueco: los demás hechizos no se mueven."
L["Hide shows the spell only while it's on cooldown. Only when usable shows it once you can cast it: Riposte after a parry, Overpower after a dodge, Execute on a low target. Both keep the gap: the other spells don't move."] = "«Ocultar» muestra el hechizo solo mientras está en reutilización. «Solo si es utilizable» lo muestra en cuanto puedes lanzarlo: Contraataque tras una parada, Abrumar tras una esquiva, Ejecutar sobre un objetivo con poca salud. Ambas opciones mantienen el hueco: los demás hechizos no se mueven."
L["Hide while mounted"] = "Ocultar montado"
L["Hides the higher raid groups, e.g. 4 for a 20-player raid."] = "Oculta los grupos de banda superiores, p. ej. 4 para una banda de 20 jugadores."
L["Hides the number while a minute or more is left, so long buffs stay quiet."] = "Oculta el número mientras quede un minuto o más, para que los beneficios largos se mantengan discretos."
L["Hides the red text and voice line from pressing a button too soon: not enough rage, mana or energy, not ready yet, out of range, no target. The useful ones still show: bags full, interrupted, line of sight, quest messages."] = "Oculta el texto rojo y la línea de voz al pulsar un botón demasiado pronto: no hay suficiente ira, maná o energía, todavía no está listo, fuera de alcance, sin objetivo. Los mensajes útiles siguen mostrándose: bolsas llenas, interrumpido, línea de visión, mensajes de misión."
L["Hiding"] = "Ocultación"
