L["Hostile"] = "Hostil"
L["Hover a button and press a key to bind it, or Escape to clear it. Click Okay when you're done. Out of combat only."] = "Pasa el ratón sobre un botón y pulsa una tecla para asignarla, o Esc para borrarla. Haz clic en «Aceptar» cuando termines. Solo fuera de combate."
L["Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "Pasa el ratón sobre un ajuste para ver qué hace; la flecha junto a un ajuste modificado lo restablece."
L["Hover delay (seconds)"] = "Retardo al pasar el ratón (segundos)"
L["Hover it for buttons: the fight (overall, current, and earlier fights by name), the mode, and reset."] = "Pasa el ratón por encima para ver los botones: el combate (total, actual y combates anteriores por nombre), el modo y restablecer."
L["Hovering a Questie icon on the map or minimap, or a quest in the quest log, makes that quest's icons a little bigger and fades the other quests' icons."] = "Pasar el ratón sobre un icono de Questie en el mapa o en el minimapa, o sobre una misión en el registro de misiones, hace que los iconos de esa misión se agranden un poco y desvanece los de las demás misiones."
L["Hovering a quest in the quest log shows its tooltip beside the log, as the game's own log does. Off shows it at the mouse."] = "Pasar el ratón sobre una misión en el registro de misiones muestra su descripción emergente junto al registro, como lo hace el propio registro del juego. Desactivado, se muestra junto al ratón."
L["Hovering an item, spell or quest link in chat shows its tooltip, just above the chat."] = "Pasar el ratón sobre un enlace de objeto, hechizo o misión en el chat muestra su descripción emergente, justo encima del chat."
L["Hovering an item, spell or quest link in chat shows its tooltip. Off, clicking a link still opens it."] = "Pasar el ratón sobre un enlace de objeto, hechizo o misión en el chat muestra su descripción emergente. Desactivado, al hacer clic en un enlace se sigue abriendo."
L["How big a crit on you pops. It starts at half this and settles back. The game's own is 60."] = "Tamaño con el que aparece un crítico contra ti. Empieza a la mitad de este valor y luego vuelve. El del juego es 60."
L["How big each buff icon is."] = "Tamaño de cada icono de beneficio."
L["How big each debuff icon is."] = "Tamaño de cada icono de perjuicio."
L["How big each icon is."] = "Tamaño de cada icono."
L["How big each item slot is in the Bank and alts window."] = "Tamaño de cada espacio de objeto en la ventana de Banco y personajes."
L["How big each item slot is in the bag."] = "Tamaño de cada espacio de objeto en la bolsa."
L["How big each item slot is in the bank."] = "Tamaño de cada espacio de objeto en el banco."
L["How big every square is."] = "Tamaño de cada cuadrado."
L["How big it is, as a percent of its normal size. This is Edit Mode's own size setting, kept in your Edit Mode layout."] = "Su tamaño, como porcentaje de su tamaño normal. Es el ajuste de tamaño propio del Modo de edición, guardado en tu diseño del Modo de edición."
L["How big the PvP flag is."] = "Tamaño del indicador JcJ."
L["How big the arrow is on your screen, yards text included."] = "Tamaño de la flecha en pantalla, con el texto de los metros incluido."
L["How big the clock is."] = "Tamaño del reloj."
L["How big the corner crown is."] = "Tamaño de la corona de la esquina."
L["How big the crowd control icon is."] = "Tamaño del icono de control de masas."
L["How big the data texts are."] = "Tamaño de los textos de datos."
L["How big the dispellable debuff's icon is."] = "Tamaño del icono del perjuicio disipable."
L["How big the framerate is."] = "Tamaño de la visualización de fotogramas por segundo."
L["How big the health text is on this frame."] = "Tamaño del texto de salud en este marco."
L["How big the health text on the tiles is."] = "Tamaño del texto de salud en las fichas."
L["How big the icons of buffs you can purge or steal are."] = "Tamaño de los iconos de los beneficios que puedes purgar o robar."
L["How big the item names, counts and skill-up text are in the loot feed."] = "Tamaño de los nombres de objeto, las cantidades y el texto de subida de habilidad en el flujo de botín."
L["How big the large health number is."] = "Tamaño del número de salud grande."
L["How big the leader crown is."] = "Tamaño de la corona de líder."
L["How big the leader's crown is."] = "Tamaño de la corona del líder."
L["How big the name is on this frame."] = "Tamaño del nombre en este marco."
L["How big the names on the tiles are."] = "Tamaño de los nombres en las fichas."
L["How big the pets' health text is."] = "Tamaño del texto de salud de las mascotas."
L["How big the pets' names are."] = "Tamaño de los nombres de las mascotas."
L["How big the portrait ring is next to the frame's height."] = "Tamaño del anillo del retrato en relación con la altura del marco."
L["How big the quest marker is in the world, distance text included."] = "Tamaño del marcador de misión en el mundo, con el texto de distancia incluido."
L["How big the raid marker is."] = "Tamaño del marcador de banda."
L["How big the ready check answer is."] = "Tamaño de la respuesta a la comprobación de listos."
