L["How big the square minimap is."] = "Tamaño del minimapa cuadrado."
L["How big the window is."] = "Tamaño de la ventana."
L["How big the window is. Other windows still open beside it when they fit."] = "Tamaño de la ventana. Las demás ventanas siguen abriéndose a su lado cuando caben."
L["How big this extra text is."] = "Tamaño de este texto adicional."
L["How big your buff icons on friendly plates are."] = "Tamaño de tus iconos de beneficio en las placas de nombre aliadas."
L["How big your debuff icons are."] = "Tamaño de tus iconos de perjuicio."
L["How bright the light behind the arrow is."] = "Luminosidad de la luz detrás de la flecha."
L["How bright the pips you haven't filled are, as a share of their color. Lower makes the filled ones stand out more."] = "Luminosidad de los puntos no llenados, en proporción a su color. Más bajo hace que los llenos destaquen más."
L["How bright the unexplored areas are. At 100% they look like the parts you've explored."] = "Luminosidad de las zonas no exploradas. Al 100%, se ven como las partes exploradas."
L["How dark the shade that sweeps over a button on cooldown is."] = "Oscuridad de la sombra que barre un botón en reutilización."
L["How dark the shadow around DaylightUI's frames and windows is."] = "Oscuridad de la sombra alrededor de los marcos y ventanas de DaylightUI."
L["How each hand's bar is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per hand, set right here. A queued attack always keeps its own color."] = "Cómo se rellena la barra de cada mano: un color para cada una, el degradado Daylight (del azul al naranja del logotipo), o un degradado de dos colores por mano, configurado aquí. Un ataque en cola conserva siempre su propio color."
L["How every cast bar (yours, target's, focus's) is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per kind of cast, set right here."] = "Relleno de cada barra de lanzamiento (la tuya, la del objetivo, la del foco): un color para cada una, el degradado Daylight (del azul al naranja del logotipo), o un degradado de dos colores por tipo de lanzamiento, configurado aquí."
L["How far above the cursor the tooltip's corner sits (below zero: lower down)."] = "Distancia de la esquina de la descripción emergente por encima del cursor (bajo cero: más abajo)."
L["How far along that quest objective is (4/10, or 45%), small, beside the !."] = "Progreso de ese objetivo de misión (4/10, o 45%), en pequeño, junto a la !."
L["How far away plates show, in yards. 60 is the most the game allows."] = "Distancia a la que se muestran las placas de nombre, en metros. 60 es el máximo que permite el juego."
L["How far away the spot is."] = "Distancia hasta el punto."
L["How far from the target the numbers start."] = "Distancia del objetivo a la que empiezan los números."
L["How far it fades. At 0 it disappears fully. Never more than Opacity."] = "Intensidad del desvanecimiento. A 0, desaparece por completo. Nunca más que «Opacidad»."
L["How far past the name and bar a click still selects the unit."] = "Distancia más allá del nombre y de la barra en la que un clic todavía selecciona la unidad."
L["How far right of the cursor the tooltip's corner sits (below zero: to the left)."] = "Distancia de la esquina de la descripción emergente a la derecha del cursor (bajo cero: a la izquierda)."
L["How far the camera can zoom out. 100% is the game's normal limit; the far right end is as far as this client allows. At 100% the game's own setting is left alone."] = "Distancia máxima de alejamiento de la cámara. El 100% es el límite normal del juego; el extremo derecho es lo máximo que permite este cliente. Al 100%, no se modifica el ajuste propio del juego."
L["How far the frames' angled ends lean, on every unit frame and cast bar. 21% is the usual look."] = "Inclinación de los extremos biselados de los marcos de unidad y de las barras de lanzamiento. El 21% es el aspecto habitual."
L["How far the name tab's shadow spreads. 0 leaves no shadow."] = "Extensión de la sombra de la pestaña del nombre. 0 no deja sombra."
L["How far the numbers fly out to the sides. At 0 they go straight up, the game's own way."] = "Distancia a la que salen los números hacia los lados. A 0, suben recto, como en el propio juego."
L["How far the panel reaches past the buttons on every side."] = "Margen que el panel sobrepasa los botones por cada lado."
L["How far the soft shadow around DaylightUI's frames and windows reaches."] = "Extensión de la sombra suave alrededor de los marcos y ventanas de DaylightUI."
L["How far this frame's shadow spreads. 0 leaves no shadow."] = "Extensión de la sombra de este marco. 0 no deja sombra."
L["How far through the level you are, e.g. 24%. With the numbers on too, it sits between them and the rested XP."] = "Tu progreso dentro del nivel, p. ej. 24%. Si los números también están activados, se coloca entre ellos y la experiencia de descanso."
L["How far through the standing you are, e.g. 60%."] = "Tu progreso dentro de la reputación, p. ej. 60%."
L["How health and power numbers are written on unit frames, extra texts and nameplates. Percents stay as they are."] = "Formato de los números de salud y de poder en los marcos de unidad, los textos adicionales y las placas de nombre. Los porcentajes no cambian."
L["How long a line stays on screen before it fades away."] = "Tiempo que una línea permanece en pantalla antes de desvanecerse."
L["How long a new item stays in Recent before it goes to its own group."] = "Tiempo que un objeto nuevo permanece en «Reciente» antes de pasar a su propio grupo."
L["How long a new whisper's preview stays."] = "Tiempo que permanece la vista previa de un nuevo susurro."
L["How long each buff and debuff has left, on the top edge of its icon."] = "Tiempo restante de cada beneficio y perjuicio, en el borde superior de su icono."
L["How long each line stays after your last loot of it."] = "Tiempo que cada línea permanece tras tu último botín de ese tipo."
L["How long it stays before fading, unless the buffs land first."] = "Tiempo que permanece antes de desvanecerse, salvo que antes lleguen los beneficios."
L["How long the mouse rests on a link before its tooltip shows, so sweeping across the chat leaves it quiet."] = "Tiempo que el ratón debe quedarse sobre un enlace antes de mostrar su descripción emergente, para que recorrer el chat no moleste."
L["How low the enemy's health has to be."] = "Salud máxima que debe tener el enemigo."
L["How many bars sit on your screen. Each one can be changed on its own later."] = "Número de barras en pantalla. Cada una podrá modificarse por separado más adelante."
L["How many buttons this bar shows."] = "Número de botones que muestra esta barra."
L["How many data texts share the strip. Pick what each shows under Slots."] = "Número de textos de datos que comparten la franja. Elige lo que muestra cada uno en «Espacios»."
L["How many of the newest messages per chat tab come back after /reload."] = "Número de mensajes más recientes por pestaña de chat que se recuperan tras /reload."
L["How many people's tiles slide out beside the chat at most."] = "Número máximo de fichas de personas que se despliegan junto al chat."
L["How many rows the buttons wrap into (columns when the bar is vertical)."] = "Número de filas en las que se reparten los botones (columnas si la barra es vertical)."
L["How many slots fit in each row of the bag. More columns make it wider and shorter."] = "Número de espacios por fila de la bolsa. Más columnas la hacen más ancha y menos alta."
L["How many yards away it is."] = "Distancia en metros."
L["How much a block, absorb or resist saved you."] = "Lo que te ahorró un bloqueo, una absorción o una resistencia."
L["How much color the empty part of a bar keeps."] = "Cantidad de color que conserva la parte vacía de una barra."
L["How much of the health bar's width the row spans, centered."] = "Parte del ancho de la barra de salud que ocupa la fila, centrada."
L["How much the shield can still soak, at the bar's right end."] = "Cuánto puede absorber todavía el escudo, en el extremo derecho de la barra."
L["How much the shield can still soak, on the icon in place of its time. Its size and color are the cooldown numbers'."] = "Cuánto puede absorber todavía el escudo, en el icono en lugar de su duración. Su tamaño y color son los de los números de reutilización."
L["How objective lines show their progress: in the colors below, green once done, or shading from red to green as the count fills."] = "Forma en que las líneas de objetivo muestran su progreso: en los colores de abajo, en verde una vez completadas, o degradando del rojo al verde a medida que se llena el contador."
L["How round the name tab's corners are. 0 keeps them sharp."] = "Redondez de las esquinas de la pestaña del nombre. 0 las mantiene rectas."
L["How round this frame's corners are. 0 keeps them sharp."] = "Redondez de las esquinas de este marco. 0 las mantiene rectas."
L["How see-through a frame gets while its unit is out of range."] = "Transparencia de un marco cuando su unidad está fuera de alcance."
L["How see-through a spell set to Fade gets, ready or on cooldown."] = "Transparencia de un hechizo configurado en «Desvanecer», listo o en reutilización."
L["How see-through a spell set to Fade gets."] = "Transparencia de un hechizo configurado en «Desvanecer»."
L["How see-through a spell's icon is while it's on cooldown. The global cooldown doesn't count."] = "Transparencia del icono de un hechizo mientras está en reutilización. El tiempo de reutilización global no cuenta."
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, and chat, the info panel, the quest box and the buff bars unless they have a separate one on their pages."] = "Transparencia de cada ventana y panel: bolsas, personaje, libro de hechizos, PNJ, buscador de grupos, las ventanas del juego que restilizamos, además del chat, el panel de información, el cuadro de misiones y las barras de beneficios, salvo que tengan un ajuste propio en su sección."
L["How see-through it is while shown, whatever the fade does."] = "Transparencia cuando se muestra, sea cual sea el desvanecimiento."
L["How see-through it is, when it fades and how far. Unlocked, in test mode or with this page open, it shows at its opacity."] = "Su transparencia, cuándo se desvanece y hasta dónde. Desbloqueado, en modo de prueba o con esta sección abierta, se muestra con su opacidad."
L["How see-through party and raid frames get while a member is out of range."] = "Transparencia de los marcos de grupo y de banda cuando un miembro está fuera de alcance."
L["How see-through the borders around DaylightUI's frames and windows are."] = "Transparencia de los bordes alrededor de los marcos y ventanas de DaylightUI."
L["How see-through the info panel's boxes and the meters' own windows are."] = "Transparencia de las cajas del panel de información y de las ventanas propias de los medidores."
L["How see-through the other plates get while you have a target."] = "Transparencia de las demás placas de nombre cuando tienes un objetivo."
L["How see-through the world map's symbols are. Lower it to see more of the map under them."] = "Transparencia de los símbolos del mapa del mundo. Bájala para ver más del mapa que hay debajo."
L["How should it look?"] = "¿Qué aspecto debe tener?"
L["How solid its background is: 0 is fully see-through."] = "Opacidad de su fondo: 0 es totalmente transparente."
L["How solid the dark background is."] = "Opacidad del fondo oscuro."
L["How solid the quest log's background is. Lower lets the world show through behind the list."] = "Opacidad del fondo del registro de misiones. Más bajo deja ver el mundo tras la lista."
L["How solid the ribbon behind each loot feed line is: 0 is fully see-through."] = "Opacidad de la cinta tras cada línea del flujo de botín: 0 es totalmente transparente."
L["How strong the highlight on an active spell is."] = "Intensidad del resaltado de un hechizo activo."
L["How strong the mouseover color over the icon is."] = "Intensidad del color al pasar el ratón sobre el icono."
L["How strong the pressed color over the icon is."] = "Intensidad del color al pulsar sobre el icono."
L["How strongly it lights up once the enemy is in range."] = "Intensidad con la que se ilumina cuando el enemigo está al alcance."
L["How strongly the debuff's color tints the health bar. Only for a Tint or Both highlight."] = "Intensidad con la que el color del perjuicio tiñe la barra de salud. Solo para un resaltado «Tinte» o «Ambos»."
L["How strongly the spell cost shows on your power bar."] = "Intensidad con la que se muestra el coste del hechizo en tu barra de poder."
L["How tall a friendly plate's health bar is."] = "Altura de la barra de salud de una placa de nombre aliada."
L["How tall each enemy plate's health bar is."] = "Altura de la barra de salud de cada placa de nombre enemiga."
L["How tall each line of text over you is. The game's own is 25."] = "Altura de cada línea de texto sobre ti. La del juego es 25."
L["How tall each of the threat meter's bars is."] = "Altura de cada barra del medidor de amenaza."
L["How tall each of this meter's bars is."] = "Altura de cada barra de este medidor."
L["How tall each pet bar is."] = "Altura de cada barra de mascota."
L["How tall each quest's row is in the quest log. Larger text keeps enough room however low this is set."] = "Altura de cada fila de misión en el registro de misiones. Un texto más grande conserva espacio suficiente, aunque este valor esté muy bajo."
L["How tall each raid tile is."] = "Altura de cada casilla de banda."
L["How tall each swing timer bar is."] = "Altura de cada barra del tiempo de golpes."
L["How tall each tile's power bar is."] = "Altura de la barra de poder de cada casilla."
L["How tall every other plate's health bar is while you have a target, as a share of Health bar height."] = "Altura de la barra de salud de las demás placas de nombre mientras tengas un objetivo, como proporción de «Altura de la barra de salud»."
L["How tall the cast bar under an enemy plate is."] = "Altura de la barra de lanzamiento bajo una placa de nombre enemiga."
L["How tall the experience bar is."] = "Altura de la barra de experiencia."
L["How tall the health bar is."] = "Altura de la barra de salud."
L["How tall the health bar under the tooltip is."] = "Altura de la barra de salud bajo la descripción emergente."
L["How tall the meter's own window is."] = "Altura de la ventana del medidor."
L["How tall the pets' power bars are."] = "Altura de las barras de poder de las mascotas."
L["How tall the power bar is."] = "Altura de la barra de poder."
L["How tall the reputation bar is."] = "Altura de la barra de reputación."
L["How tall the second meter's window is."] = "Altura de la ventana del segundo medidor."
L["How tall the tab holding the name above the frame is."] = "Altura de la pestaña que contiene el nombre sobre el marco."
L["How tall this frame is."] = "Altura de este marco."
L["How tall your cast bar is."] = "Altura de tu barra de lanzamiento."
L["How tall your focus's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Altura de la barra de lanzamiento de tu foco. No dentro del marco, donde ocupa el lugar de la barra de poder."
L["How tall your target's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Altura de la barra de lanzamiento de tu objetivo. No dentro del marco, donde ocupa el lugar de la barra de poder."
L["How tall your target's health bar is, as a share of Health bar height."] = "Altura de la barra de salud de tu objetivo, como proporción de «Altura de la barra de salud»."
L["How the health text on friendly plates reads: a percent, the health itself, health out of max, both, or what's missing."] = "Formato del texto de salud en las placas de nombre aliadas: un porcentaje, la salud en sí, la salud sobre el máximo, ambas o lo que falta."
L["How the health text reads: a percent, the health itself, health out of max, both, or what's missing."] = "Formato del texto de salud: un porcentaje, la salud en sí, la salud sobre el máximo, ambas o lo que falta."
L["How the pets' health text is written."] = "Formato del texto de salud de las mascotas."
L["How the power text is written."] = "Formato del texto de poder."
L["How the tiles' health text is written. Missing health shows nothing while the member is at full."] = "Formato del texto de salud de las casillas. «Salud que falta» no muestra nada cuando el miembro tiene la salud al máximo."
L["How thick the border around each button is."] = "Grosor del borde alrededor de cada botón."
L["How thick the name tab's outline is. 0 leaves none."] = "Grosor del contorno de la pestaña del nombre. 0 no muestra ninguno."
L["How this category's buffs are edged: one color or a gradient. Click to change."] = "Borde de los beneficios de esta categoría: un color o un degradado. Haz clic para cambiarlo."
L["How this extra text writes the health."] = "Formato de los puntos de salud en este texto adicional."
L["How this extra text writes the power."] = "Formato del poder en este texto adicional."
L["How wide a friendly plate's health bar is."] = "Anchura de la barra de salud de una placa de nombre aliada."
L["How wide each combo point pip is. Not while the pips match the frame's width."] = "Anchura de cada punto de combo. No mientras los puntos se ajusten a la anchura del marco."
L["How wide each enemy plate's health bar is."] = "Anchura de la barra de salud de cada placa de nombre enemiga."
L["How wide each pet bar is."] = "Anchura de cada barra de mascota."
L["How wide each raid tile is."] = "Anchura de cada casilla de banda."
L["How wide every other plate is while you have a target, as a share of Width."] = "Anchura de las demás placas de nombre mientras tengas un objetivo, como proporción de «Anchura»."
L["How wide the bars are."] = "Anchura de las barras."
L["How wide the damage meter is, in the panel or in its own window."] = "Anchura del medidor de daño, en el panel o en su propia ventana."
L["How wide the list is."] = "Anchura de la lista."
L["How wide the name tab is when Name tab width is Fixed width."] = "Anchura de la pestaña del nombre cuando «Anchura de la pestaña del nombre» está en Anchura fija."
L["How wide the reputation bar is. Dragging its corner in unlock mode sets this too."] = "Anchura de la barra de reputación. Arrastrar su esquina en el modo de desbloqueo también la ajusta."
L["How wide the second meter's window is. Dragging its corner in unlock mode sets this too."] = "Anchura de la ventana del segundo medidor. Arrastrar su esquina en el modo de desbloqueo también la ajusta."
L["How wide the separate experience bar is. Dragging its corner in unlock mode sets this too."] = "Anchura de la barra de experiencia separada. Arrastrar su esquina en el modo de desbloqueo también la ajusta."
L["How wide the threat meter is."] = "Anchura del medidor de amenaza."
L["How wide this frame is."] = "Anchura de este marco."
L["How wide your focus's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Anchura de la barra de lanzamiento de tu foco. No dentro del marco, ni mientras coincida con la anchura del marco."
L["How wide your target's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Anchura de la barra de lanzamiento de tu objetivo. No dentro del marco, ni mientras coincida con la anchura del marco."
L["How wide your target's plate is, as a share of Width."] = "Anchura de la placa de nombre de tu objetivo, como proporción de «Anchura»."
L["How you find your way to quests, and how they show in the tracker."] = "Cómo encuentras el camino a las misiones y cómo aparecen en el seguimiento."
L["How you find your way to quests, how they show in the tracker, and how talking to NPCs looks."] = "Cómo encuentras el camino a las misiones, cómo aparecen en el seguimiento y qué aspecto tiene hablar con los PNJ."
L["How your target's plate stands out from the rest."] = "Cómo destaca la placa de nombre de tu objetivo frente a las demás."
L["Hunter"] = "Cazador"
L["Hunters: a line on the ranged bar where Auto Shot's wind-up starts, adjusted for haste and your ping. Moving past it holds the shot back, so the bar stays full and says Stop moving until you stand still."] = "Cazadores: una línea en la barra de distancia donde empieza la preparación de Disparo automático, ajustada según la celeridad y tu latencia. Moverte más allá la retiene: la barra se mantiene llena y dice «Deja de moverte» hasta que te quedes quieto."
L["I'd like to train."] = "Quiero instruirme."
L["I'm away right now, I'll get back to you soon."] = "Estoy ausente ahora mismo, te responderé pronto."
L["INTERRUPTS"] = "INTERRUPCIONES"
L["Icon"] = "Icono"
L["Icon (the game's)"] = "Icono (el del juego)"
L["Icon look"] = "Aspecto de los iconos"
L["Icon per class"] = "Icono por clase"
L["Icon positions and sizes"] = "Posiciones y tamaños de los iconos"
L["Icon size"] = "Tamaño de los iconos"
L["Icon style"] = "Estilo de los iconos"
L["Icon zoom"] = "Zoom de los iconos"
L["Icons fill from the bar's right edge leftward, toward the middle of the screen."] = "Los iconos se llenan desde el borde derecho de la barra hacia la izquierda, hacia el centro de la pantalla."
L["Icons left / right"] = "Iconos izquierda / derecha"
L["Icons on a row before it wraps to the next."] = "Iconos en una fila antes de pasar a la siguiente."
L["Icons on bars"] = "Iconos en las barras"
L["Icons per row"] = "Iconos por fila"
L["Icons up / down"] = "Iconos arriba / abajo"
L["Idle time (seconds)"] = "Tiempo de inactividad (segundos)"
L["Ignore"] = "Ignorar"
L["Ignored"] = "Ignorado"
L["Immersive"] = "Inmersivo"
L["Immersive Preset"] = "Preajuste inmersivo"
L["Import"] = "Importar"
L["Import a Cooldown Manager layout"] = "Importar un diseño del gestor de reutilización"
L["Import profile"] = "Importar perfil"
L["Imported"] = "Importado"
L["Imported the Cooldown Manager profile %s, used by talent set %d."] = "Importado el perfil del gestor de reutilización %s, usado por el conjunto de talentos %d."
L["Imported the profile %s."] = "Perfil %s importado."
L["In a dungeon or raid"] = "En mazmorra o banda"
L["In a fight"] = "En combate"
L["In a group or with a pet, a small tag on the frame's top inner corner: your threat on it, where 100% means it turns on you. Orange as you get close, red once it's on you."] = "En grupo o con una mascota, una pequeña etiqueta en la esquina interior superior del marco: tu amenaza sobre él, donde 100% significa que se vuelve contra ti. Naranja cuando te acercas, rojo cuando ya te ataca."
L["In a group, colors a mob by who it's attacking; solo plates never change. As a tank: red when it's attacking someone else, orange when you're about to lose it, normal while you hold it. As damage or healer: orange when you're close to pulling it, red once it's attacking you."] = "En grupo, colorea una criatura según a quién ataque; en solitario, las placas de nombre nunca cambian. Como tanque: rojo cuando ataca a otro, naranja cuando estás a punto de perderla, normal mientras la mantienes. Como DPS o sanador: naranja cuando estás cerca de robarle la amenaza, rojo cuando te ataca."
L["In a group or with a pet, the target's ring (and threat tag) turns this color as you get close to pulling it."] = "En grupo o con una mascota, el anillo del objetivo (y la etiqueta de amenaza) toma este color cuando te acercas a atraerlo."
L["In a raid, only the leader and assists can use the leader tools."] = "En banda, solo el líder y los asistentes pueden usar las herramientas de líder."
L["In a row above the bar."] = "En una fila sobre la barra."
L["In categories"] = "En categorías"
L["In columns"] = "En columnas"
L["In combat"] = "En combate"
L["In combat in a group or with a pet"] = "En combate en grupo o con una mascota"
L["In combat, when I'm the tank"] = "En combate, cuando soy el tanque"
L["In dungeons, raids, battlegrounds and arenas, everything set to fade stays shown, as if its fade were Never. It fades again once you're back outside."] = "En mazmorras, bandas, campos de batalla y arenas, todo lo configurado para desvanecerse se mantiene visible, como si su desvanecimiento fuera Nunca. Vuelve a desvanecerse cuando sales de nuevo al exterior."
L["In fights"] = "En combates"
L["In fights and when idle"] = "En combates y en inactividad"
L["In fights: the panel and tabs float away and the messages stay over the world. When idle: the whole chat also fades when nothing new has come in for a while. Always: no panel or tabs while you play, only messages. The mouse over the chat or pressing Enter brings it back."] = "En combates: el panel y las pestañas se ocultan y los mensajes permanecen sobre el mundo. En inactividad: todo el chat también se desvanece cuando no llega nada nuevo durante un rato. Siempre: ni panel ni pestañas mientras juegas, solo mensajes. Pasar el ratón sobre el chat o pulsar Intro lo devuelve."
L["In progress"] = "En curso"
L["In public channels (General, Trade, say...), the same words from the same person again within a minute are hidden. Guild, group and whispers are never hidden."] = "En los canales públicos (General, Comercio, decir...), las mismas palabras de la misma persona repetidas en menos de un minuto se ocultan. La hermandad, el grupo y los susurros nunca se ocultan."
L["In rows"] = "En filas"
L["In screen pixels, so it stays sharp at any UI scale. Heavy border needs 3 or more."] = "En píxeles de pantalla, para que se mantenga nítido a cualquier escala de interfaz. El borde grueso necesita 3 o más."
L["In the Daylight chat box (Chat style: Daylight)."] = "En el cuadro de chat Daylight (estilo de chat: Daylight)."
L["In the chat box, Up and Down step through what you sent. Alt+Up and Alt+Down still work as before. While the box is open, the arrow keys don't turn your character."] = "En el cuadro de texto, Arriba y Abajo recorren lo que enviaste. Alt+Arriba y Alt+Abajo siguen funcionando como antes. Mientras el cuadro esté abierto, las flechas no giran tu personaje."
L["In the group"] = "En el grupo"
L["In the info panel"] = "En el panel de información"
L["In the tooltip spot"] = "En el lugar de la descripción emergente"
L["In use"] = "En uso"
L["In use: %s"] = "En uso: %s"
L["In your accent color (Appearance), following it when it changes. When off, uses the color below."] = "En tu color de acento (Apariencia), siguiéndolo cuando cambie. Desactivado, usa el color de abajo."
L["In your bags"] = "En tus bolsas"
L["In your layout: click to move it here."] = "En tu diseño: clic para moverlo aquí."
L["In your layout: click to pick it."] = "En tu diseño: haz clic para elegirlo."
L["Inactive"] = "Inactivo"
L["Inbox"] = "Bandeja de entrada"
L["Incoming heals"] = "Sanaciones entrantes"
L["Info"] = "Info"
L["Info Panel"] = "Panel de información"
L["Info panel"] = "Panel de información"
L["Info panel background opacity"] = "Opacidad del fondo del panel de información"
L["Inner end"] = "Extremo interior"
L["Inside the frame"] = "Dentro del marco"
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode."] = "Dentro del marco cubre la barra de poder, con su mismo ancho (en el estilo Cinta se coloca bajo el marco). Encima, debajo o independiente es una barra cuyo tamaño ajustas aquí; independiente, la mueves en el modo de desbloqueo."
L["Inspect"] = "Inspeccionar"
L["Inspecting a player opens DaylightUI's window, with their gear and talents. Turn it off to use the game's window."] = "Inspeccionar a un jugador abre la ventana de DaylightUI, con su equipo y sus talentos. Desactívalo para usar la ventana del juego."
L["Install the Jiberish Fabled Icons addon to unlock more class icon styles."] = "Instala el addon Jiberish Fabled Icons para desbloquear más estilos de iconos de clase."
