L["It shows when the first meter would: the Damage meter page's \"Show only in a group\" and \"Show only in combat\" count for both. Reset clears the fights in both."] = "Se muestra cuando lo haría el primer medidor: «Mostrar solo en grupo» y «Mostrar solo en combate» de la sección Medidor de daño valen para ambos. Restablecer borra los combates de los dos."
L["It slides back once the fight ends. A click on its tab overrides this until the next fight starts or ends."] = "Vuelve a su sitio cuando termina el combate. Un clic en su pestaña anula esto hasta que empiece o termine el siguiente combate."
L["It takes a reload."] = "Requiere recargar."
L["It's %s. Just one more quest?"] = "Son las %s. ¿Una misión más?"
L["Item"] = "Objeto"
