L["Item level line"] = "Línea del nivel de objeto"
L["Item names beside icons"] = "Nombres de objetos junto a los iconos"
L["Item names in their quality color, or all white. The icon's edge keeps the quality color."] = "Nombres de objetos en el color de su calidad, o todos en blanco. El borde del icono conserva el color de calidad."
L["Item quality border"] = "Borde de calidad de objeto"
L["Items"] = "Objetos"
L["Items and loot"] = "Objetos y botín"
L["Items below this quality don't show, like gray junk."] = "Los objetos por debajo de esta calidad no se muestran, como la morralla gris."
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "Objetos ordenados en grupos por tipo. Para mover un objeto a otro grupo, arrástralo sobre el encabezado de ese grupo o haz Alt+clic derecho sobre él. Haz clic en un encabezado para plegarlo. Alt+clic derecho también bloquea un objeto para que nunca se venda ni desencante."
L["Items that are uncommon or better get a border in their quality color."] = "Los objetos de calidad poco común o superior reciben un borde con el color de su calidad."
L["Items you loot, create, buy or get from a quest."] = "Los objetos que recoges, fabricas, compras u obtienes de una misión."
L["Items your class, level or skills can't use yet, or that you already know, get a red icon, as at a vendor."] = "Los objetos que tu clase, tu nivel o tus habilidades aún no te permiten usar, o que ya conoces, tienen un icono rojo, como en un vendedor."
L["Itim"] = "Itim"
L["Its buff or debuff"] = "Su beneficio o perjuicio"
L["Its cooldown"] = "Su tiempo de reutilización"
L["Its options and My Journey windows, and its quest objective icons on the maps, each quest in its own color."] = "Sus ventanas de opciones y My Journey, y sus iconos de objetivo de misión en los mapas, cada misión en su propio color."
L["Its own fade, apart from the panel's. With this page open it shows a sample group."] = "Su propio desvanecimiento, independiente del del panel. Con esta sección abierta, se muestra un grupo de ejemplo."
L["Its own window"] = "Su propia ventana"
L["Its own window, in the bottom-right corner to start. Move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Su propia ventana, en la esquina inferior derecha al principio. Muévela en el modo de desbloqueo (/dui unlock) y arrastra su esquina para cambiar su tamaño."
L["Its owner's class"] = "La clase de su dueño"
L["Its owner's class tells at a glance whose pet it is."] = "La clase de su dueño indica de un vistazo a quién pertenece la mascota."
L["Its ring buttons in your action bar look. The ring, its spin and its options stay OPie's."] = "Sus botones de anillo toman el aspecto de tus barras de acción. El anillo, su rotación y sus opciones siguen siendo de OPie."
L["Its timer bars in your font, bar texture and border. Sizes, colors and spots stay DBM's."] = "Sus barras de temporizador con tu fuente, textura de barra y borde. Tamaños, colores y posiciones siguen siendo los de DBM."
L["BigWigs and LittleWigs"] = "BigWigs y LittleWigs"
L["Leader crown left / right"] = "Corona del líder izquierda / derecha"
L["Leader crown up / down"] = "Corona del líder arriba / abajo"
L["Nudges it sideways from its spot."] = "La desplaza lateralmente desde su posición."
L["Nudges it up or down from its spot."] = "La desplaza hacia arriba o abajo desde su posición."
L["Party pet"] = "Mascota de grupo"
L["Ready check left / right"] = "Comprobación de listos izquierda / derecha"
L["Ready check up / down"] = "Comprobación de listos arriba / abajo"
L["Role icon left / right"] = "Icono de rol izquierda / derecha"
L["Role icon up / down"] = "Icono de rol arriba / abajo"
L["Their timer bars in your font, bar texture and border, on BigWigs' Default bar style. Sizes, colors and spots stay BigWigs'."] = "Sus barras de temporizador con tu fuente, textura de barra y borde, con el estilo de barra Default de BigWigs. Tamaños, colores y posiciones siguen siendo los de BigWigs."
L["Its window, and each attunement chain drawn like the talent trees."] = "Su ventana, y cada cadena de sintonización dibujada como los árboles de talentos."
L["Jiberish Fabled Icons is installed. Pick an icon for each class below, any style or one of its specs. The first icon on each line follows the Icon style."] = "Jiberish Fabled Icons está instalado. Elige un icono para cada clase abajo, de cualquier estilo o de una de sus especializaciones. El primer icono de cada línea sigue al estilo de iconos."
L["Join a group to use the leader tools, or try them with /dui leader test."] = "Únete a un grupo para usar las herramientas de líder, o pruébalas con /dui leader test."
L["Join the DaylightUI Discord: press Ctrl+C to copy the link, then paste it in your browser."] = "Únete al Discord de DaylightUI: pulsa Ctrl+C para copiar el enlace, y luego pégalo en tu navegador."
L["Junk"] = "Chatarra"
L["Just left of the panel, level with its top, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Justo a la izquierda del panel, a la altura de su borde superior, siguiéndolo cuando el minimapa o el medidor de daño cambia de tamaño. Desactívalo para mover la barra tú mismo en el modo de desbloqueo."
L["Just left of the panel, the first row resting on its bottom edge, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Justo a la izquierda del panel, la primera fila apoyada en su borde inferior, siguiéndolo cuando el minimapa o el medidor de daño cambia de tamaño. Desactívalo para mover la barra tú mismo en el modo de desbloqueo."
