L["Lootable quest objects sparkle, and so do quest givers (the game has no setting for one alone). The game only sparkles with its outline around what you point at off, so this keeps that outline off. Turning this off puts the outline back; the sparkle may stay until you restart the game."] = "Los objetos de misión recogibles brillan, al igual que quienes dan misiones (el juego no tiene una opción solo para uno de ellos). El juego solo brilla si su contorno alrededor de lo que señalas está desactivado, así que esta opción mantiene ese contorno desactivado. Al desactivar esta opción, el contorno vuelve; el brillo puede mantenerse hasta que reinicies el juego."
