L["Offline"] = "Desconectado"
L["Okay"] = "OK"
L["Old layout: %s, set %d"] = "Diseño antiguo: %s, conjunto %d"
L["On a flight path, a bar at the top of the screen shows where you're going and the time left. Each route's time is learned the first time you fly it, for all your characters. Move it with /dui unlock."] = "Durante un vuelo, una barra en la parte superior de la pantalla muestra adónde vas y el tiempo restante. El tiempo de cada trayecto se aprende la primera vez que lo vuelas, para todos tus personajes. Muévela con /dui unlock."
L["On a ready check, and when you enter a dungeon or raid in a group, a short line shows the group buffs you don't have yet: only ones someone in your group can give. It fades once they land. Move it in unlock mode."] = "En una comprobación de disponibilidad, y al entrar en una mazmorra o banda en grupo, una línea breve muestra los beneficios de grupo que aún no tienes: solo los que alguien de tu grupo puede dar. Se desvanece cuando se aplican. Muévela en modo de desbloqueo."
L["On cooldown"] = "En reutilización"
L["On in the Healer setup. Each class has its own picks; change them below."] = "Activado en la configuración de Sanador. Cada clase tiene sus propias opciones; cámbialas abajo."
L["On its own (unlock to move)"] = "Independiente (desbloquear para mover)"
L["On its own, the power bar leaves the frame and you can move it anywhere in unlock mode, like the middle of the screen. The frame is then all health."] = "Independiente, la barra de poder sale del marco y puedes moverla a cualquier lugar en modo de desbloqueo, por ejemplo al centro de la pantalla. El marco muestra entonces solo la salud."
L["On the plate"] = "En la placa de nombre"
L["On the portrait"] = "En el retrato"
L["On the portrait rings of the player, target and focus frames."] = "En los anillos de retrato de los marcos del jugador, del objetivo y del foco."
L["One click sets where the auras and the name sit. Change anything after."] = "Un clic define dónde van las auras y el nombre. Cambia lo que quieras después."
L["One color"] = "Un color"
L["One color on every pip; colors shading from Combo point color to Full color along the row; your class color; or two-color pairs from the Gradients page (Combo points), one for all pips or one each. Your nameplates' combo points use the same colors."] = "Un color en cada punto; colores que van de «Color de los puntos de combo» a «Color completo» a lo largo de la fila; el color de tu clase; o pares de dos colores de la sección Degradados (Puntos de combo), uno para todos los puntos o uno para cada uno. Los puntos de combo de tus placas de nombre usan los mismos colores."
L["One custom color, the accent, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Un color personalizado, el de acento, el color de tu clase, o los dos colores de tu clase como degradado (de la sección Degradados)."
L["One custom color, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Un color personalizado, el color de tu clase, o los dos colores de tu clase como degradado (de la sección Degradados)."
L["One gradient (Gradients page)"] = "Un degradado (sección Degradados)"
L["One more thing at the end of the same line, after the second part."] = "Un elemento más al final de la misma línea, tras la segunda parte."
L["One row per group member and your pet on your target's threat list, highest first, with you always in it. The percent is of the pull: at 100% it turns on you."] = "Una fila por miembro del grupo y por tu mascota en la lista de amenaza de tu objetivo, de mayor a menor, siempre con tu personaje incluido. El porcentaje se refiere al umbral de atracción: al 100 %, se vuelve contra ti."
L["One switch per part of the game's windows."] = "Un interruptor por cada parte de las ventanas del juego."
L["One tile with the count"] = "Una casilla con el número"
L["One tile: each section of the bank shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "Una casilla: cada sección del banco muestra un único espacio vacío con el número de espacios libres. Suelta un objeto sobre ella para guardarlo ahí."
L["One tile: each section shows a single empty slot with the free count on it."] = "Una casilla: cada sección muestra un único espacio vacío con el número de espacios libres."
L["One tile: each section shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "Una casilla: cada sección muestra un único espacio vacío con el número de espacios libres. Suelta un objeto sobre ella para guardarlo ahí."
L["Ones that matter in a fight"] = "Los que importan en combate"
L["Online"] = "En línea"
L["Only at full health"] = "Solo con salud completa"
L["Only clears this list. Moved buffs stay in their new categories."] = "Solo borra esta lista. Los beneficios movidos permanecen en sus nuevas categorías."
L["Only debuffs I can dispel"] = "Solo los perjuicios que puedo disipar"
L["Only enemies"] = "Solo enemigos"
L["Only in a group"] = "Solo en grupo"
L["Only in combat"] = "Solo en combate"
L["Only mine"] = "Solo los míos"
L["Only ones I can dispel"] = "Solo los que puedo disipar"
L["Only spells you cast can be bound."] = "Solo se pueden asignar los hechizos que lanzas."
L["Only the chat's messages stay over the world, each fading after a while, like Floating chat (Chat > Floating). It stays even with Fade everything at the campfire on."] = "Solo los mensajes del chat permanecen sobre el mundo, y cada uno se desvanece tras un rato, como el chat flotante (Chat > Flotante). Sigue así incluso con «Desvanecer todo en la hoguera» activado."
L["Only the debuffs you put on it, or yours first and then everyone else's."] = "Solo los perjuicios que le aplicas, o los tuyos primero y luego los de los demás."
L["Only under a minute"] = "Solo por debajo de un minuto"
L["Only what you move here"] = "Solo lo que muevas aquí"
L["Only when detached."] = "Solo cuando está separado."
L["Only when detached. Main hand at the bottom, the others above it."] = "Solo cuando está separado. Mano principal abajo, las demás encima."
L["Only when detached. When attached, the bars match the cast bar's width."] = "Solo cuando está separado. Cuando está unido, las barras coinciden con el ancho de la barra de lanzamiento."
L["Only when something changes"] = "Solo cuando algo cambia"
L["Only while the power bar is on its own."] = "Solo mientras la barra de poder esté independiente."
L["Only while the power bar is on its own. When off, both ends are straight."] = "Solo mientras la barra de poder esté independiente. Desactivado, ambos extremos son rectos."
L["Only with a target"] = "Solo con un objetivo"
L["Only your group's leader can change the listing."] = "Solo el líder de tu grupo puede cambiar el anuncio."
L["Only your group's leader can list the group."] = "Solo el líder de tu grupo puede anunciar el grupo."
L["Opacity"] = "Opacidad"
L["Opacity & fade"] = "Opacidad y desvanecimiento"
L["Opacity on cooldown"] = "Opacidad en reutilización"
L["Open"] = "Abrir"
L["Open DaylightUI options"] = "Abrir las opciones de DaylightUI"
L["Open a chat box first to link it."] = "Abre primero un cuadro de texto del chat para enlazarlo."
L["Open spot"] = "Hueco libre"
L["Open stat groups"] = "Grupos de estadísticas abiertos"
L["Open this page at these settings."] = "Abrir esta sección con estos ajustes."
L["Open world only"] = "Solo en el mundo abierto"
L["Opening a mailbox shows DaylightUI's window: your letters, sending, and a ledger of your gold. Turn it off to use the game's window. The ledger keeps counting either way."] = "Abrir un buzón muestra la ventana de DaylightUI: tus cartas, el envío y un registro de tu oro. Desactívala para usar la ventana del juego. El registro sigue contando en cualquier caso."
L["Opening a profession shows DaylightUI's window: your recipes on the left, the one you picked on the right. In a fight the game's own window opens. Turn it off to use the game's window."] = "Abrir una profesión muestra la ventana de DaylightUI: tus recetas a la izquierda, la que hayas elegido a la derecha. En combate se abre la ventana propia del juego. Desactívala para usar la ventana del juego."
L["Opening a vendor sells everything in the Junk group: gray items, and anything you've moved to Junk yourself. Chat shows how much you got."] = "Abrir un mercader vende todo lo que hay en el grupo Chatarra: objetos grises y todo lo que hayas movido tú mismo a Basura. El chat muestra cuánto has ganado."
L["Opening a vendor that repairs fixes all your gear, and chat shows the cost. Not in combat."] = "Abrir un mercader que repara arregla todo tu equipo, y el chat muestra el coste. No en combate."
L["Opening and closing windows: bags, character, spellbook, quest log, the game menu and DaylightUI's own windows."] = "Apertura y cierre de ventanas: bolsas, personaje, libro de hechizos, registro de misiones, menú del juego y ventanas propias de DaylightUI."
L["Opening the group finder shows DaylightUI's window: groups to join, listing yourself, and who's about. In a fight the game's own window opens. Turn it off to use the game's window."] = "Abrir el buscador de grupos muestra la ventana de DaylightUI: grupos a los que unirse, tu anuncio y quién anda por ahí. En combate se abre la ventana propia del juego. Desactívala para usar la ventana del juego."
L["Opening your bag fills up part stacks of the same item (15 and 5 Linen Cloth become 20), so no slot is wasted. Not in combat, or while you trade or have the mailbox or auction house open."] = "Abrir tu bolsa completa las pilas parciales de un mismo objeto (15 y 5 Tela de lino se convierten en 20), para no desperdiciar ningún espacio. No en combate, ni mientras comercias o tienes abiertos el buzón o la casa de subastas."
L["Opens the Gradients page, where the Combo points pairs are."] = "Abre la sección Degradados, donde están los pares de puntos de combo."
L["Opens the layout editor right on your screen: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "Abre el editor de diseño directamente en la pantalla: saca hechizos de la bandeja, arrástralos donde quieras, enlázalos entre sí y haz clic en uno para cambiarlo. Escribe /cdm para abrirlo en cualquier momento. Solo fuera de combate."
L["Opens your spellbook with Click-cast switched on: click a spell with the mouse button you want. Close the spellbook when you're done and this page comes back."] = "Abre tu libro de hechizos con el lanzamiento con clic activado: haz clic en un hechizo con el botón del ratón que quieras. Cierra el libro de hechizos cuando termines y volverá esta sección."
L["Option toggles"] = "Interruptores de opciones"
L["Options"] = "Opciones"
L["Options (%s): %s"] = "Opciones (%s): %s"
L["Options windows of addons built on Ace3, in the game's settings and their own windows: Questie, RestedXP and many more."] = "Ventanas de opciones de addons basados en Ace3, en los ajustes del juego y en sus propias ventanas: Questie, RestedXP y muchos más."
L["Or drag the badge in Design mode."] = "O arrastra la insignia en el modo Diseño."
L["Or pick one here to skip the click"] = "O elige uno aquí para saltarte el clic"
L["Orange timer when running out"] = "Temporizador naranja al agotarse"
