L["Outlines the member you have targeted, so you can find them at a glance."] = "Rodea al miembro que tienes como objetivo, para encontrarlo de un vistazo."
L["Outside spots may need more space between frames."] = "Las posiciones exteriores pueden necesitar más espacio entre marcos."
L["Outside: above"] = "Exterior: encima"
L["Outside: below"] = "Exterior: debajo"
L["Outside: bottom left"] = "Exterior: abajo a la izquierda"
L["Outside: bottom right"] = "Exterior: abajo a la derecha"
L["Outside: left"] = "Exterior: a la izquierda"
L["Outside: right"] = "Exterior: a la derecha"
L["Outside: top left"] = "Exterior: arriba a la izquierda"
L["Outside: top right"] = "Exterior: arriba a la derecha"
L["Over an hour away. Still here, still waiting."] = "Ausente desde hace más de una hora. Sigue aquí, sigue esperando."
L["Over its owner"] = "Encima de su propietario"
L["Over or under the frame, the buffs sit nearest it when both share a spot. Outside spots may need room around the frame."] = "Encima o debajo del marco, los beneficios quedan lo más cerca de él cuando ambos comparten una posición. Las posiciones exteriores pueden necesitar espacio alrededor del marco."
L["Over, under or beside the health bar. In Design mode on the preview, drag it there."] = "Encima, debajo o al lado de la barra de salud. En modo Diseño, en la vista previa, arrástralo hasta el lugar que quieras."
L["Over, under or beside the health bar. Rows sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Encima, debajo o al lado de la barra de salud. Las filas que comparten una posición se alinean hacia fuera desde la barra. En modo Diseño, en la vista previa, arrástralo hasta el lugar que quieras."
L["Over, under, beside or on a friendly plate's health bar. Without the health bar the name stays centered."] = "Encima, debajo, al lado o sobre la barra de salud de una placa de nombre aliada. Sin la barra de salud, el nombre se queda centrado."
L["Over, under, beside or on the health bar. Pieces sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Encima, debajo, al lado o sobre la barra de salud. Los elementos que comparten una posición se alinean hacia fuera desde la barra. En modo Diseño, en la vista previa, arrástralo hasta el lugar que quieras."
