L["Parts of the world map you haven't explored yet show too, dimmed so you can still tell where you haven't been."] = "También se muestran las partes del mapa del mundo que aún no has explorado, atenuadas para que puedas saber dónde no has estado."
L["Party"] = "Grupo"
