L["Party and instance"] = "Grupo y estancia"
L["Party and raid faded opacity"] = "Opacidad desvanecida del grupo y de la banda"
L["Party and raid frames fade to their own opacity instead of the one above."] = "Los marcos de grupo y de banda se desvanecen a su propia opacidad en lugar de a la de arriba."
L["Party chat from everyone but the leader."] = "Chat de grupo de todos excepto del líder."
L["Party chat from the group's leader."] = "Chat de grupo del líder del grupo."
L["Party color"] = "Color del grupo"
L["Party leader color"] = "Color del líder de grupo"
L["Party on the left, you and your target low in the middle."] = "El grupo a la izquierda, tú y tu objetivo abajo en el centro."
L["Passion One"] = "Passion One"
L["Past this the list scrolls with the mouse wheel."] = "Más allá de esto, la lista se desplaza con la rueda del ratón."
L["Paste a DaylightUI profile (Ctrl+V) and name it. It becomes a new profile, chosen for this character (these talents, with dual spec); yours stay as they are."] = "Pega un perfil de DaylightUI (Ctrl+V) y ponle nombre. Se convierte en un perfil nuevo, elegido para este personaje (estos talentos, con doble especialización); los tuyos siguen como están."
L["Paste a layout string from the game's Cooldown Manager (its Export), a guide or another UI (Ctrl+V). It becomes a new profile, used by talent set %d."] = "Pega una cadena de diseño del gestor de reutilización del juego (su Exportar), de una guía o de otra interfaz (Ctrl+V). Se convierte en un perfil nuevo, usado por el conjunto de talentos %d."
L["Paste a talent string"] = "Pegar una cadena de talentos"
L["Paste someone's profile. It becomes a new profile; yours stay as they are."] = "Pega el perfil de alguien. Se convierte en un perfil nuevo; los tuyos siguen como están."
L["Paste talent string..."] = "Pegar cadena de talentos..."
