L["Pick All bars to change every bar at once, or one bar to give it a look of its own."] = "Elige Todas las barras para cambiarlas a la vez, o una sola barra para darle una apariencia propia."
L["Pick a category to look for groups."] = "Elige una categoría para buscar grupos."
L["Pick a letter."] = "Elige una carta."
L["Pick a page on the left to shape your interface. Changes apply as you make them."] = "Elige una sección a la izquierda para dar forma a tu interfaz. Los cambios se aplican a medida que los haces."
L["Pick a page on the left to shape your interface. Changes apply as you make them. Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "Elige una sección a la izquierda para dar forma a tu interfaz. Los cambios se aplican a medida que los haces. Pasa el ratón sobre un ajuste para ver qué hace; la flecha junto a un ajuste modificado lo restablece."
L["Pick a playstyle to list."] = "Elige un estilo de juego para el anuncio."
L["Pick a profession above."] = "Elige una profesión arriba."
L["Pick a recipe."] = "Elige una receta."
L["Pick a spell to put above %s"] = "Elige un hechizo para colocar encima de %s"
