L["Pick a spell to put right of %s"] = "Elige un hechizo para colocar a la derecha de %s"
L["Pick an icon or a bar."] = "Elige un icono o una barra."
L["Picks a whole set of colors at once. Colors you changed yourself are kept; a row's reset button sets it back to the palette."] = "Elige un conjunto completo de colores de una vez. Los colores que hayas modificado tú mismo se conservan; el botón de restablecer de una fila lo devuelve a la paleta."
L["Pin"] = "Fijar"
