L["Player Cast Bar"] = "Barra de lanzamiento del jugador"
L["Player Power Bar"] = "Barra de poder del jugador"
L["Player cast bar"] = "Barra de lanzamiento del jugador"
L["Player frame"] = "Marco del jugador"
L["Player, target, party and raid frames."] = "Marcos del jugador, del objetivo, de grupo y de banda."
L["Player, target, party, raid and more."] = "Jugador, objetivo, grupo, banda y más."
L["Players"] = "Jugadores"
L["Players' and creatures' tooltips show while you're fighting. When off, they stay hidden in a fight; hold Shift to see one."] = "Los avisos emergentes de jugadores y criaturas se muestran durante el combate. Si está desactivado, permanecen ocultas en combate; mantén pulsado Mayús para ver una."
L["Players' last names after their first, on nameplates. Where the game hides names (in combat, in places) only the first name shows."] = "El apellido de los jugadores después de su nombre, en las placas de nombre. Allí donde el juego oculta los nombres (en combate, en algunos lugares) solo se muestra el nombre."
L["Players' last names after their first, on this frame only. Where the game hides names (in combat, in places) only the first name shows."] = "El apellido de los jugadores después de su nombre, solo en este marco. Allí donde el juego oculta los nombres (en combate, en algunos lugares) solo se muestra el nombre."
L["Players' last names after their first, on tooltips. Where the game hides names (in combat, in places) only the first name shows."] = "El apellido de los jugadores después de su nombre, en los avisos emergentes. Allí donde el juego oculta los nombres (en combate, en algunos lugares) solo se muestra el nombre."
L["Players' last names after their first. When off, first names only, which fit the narrow rows better."] = "El apellido de los jugadores después de su nombre. Si está desactivado, solo el nombre, que encaja mejor en las filas estrechas."
L["Players' names in their class color, in every kind of chat (the game's own setting)."] = "Los nombres de los jugadores en el color de su clase, en todos los tipos de chat (ajuste propio del juego)."
L["Playing %s"] = "%s"
L["Plays it now. Also /dui levelup."] = "Lo reproduce ahora. También /dui levelup."
