L["Press 1 to 9 to pick a line or a reward, Space for the next step (accept, continue, complete), Escape to back out. Space never jumps while you talk. Other keys still go to the game, and in combat every key is the game's."] = "Pulsa de 1 a 9 para elegir una línea o una recompensa, Espacio para el siguiente paso (aceptar, continuar, terminar), Escape para volver atrás. Espacio nunca avanza mientras hablas. Las demás teclas siguen yendo al juego, y en combate todas las teclas son del juego."
L["Press Bind in spellbook (or open %s and switch on Click-cast at its top), then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more). That click on any of your unit frames then casts it on that unit. Close the spellbook when you're done: this page comes back. Left-click still targets and right-click opens the menu unless you bind them."] = "Pulsa Asignar en el libro de hechizos (o abre %s y activa el lanzamiento con clic en su parte superior), luego haz clic en un hechizo con el botón del ratón que quieras (mantén Mayús, Ctrl o Alt para más opciones). Ese clic en cualquiera de tus marcos de unidad lanzará entonces el hechizo sobre esa unidad. Cierra el libro de hechizos cuando termines: esta sección vuelve. El clic izquierdo sigue seleccionando el objetivo y el clic derecho abre el menú, salvo que los asignes."
