L["Shows a grid while frames are unlocked, and snaps them to it."] = "Muestra una cuadrícula mientras los marcos están desbloqueados, y los ajusta a ella."
L["Shows a handle on every frame. Drag to move it; right-click a handle to reset that frame."] = "Muestra un tirador en cada marco. Arrástralo para moverlo; haz clic derecho en un tirador para restablecer ese marco."
L["Shows a macro's name on its button. When off, macros show their icon only."] = "Muestra el nombre de una macro en su botón. Desactivado, las macros solo muestran su icono."
L["Shows a sample of just this frame while you edit it, and every change as you make it. Stays on across pages until you switch it off; combat ends it."] = "Muestra un ejemplo de este único marco mientras lo editas, con cada cambio a medida que lo haces. Permanece activo de una sección a otra hasta que lo desactives; el combate lo termina."
L["Shows a sample of the line where it sits."] = "Muestra un ejemplo de la línea donde está colocada."
L["Shows buffs icons on each member."] = "Muestra los iconos de beneficios en cada miembro."
L["Shows crowd control icons on each member."] = "Muestra los iconos de control de masas en cada miembro."
L["Shows debuffs icons on each member."] = "Muestra los iconos de perjuicios en cada miembro."
L["Shows each button's key on the button. When off, the keys still work, you just don't see them."] = "Muestra la tecla de cada botón en el propio botón. Desactivado, las teclas siguen funcionando, simplemente no las ves."
L["Shows each pet's health as text."] = "Muestra la salud de cada mascota como texto."
L["Shows each pet's name."] = "Muestra el nombre de cada mascota."
L["Shows only while the buff is up, like Power Word: Shield."] = "Se muestra solo mientras el beneficio está activo, como Palabra de poder: escudo."
L["Shows or hides the row of bag buttons. Your bag keys still open your bags when it's hidden."] = "Muestra u oculta la fila de botones de las bolsas. Tus teclas de bolsas siguen abriéndolas cuando está oculta."
L["Shows or hides the row of small buttons that open your character, spellbook, talents and other windows. Their keys still work when it's hidden."] = "Muestra u oculta la fila de botones pequeños que abren la ventana del personaje, el libro de hechizos, los talentos y otras ventanas. Sus teclas siguen funcionando cuando está oculta."
L["Shows server time instead of your local time."] = "Muestra la hora del servidor en lugar de tu hora local."
L["Shows target, focus, pet, target of target and the party with sample units, and both cast bars mid-cast, so you can style and move them without a real target. Ends when combat starts."] = "Muestra el objetivo, el foco, la mascota, el objetivo del objetivo y el grupo con unidades de ejemplo, y ambas barras de lanzamiento a mitad de lanzamiento, para que puedas dar estilo y mover los elementos sin un objetivo real. Termina al empezar un combate."
L["Shows the AFK screen now. Click or press any key to close it. Also /dui afk."] = "Muestra ahora la pantalla de AFK. Haz clic o pulsa cualquier tecla para cerrarla. También /dui afk."
L["Shows the calendar and tracking buttons on the map's right edge while the mouse is over the map."] = "Muestra los botones del calendario y del seguimiento en el borde derecho del mapa mientras el ratón está sobre él."
L["Shows the game's countdown on buttons that are on cooldown."] = "Muestra la cuenta atrás del juego en los botones que están en tiempo de reutilización."
L["Shows the game's small gold coin on gray items in the bank, like the default bags."] = "Muestra la pequeña moneda de oro del juego en los objetos grises del banco, como las bolsas predeterminadas."
L["Shows the game's small gold coin on gray items, like the default bags."] = "Muestra la pequeña moneda de oro del juego en los objetos grises, como las bolsas predeterminadas."
L["Shows the healer's name next to a heal on you."] = "Muestra el nombre del sanador junto a una sanación recibida."
L["Shows the health text large and white in the frame's inner corner (in Ribbon, at the inner end of the row above the bar)."] = "Muestra el texto de salud grande y en blanco en la esquina interior del marco (en Cinta, en el extremo interior de la fila sobre la barra)."
L["Shows the unit's name on this frame."] = "Muestra el nombre de la unidad en este marco."
L["Shows these raid frames in a party too, in place of the party frames."] = "Muestra también estos marcos de banda en grupo, en lugar de los marcos de grupo."
L["Shows this square on each member while its spell is on them."] = "Muestra este cuadrado en cada miembro mientras su hechizo esté activo sobre él."
