L["Sitting by a campfire warms the screen with firelight and embers, a soft crackle plays, and your action bars and unit frames fade away. Move, target or cast and everything comes back; a fight brings it back at once. The sounds follow Soft UI sounds (General > Sound)."] = "Sentado junto a una hoguera, la pantalla se calienta con luz de fuego y brasas, suena un suave crepitar, y tus barras de acción y marcos de unidad se desvanecen. Muévete, selecciona un objetivo o lanza un hechizo y todo vuelve; un combate lo hace reaparecer de inmediato. Los sonidos siguen los sonidos de interfaz suaves (General > Sonido)."
