L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for the bank alone: their rows show below."] = "El tamaño de las ranuras, el espaciado, la escala, la disposición de los objetos, las ranuras vacías y las marcas de los iconos siguen tu sección de Bolsas. Desactívalo para configurarlos solo para el banco: sus filas se muestran abajo."
L["Slots"] = "Ranuras"
