L["Slots with nothing on them show as empty frames. When off, they disappear and show again while you drag a spell or item."] = "Las ranuras vacías se muestran como marcos vacíos. Desactivado, desaparecen y vuelven a mostrarse mientras arrastras un hechizo o un objeto."
L["Small Brown Pouch"] = "Pequeña bolsa marrón"
L["Small colored squares on each member for your heals over time and shields, like Renew or Power Word: Shield. Each square shows while your spell is on them."] = "Pequeños cuadrados de colores en cada miembro para tus sanaciones de efecto continuo y escudos, como Renovar o Palabra de poder: escudo. Cada cuadrado se muestra mientras tu hechizo esté activo sobre él."
L["Small helpers and the game's windows in DaylightUI style."] = "Pequeños asistentes y ventanas del juego con el estilo de DaylightUI."
