L["Small icons in their own row, under the frame by default."] = "Pequeños iconos en su propia fila, debajo del marco por defecto."
L["Small icons over your frame, nearest it. Off by default: your buff bars show them too."] = "Pequeños iconos encima de tu marco, lo más cerca posible. Desactivado por defecto: tus barras de beneficios también los muestran."
L["Small tiles for a raid of up to 10: one column per group, left to right. Show, fade, textures and fonts here count for every raid size; your party has its own page."] = "Pequeñas casillas para una banda de hasta 10: una columna por grupo, de izquierda a derecha. Mostrar, atenuar, texturas y fuentes aquí valen para todos los tamaños de banda; tu grupo tiene su propia sección."
