L["The AFK screen can't show in combat, a boss fight, a keystone or a PvP match."] = "La pantalla AFK no puede mostrarse en combate, en un enfrentamiento con un jefe, con una piedra angular ni en una partida JcJ."
L["The Daylight chat box's own look and motion (Chat style: Daylight)."] = "El aspecto y las animaciones propios del cuadro de chat Daylight (estilo de chat: Daylight)."
L["The DaylightUI border, the item's quality color, your accent color (General > Appearance), or a color you pick."] = "El borde de DaylightUI, el color de calidad del objeto, tu color de acento (General > Apariencia) o un color que elijas."
L["The Fabled styles are art by JiberishUI and its artists, from the Jiberish Fabled Icons addon, read from its own folder. Without it installed, every style shows Daylight UI's own icons."] = "Los estilos Fabled son obra de JiberishUI y sus artistas. Proceden del addon Jiberish Fabled Icons, leídos desde su propia carpeta. Si no está instalado, cada estilo muestra los iconos propios de Daylight UI."
L["The Legacy button shows DaylightUI's window: how far the next reward is, the challenges and the Legacy trees. Turn it off to use the game's window."] = "El botón Legado muestra la ventana de DaylightUI: cuánto falta para la siguiente recompensa, los desafíos y los árboles de legado. Desactívalo para usar la ventana del juego."
L["The Mindless Ones completed."] = "Los Sin mente completados."
L["The NPC window is switched off (/dui > Talk)."] = "La ventana de PNJ está desactivada (/dui > Hablar)."
L["The Quests header stays when nothing is tracked, so you can see where the tracker is."] = "El encabezado Misiones permanece visible cuando no hay nada seguido, para que veas dónde está el seguimiento."
L["The accent"] = "El acento"
L["The aggro color when Aggro color is Custom color."] = "El color de amenaza cuando Color de amenaza está en Color personalizado."
L["The arrow's color while Arrow color is set to Custom."] = "El color de la flecha cuando Color de la flecha está en Personalizado."
L["The bank in the same look as your bags. Groups and moved items are shared with your bags."] = "El banco con la misma apariencia que tus bolsas. Los grupos y objetos movidos se comparten con tus bolsas."
L["The bar shades from dark to bright in its standing's colors, editable on the Gradients page."] = "La barra pasa de oscuro a claro en los colores de su nivel de reputación, modificables en la sección Degradados."
L["The bar shades from dark to bright instead of one flat color. Reputation gets one per standing, editable on the Gradients page."] = "La barra pasa de oscuro a claro en lugar de un color plano. La reputación tiene uno por nivel, modificable en la sección Degradados."
L["The bar's color for dead and offline players and tapped NPCs, and for NPCs by how they feel about you."] = "El color de la barra para los jugadores muertos y desconectados, los PNJ reclamados, y para los PNJ según su actitud hacia ti."
L["The bar's color while the cast can't be interrupted, whatever the fill style."] = "El color de la barra cuando el lanzamiento no puede interrumpirse, sea cual sea el estilo de relleno."
L["The bar's color while the cast can't be interrupted."] = "El color de la barra cuando el lanzamiento no puede interrumpirse."
L["The bars over enemies' heads: how big they are, and what they show."] = "Las barras sobre la cabeza de los enemigos: su tamaño y lo que muestran."
L["The bars shade from dark to bright instead of one flat color. The color pairs are on General > Gradients."] = "Las barras pasan de oscuro a claro en lugar de un color plano. Los pares de colores están en General > Degradados."
L["The bars that hang off the end of the health for incoming heals and absorb shields. An overshield (a shield bigger than the health missing) follows the shield."] = "Las barras que prolongan la salud por las sanaciones entrantes y los escudos de absorción. Un sobreescudo (un escudo mayor que la salud que falta) sigue al escudo."
L["The bars' and names' colors on every unit frame."] = "Los colores de las barras y de los nombres en todos los marcos de unidad."
L["The bars' color when Bar color is One color."] = "El color de las barras cuando Color de la barra está en Un color."
L["The border color of every loot feed line while Loot feed border color is set to Custom."] = "El color del borde de cada línea del flujo de botín cuando Color del borde del flujo de botín está en Personalizado."
L["The border color when Border color is set to Your own color."] = "El color del borde cuando Color del borde está en Tu color."
L["The border in the same color as the name."] = "El borde del mismo color que el nombre."
L["The border of a debuff you can dispel, and the raid tile's dispel icon. Debuffs already on screen change after /reload."] = "El borde de un perjuicio que puedes disipar, y el icono de disipación de la casilla de banda. Los perjuicios que ya están en pantalla cambian tras /reload."
L["The boxes behind the experience bar, minimap and damage meter, and the meters' and threat meter's own windows. At 0 opacity the boxes disappear; the minimap and bars still show."] = "Los marcos detrás de la barra de experiencia, el minimapa y el medidor de daño, y las ventanas propias de los medidores y del medidor de amenaza. Con una opacidad de 0, los marcos desaparecen; el minimapa y las barras siguen visibles."
L["The buffs wrap onto up to this many rows."] = "Los beneficios se distribuyen en este número de filas como máximo."
L["The button's border lights up while the mouse is over it."] = "El borde del botón se ilumina cuando el ratón lo sobrevuela."
L["The button's border lights up while you press it."] = "El borde del botón se ilumina cuando lo pulsas."
L["The cast bar's color when Fill style is One color."] = "El color de la barra de lanzamiento cuando Estilo de relleno está en Un color."
L["The character window and its tabs (reputation, skills, PvP, currency, statistics), inspecting others."] = "La ventana del personaje y sus pestañas (reputación, habilidades, JcJ, monedas, estadísticas), la inspección de otros."
L["The chat menu, channel, voice and social buttons next to chat. When off, they're gone; their slash commands still work."] = "Los botones del menú de chat, de canales, de voz y de social, junto al chat. Desactivados, desaparecen; sus comandos slash siguen funcionando."
L["The chat only"] = "Solo el chat"
L["The chat window's text and the chat bubbles. General uses the font on General > Appearance."] = "El texto de la ventana de chat y las burbujas de chat. General usa la fuente de General > Apariencia."
L["The clock reads 18:30 instead of 6:30 PM."] = "El reloj muestra 18:30 en lugar de 6:30 PM."
L["The color of a Curse debuff's border and dispel icon."] = "El color del borde y del icono de disipación de un perjuicio de tipo Maldición."
L["The color of a Disease debuff's border and dispel icon."] = "El color del borde y del icono de disipación de un perjuicio de tipo Enfermedad."
L["The color of a Magic debuff's border and dispel icon."] = "El color del borde y del icono de disipación de un perjuicio de tipo Magia."
L["The color of a Poison debuff's border and dispel icon."] = "El color del borde y del icono de disipación de un perjuicio de tipo Veneno."
L["The color of the glow around your target's bar."] = "El color del resplandor alrededor de la barra de tu objetivo."
L["The color of the last pip, or the whole row at max points, and the end of Color to full color."] = "El color del último punto, o de toda la fila con el máximo de puntos, y el final de Color hasta lleno."
L["The color of the names on the threat meter."] = "El color de los nombres en el medidor de amenaza."
L["The color of the names on this meter's bars."] = "El color de los nombres en las barras de este medidor."
L["The color of the outline around your target's bar."] = "El color del contorno alrededor de la barra de tu objetivo."
L["The color of the pull line across the threat bars."] = "El color de la línea de recuperación de amenaza en las barras."
L["The color of the shaded spell cost on your power bar."] = "El color del coste del hechizo sombreado en tu barra de poder."
L["The color of the stretch for damage shields."] = "El color de la porción de los escudos de daño."
L["The color of the stretch past the health for heals on their way."] = "El color de la porción más allá de la salud para las sanaciones en curso."
L["The color the border lights up in while the mouse is over a button."] = "El color de iluminación del borde cuando el ratón sobrevuela un botón."
L["The color the border lights up in while you press a button."] = "El color de iluminación del borde cuando pulsas un botón."
L["The color the execute range lights up in."] = "El color de iluminación de la zona de ejecución."
L["The color used while the menu above is set to Custom."] = "El color que se usa cuando el menú de arriba está en Personalizado."
L["The colored sweep over the icon while its buff is up. When off, only the timer shows."] = "El barrido coloreado sobre el icono mientras su beneficio está activo. Desactivado, solo se muestra el temporizador."
L["The colors below"] = "Los colores de abajo"
L["The colors, font and textures used everywhere. The screen changes as you pick."] = "Los colores, la fuente y las texturas que se usan en todas partes. La pantalla cambia a medida que eliges."
L["The cooldown edge's color when Cooldown edge is set to Your own color."] = "El color del borde del tiempo de reutilización cuando Borde del tiempo de reutilización está en Tu color."
L["The cooldown layout can't be edited during combat."] = "El diseño de reutilización no se puede modificar en combate."
L["The cooldown manager's layout."] = "El diseño del gestor de reutilización."
L["The countdown icons for your totems, above the player frame. Move them in unlock mode."] = "Los iconos de cuenta atrás de tus tótems, encima del marco del jugador. Muévelos en el modo de desbloqueo."
L["The crowd control alert's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "El sitio del aviso de control lo guarda el modo de edición del juego, y estás en un diseño propio de ese modo: muévelo allí (Esc > Modo de edición)."
L["The currencies you're tracking (as the game's own backpack list shows them), with their icon and count, beside your money."] = "Las monedas que sigues (tal como las muestra la lista de la mochila del juego), con su icono y su cantidad, junto a tu dinero."
L["The damage meter and minimap fade together (and the separate meter window, if used). So does the experience bar, unless you give it its own fade below."] = "El medidor de daño y el minimapa se desvanecen juntos. Igual que la barra de experiencia, a menos que use su propio desvanecimiento."
L["The dark part shrinks away instead of filling in."] = "La parte oscura se reduce en lugar de llenarse."
L["The dark ribbon behind each line. When off, only the icon and text show."] = "La cinta oscura detrás de cada línea. Desactivada, solo se muestran el icono y el texto."
L["The data texts, and the clock and framerate on the minimap. General uses the font on General > Appearance."] = "Los textos de datos, así como el reloj y los fotogramas por segundo del minimapa. General usa la fuente de General > Apariencia."
L["The debuffs wrap onto up to this many rows."] = "Los perjuicios se distribuyen en este número de filas como máximo."
L["The dim line under each item's name. Repair warnings still show when it's off."] = "La línea atenuada bajo el nombre de cada objeto. Las alertas de reparación siguen mostrándose cuando está desactivada."
L["The dungeon journal, its favorites and settings windows; each dungeon's picture kept."] = "El diario de mazmorras, sus ventanas de favoritos y de opciones; la imagen de cada mazmorra se conserva."
L["The edge round each button. A proc still lights it up."] = "El borde alrededor de cada botón. Una activación sigue iluminándolo."
L["The elite dragon wraps your own portrait too."] = "El dragón élite rodea también tu propio retrato."
L["The empty bar pulses while the buff is down."] = "La barra vacía pulsa mientras el beneficio no esté activo."
L["The empty part behind every bar's fill, tinted in the bar's color, except where a frame's own page picks another."] = "La parte vacía detrás del relleno de cada barra, teñida con el color de la barra, salvo que la sección propia de un marco elija otra."
L["The empty part behind the bars in DaylightUI's windows. General uses the bar background above."] = "La parte vacía detrás de las barras de las ventanas de DaylightUI. General usa el fondo de barra de arriba."
L["The empty part of every bar in the group. A spell's own background, above, wins."] = "La parte vacía de cada barra del grupo. El fondo propio de un hechizo, arriba, tiene prioridad."
L["The empty part of every health bar: a dimmed copy of the bar's own color, or one you pick."] = "La parte vacía de cada barra de salud: una copia atenuada del color de la barra, o un color de tu elección."
L["The empty part of the Cooldown Manager's bars, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de las barras del gestor de reutilización, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the cast bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de la barra de lanzamiento de cada placa de nombre, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the combo points on your target's nameplate, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de los puntos de combo en la placa de nombre de tu objetivo, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the combo points, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de los puntos de combo, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the damage, healing and threat meters' bars, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de las barras de los medidores de daño, de sanación y de amenaza, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the experience and reputation bar, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de la barra de experiencia y de reputación, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the health bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de la barra de salud en cada placa de nombre, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the health bar under a unit's tooltip, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de la barra de salud bajo la descripción emergente de una unidad, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the pets' health bars, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de las barras de salud de las mascotas, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the pets' power bars, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de las barras de poder de las mascotas, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the progress bars in the tracker and the pop-up, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de las barras de progreso del seguimiento y de la ventana emergente, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the raid tiles' health bars, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de las barras de salud de las casillas de banda, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the raid tiles' power bars, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de las barras de poder de las casillas de banda, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of the swing timer, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía del tiempo de golpes, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of this frame's health bar, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de la barra de salud de este marco, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of this frame's power bar, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de la barra de poder de este marco, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of your cast bar, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de tu barra de lanzamiento, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of your focus's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de la barra de lanzamiento de tu foco, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part of your target's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "La parte vacía de la barra de lanzamiento de tu objetivo, detrás del relleno. General usa el fondo de barra de General > Apariencia."
L["The empty part's color when Missing health color is Custom color."] = "El color de la parte vacía cuando Color de salud perdida está en Color personalizado."
L["The experience bar on top of the panel, or reputation at the level cap."] = "La barra de experiencia en la parte superior del panel, o la reputación en el nivel máximo."
L["The experience bar's text and its +XP. General uses the font on General > Appearance."] = "El texto de la barra de experiencia y su +PE. General usa la fuente de General > Apariencia."
L["The experience bar's box, and the meters' and threat meter's own windows. The minimap's box has its own on the Minimap page. At 0 opacity the boxes disappear; the bars still show."] = "El fondo de la barra de experiencia, así como las ventanas propias de los medidores de daño y del medidor de amenaza. El fondo del minimapa tiene su propia opción en la sección Minimapa. A una opacidad de 0, los fondos desaparecen; las barres siguen visibles."
L["The experience bar, damage meter and minimap fade together (and the separate meter window, if used)."] = "La barra de experiencia, el medidor de daño y el minimapa se desvanecen juntos (y la ventana separada del medidor, si se usa)."
L["The faction's name on the bar."] = "El nombre de la facción en la barra."
L["The fifth chat channel you joined, often a custom one."] = "El quinto canal de chat al que te has unido, a menudo uno personalizado."
L["The fifth pip fills in Full color (red to start with), so a full row stands out at a glance."] = "El quinto punto se llena con el Color lleno (rojo al principio), para que una fila completa se note de un vistazo."
L["The fill of every bar: health, power, cast bars, swing timers, experience, the damage meter, nameplates and more, except where a frame's own page picks another. Textures other addons share (SharedMedia) are listed after ours."] = "El relleno de todas las barras: salud, poder, barras de lanzamiento, temporizadores de golpe, experiencia, medidor de daño, placas de nombre y más, salvo que la sección propia de un marco elija otra. Las texturas que comparten otros addons (SharedMedia) aparecen después de las nuestras."
L["The fill of the Cooldown Manager's bars. General uses the bar texture on General > Appearance."] = "El relleno de las barras del gestor de reutilización. General usa la textura de barra de General > Apariencia."
L["The fill of the bars in DaylightUI's windows: reputation, skills, professions, pet experience, quest objectives. They keep their round shape. General uses the bar texture above."] = "El relleno de las barras de las ventanas de DaylightUI: reputación, habilidades, profesiones, experiencia de la mascota, objetivos de misión. Conservan su forma redondeada. General usa la textura de barra de arriba."
L["The fill of the cast bar on every nameplate. General uses the bar texture on General > Appearance."] = "El relleno de la barra de lanzamiento en cada placa de nombre. General usa la textura de barra de General > Apariencia."
L["The fill of the combo points on your target's nameplate. General uses the bar texture on General > Appearance."] = "El relleno de los puntos de combo en la placa de nombre de tu objetivo. General usa la textura de barra de General > Apariencia."
L["The fill of the combo points. General uses the bar texture on General > Appearance."] = "El relleno de los puntos de combo. General usa la textura de barra de General > Apariencia."
L["The fill of the damage, healing and threat meters' bars. General uses the bar texture on General > Appearance."] = "El relleno de las barras de los medidores de daño, de sanación y de amenaza. General usa la textura de barra de General > Apariencia."
L["The fill of the experience and reputation bar. General uses the bar texture on General > Appearance."] = "El relleno de la barra de experiencia y de reputación. General usa la textura de barra de General > Apariencia."
L["The fill of the health bar on every nameplate. General uses the bar texture on General > Appearance."] = "El relleno de la barra de salud en cada placa de nombre. General usa la textura de barra de General > Apariencia."
L["The fill of the health bar under a unit's tooltip. General uses the bar texture on General > Appearance."] = "El relleno de la barra de salud bajo la descripción emergente de una unidad. General usa la textura de barra de General > Apariencia."
L["The fill of the pets' health bars. General uses the bar texture on General > Appearance."] = "El relleno de las barras de salud de las mascotas. General usa la textura de barra de General > Apariencia."
L["The fill of the pets' power bars. General uses the bar texture on General > Appearance."] = "El relleno de las barras de poder de las mascotas. General usa la textura de barra de General > Apariencia."
L["The fill of the progress bars in the tracker and the pop-up. General uses the bar texture on General > Appearance."] = "El relleno de las barras de progreso del seguimiento y de la ventana emergente. General usa la textura de barra de General > Apariencia."
L["The fill of the raid tiles' health bars. General uses the bar texture on General > Appearance."] = "El relleno de las barras de salud de las casillas de banda. General usa la textura de barra de General > Apariencia."
L["The fill of the raid tiles' power bars. General uses the bar texture on General > Appearance."] = "El relleno de las barras de poder de las casillas de banda. General usa la textura de barra de General > Apariencia."
L["The fill of the swing timer. General uses the bar texture on General > Appearance."] = "El relleno del tiempo de golpes. General usa la textura de barra de General > Apariencia."
L["The fill of this frame's health bar. General uses the bar texture on General > Appearance."] = "El relleno de la barra de salud de este marco. General usa la textura de barra de General > Apariencia."
L["The fill of this frame's power bar. General uses the bar texture on General > Appearance."] = "El relleno de la barra de poder de este marco. General usa la textura de barra de General > Apariencia."
L["The fill of your cast bar. General uses the bar texture on General > Appearance."] = "El relleno de tu barra de lanzamiento. General usa la textura de barra de General > Apariencia."
L["The fill of your focus's cast bar. General uses the bar texture on General > Appearance."] = "El relleno de la barra de lanzamiento de tu foco. General usa la textura de barra de General > Apariencia."
L["The fill of your target's cast bar. General uses the bar texture on General > Appearance."] = "El relleno de la barra de lanzamiento de tu objetivo. General usa la textura de barra de General > Apariencia."
L["The font above shows everywhere at once, except where a frame's own page or the window font below picks another. This puts every one of those back on the font above."] = "La fuente de arriba se aplica en todas partes a la vez, salvo donde la sección propia de un marco o la fuente de la ventana de abajo elija otra. Esto devuelve todas esas excepciones a la fuente de arriba."
L["The friendly health bar's color when Bar color is One color."] = "El color de la barra de salud aliada cuando «Color de la barra» está en «Un color»."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar. Also the game's own character and inspect windows while Daylight UI's are off."] = "El menú del juego, la lista de addons, las macros, el reloj, el botín, el engarzado, la mejora de objetos, el desguazador, la casa de subastas, el libro de profesiones, el marco del mapa del mundo, la barra de aliento. También las ventanas de personaje y de inspección del juego mientras las de Daylight UI estén desactivadas."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the world map's frame, the breath bar."] = "El menú del juego, la lista de addons, las macros, el reloj, el botín, el engarzado, la mejora, el desguazador, la casa de subastas, el marco del mapa del mundo, la barra de aliento."
L["The game only reports range for your group; anyone else stays at full opacity."] = "El juego solo muestra el alcance de tu grupo; los demás se mantienen a opacidad completa."
L["The game shows it as a bar."] = "El juego lo muestra como barra."
L["The game shows it as an icon."] = "El juego lo muestra como icono."
L["The game's chat in the DaylightUI look, in the bottom-left corner. Chat itself works as normal."] = "El chat del juego con la apariencia DaylightUI, en la esquina inferior izquierda. El chat en sí funciona con normalidad."
L["The game's new-player tips (the game setting 'Tutorials'). When off, they're turned off."] = "Los consejos del juego para jugadores nuevos (el ajuste «Tutoriales» del juego). Si está desactivado, no se muestran."
L["The game's numbers that pop off what you hit, and the scrolling combat text over you."] = "Los números del juego que salen de lo que golpeas, y el texto de combate que se desplaza sobre ti."
L["The game's own"] = "El del juego"
L["The game's own buff frames show beside DaylightUI's bars. When off, our bars replace them (they still show while Edit Mode is open)."] = "Los marcos de beneficio del juego se muestran junto a las barras de DaylightUI. Desactivado, nuestras barras los reemplazan (siguen visibles mientras el Modo de edición esté abierto)."
L["The game's own messages: logins, /played, errors and the like."] = "Los mensajes propios del juego: inicios de sesión, /played, errores y similares."
L["The game's own setting: a quest you accept goes straight into the tracker."] = "Ajuste propio del juego: una misión que aceptas va directamente al seguimiento."
L["The game's own setting: the map turns with you, so the way you face is always up. When off, north is always up."] = "Ajuste propio del juego: el mapa gira contigo, así que la dirección hacia la que miras siempre queda arriba. Desactivado, el norte siempre queda arriba."
L["The game's own settings for how the numbers leave the target."] = "Los ajustes propios del juego sobre cómo salen los números del objetivo."
L["The game's own switches."] = "Las opciones propias del juego."
L["The game's own windows in DaylightUI style: the info panel's background, DaylightUI borders, font, controls and scroll bars."] = "Las ventanas del juego con el estilo DaylightUI: el fondo del panel de información, los bordes de DaylightUI, la fuente, los controles y las barras de desplazamiento."
L["The game's own windows in the DaylightUI look."] = "Las ventanas del juego con el aspecto DaylightUI."
L["The game's quest tracker, placed under the panel."] = "El seguimiento de misiones del juego, colocado debajo del panel."
L["The game's scrolling text over your own character: hits you take, heals, procs and more."] = "El texto desplazable del juego sobre tu propio personaje: golpes recibidos, sanaciones, activaciones y más."
L["The game's tooltips in the DaylightUI look."] = "Los avisos emergentes del juego con el aspecto DaylightUI."
L["The game's tooltips."] = "Los avisos emergentes del juego."
L["The game's windows Daylight UI didn't rebuild. Rebuilt windows have their own switches under Extras."] = "Las ventanas del juego que Daylight UI no ha rehecho. Las ventanas rehechas tienen sus propias opciones en Extras."
L["The gap between buff icons."] = "El espacio entre los iconos de beneficio."
L["The gap between combo point pips."] = "El espacio entre los puntos de combo."
L["The gap between combo points."] = "El espacio entre los puntos de combo."
L["The gap between debuff icons."] = "El espacio entre los iconos de perjuicio."
L["The gap between icons."] = "El espacio entre los iconos."
L["The gap between lines, when there's more than one."] = "El espacio entre líneas, cuando hay varias."
L["The gap between one party frame and the next."] = "El espacio entre un marco de grupo y el siguiente."
L["The gap between this bar's buttons."] = "El espacio entre los botones de esta barra."
L["The gap between this bar's icons."] = "El espacio entre los iconos de esta barra."
L["The glow behind your character in this color."] = "El resplandor detrás de tu personaje en este color."
L["The glowing border on a button when its spell procs."] = "El borde luminoso de un botón cuando su hechizo se activa."
L["The gold at the bottom of the bag counts up or down to its new amount. Needs Motion effects (General > Appearance)."] = "El oro de la parte inferior de la bolsa sube o baja hasta su nueva cantidad. Necesita los efectos de movimiento (General > Apariencia)."
L["The green numbers over who you heal."] = "Los números verdes sobre quienes curas."
L["The guide that set this character up: a quick setup, a tour of everything DaylightUI does, or another profile."] = "La guía que configuró este personaje: una configuración rápida, un recorrido por todo lo que hace DaylightUI, o otro perfil."
L["The guide window (old and new), its steps and its item and target boxes."] = "La ventana de la guía (antigua y nueva), sus pasos y sus casillas de objeto y de objetivo."
L["The hand and time on each bar. Attached under the cast bar, it's kept small enough for the bar."] = "La aguja y el tiempo de cada barra. Anclado bajo la barra de lanzamiento, se mantiene lo bastante pequeño para la barra."
L["The health and level numbers on the nameplates. General uses the font on General > Appearance."] = "Los números de salud y de nivel en las placas de nombre. «General» usa la fuente de General > Apariencia."
L["The health bar fills bottom to top instead of across."] = "La barra de salud se llena de abajo arriba en lugar de izquierda a derecha."
L["The health bar fills from the opposite side."] = "La barra de salud se llena desde el lado opuesto."
L["The health bar's color for a dead unit."] = "El color de la barra de salud de una unidad muerta."
L["The health bar's color for a friendly NPC."] = "El color de la barra de salud de un PNJ aliado."
L["The health bar's color for a player who went offline."] = "El color de la barra de salud de un jugador desconectado."
L["The health bar's color for an NPC someone else tagged first."] = "El color de la barra de salud de un PNJ que otro jugador ha atacado primero."
L["The health bar's color for an NPC that attacks you."] = "El color de la barra de salud de un PNJ que te ataca."
L["The health bar's color for an NPC that leaves you alone until you hit it."] = "El color de la barra de salud de un PNJ que te deja en paz hasta que lo golpeas."
L["The health bar's color when Health bar color is One color."] = "El color de la barra de salud cuando «Color de la barra de salud» está en «Un color»."
L["The health text shows at full health too. When off, it disappears while the unit is at full."] = "El texto de salud también se muestra con la salud completa. Desactivado, desaparece mientras la unidad tiene toda su salud."
L["The health text's color when Health text color is Custom."] = "El color del texto de salud cuando «Color del texto de salud» está en «Personalizado»."
L["The highest rank"] = "El rango más alto"
L["The highlight color: Daylight's own quiet tone, the Daylight gradient, your class's color or its gradient (from the Gradients page), or one of your own."] = "El color de resaltado: el tono discreto de Daylight, el degradado Daylight, el color de tu clase o su degradado (de la sección Degradados), o uno a tu elección."
L["The highlight's color when Active spell is set to Your own color."] = "El color de resaltado cuando «Hechizo activo» está en «Tu propio color»."
L["The icon of the quest the minimap arrow points to (click a quest's icon to pick it), and the light behind an icon under the mouse."] = "El icono de la misión hacia la que apunta la flecha del minimapa (haz clic en el icono de una misión para elegirla), y el resplandor detrás de un icono bajo el ratón."
L["The info panel, meter, map and tracker."] = "El panel de información, el medidor, el mapa y el seguimiento."
L["The item level at the bottom in your gear's quality color, durability green to yellow to red. When off, both are plain gray."] = "El nivel de objeto abajo, con el color de calidad de tu equipo; la durabilidad va del verde al amarillo y luego al rojo. Desactivado, ambos se ven en gris liso."
L["The item level of weapons and armor in the bank, in the bottom left corner."] = "El nivel de objeto de las armas y armaduras en el banco, en la esquina inferior izquierda."
L["The item level of weapons and armor in the bottom left corner."] = "El nivel de objeto de las armas y armaduras en la esquina inferior izquierda."
L["The kobolds in the mine carry candles on their heads to see in the dark. Bring me eight of them and I'll make it worth your while."] = "Los kóbolds de la mina llevan velas en la cabeza para ver en la oscuridad. Tráeme ocho y no te arrepentirás."
L["The layout: %s."] = "El diseño: %s."
L["The leader tools are off: Unit Frames > Raid > Leader tools."] = "Las herramientas de líder están desactivadas: Marcos de unidad > Banda > Herramientas de líder."
L["The leader tools open after the fight."] = "Las herramientas de líder se abrirán después del combate."
L["The leader tools sit beside Daylight UI's party or raid frames, which are off."] = "Las herramientas de líder se colocan junto a los marcos de grupo o de banda de DaylightUI, que están desactivados."
L["The leader's crown stays in a fight. When off, it hides while you're fighting."] = "La corona del líder sigue visible en combate. Desactivado, se oculta mientras combates."
L["The level in front of each quest name."] = "El nivel delante del nombre de cada misión."
L["The line under the open tab at the top (Character, Reputation, Skills...)."] = "La línea bajo la pestaña abierta arriba (Personaje, Reputación, Habilidades...)."
L["The line under the open tab in this color."] = "La línea bajo la pestaña abierta en este color."
L["The line where the range starts. 0 hides it."] = "La línea donde empieza el alcance. 0 la oculta."
L["The lines in the middle of the screen (interrupted, bags full, a new area found) in your font, errors in a soft red, easing in and out. Move them with /dui unlock. Turn it off to see the game's own red and yellow text."] = "Las líneas del centro de la pantalla (interrumpido, bolsas llenas, nueva zona descubierta) con tu fuente, los errores en rojo suave, con entrada y salida graduales. Muévelas con /dui unlock. Desactívalo para ver el texto rojo y amarillo propio del juego."
L["The lines under the headers in this color."] = "Las líneas bajo los encabezados en este color."
L["The list grows up from its handle instead of down. For a tracker placed low on the screen."] = "La lista crece hacia arriba desde su asidero en lugar de hacia abajo. Para un seguimiento colocado bajo en la pantalla."
L["The look everything shares: the font, the accent color and the window background."] = "El aspecto común a todo: la fuente, el color de acento y el fondo de las ventanas."
L["The look shared by everything DaylightUI draws."] = "El aspecto común a todo lo que dibuja DaylightUI."
L["The loot browser's window, its lists, buttons and dialogs; its icons and maps kept."] = "La ventana del navegador de botín, sus listas, botones y diálogos; sus iconos y mapas se conservan."
L["The loot window's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "La posición de la ventana de botín la gestiona el Modo de edición del juego, y usas un diseño propio del Modo de edición: muévela allí (Esc > Modo de edición)."
L["The lower ranks of each spell sit under the highest, so you can cast an older rank for less mana. When off, the spellbook lists only the highest rank. The spellbook page has the same switch (Hide ranks)."] = "Los rangos inferiores de cada hechizo se colocan bajo el más alto, para lanzar un rango antiguo con menos maná. Desactivado, el libro de hechizos solo muestra el rango más alto. La sección del libro de hechizos tiene la misma opción (Ocultar rangos)."
L["The main hand bar's color."] = "El color de la barra de mano derecha."
L["The mark shows what the quest wants from it, the way the map does: a sword to kill, a bag to loot, a cog to use, an eye to explore, in the quest's color. Needs the Quests module; without it, the !."] = "La marca indica lo que la misión espera de ella, igual que en el mapa: una espada para matar, una bolsa para recoger, un engranaje para usar, un ojo para explorar, en el color de la misión. Necesita el módulo Misiones; sin él, aparece el !."
L["The marker and the arrow fade back while you're in combat, so they're never in the way."] = "El marcador y la flecha se desvanecen mientras estás en combate, para que nunca estorben."
L["The marker in the world that leads you to your quest."] = "El marcador del mundo que te lleva a tu misión."
L["The marker over the spot of the quest you picked (click its icon in the tracker) in DaylightUI style, with the distance. It fades away once you're in the quest's area on the map. Turn it off to see the game's own marker."] = "El marcador sobre el punto de la misión que elegiste (haz clic en su icono en el seguimiento) con el estilo DaylightUI, con la distancia. Se desvanece en cuanto estás en la zona de la misión en el mapa. Desactívalo para ver el marcador del juego."
L["The melee bars' color while Heroic Strike, Cleave or Maul waits for your next swing."] = "El color de las barras cuerpo a cuerpo mientras «Golpe heroico», «Rajar» o «Magullar» espera a tu próximo golpe."
L["The meter hides while you play solo."] = "El medidor se oculta cuando juegas en solitario."
L["The most buff icons at once."] = "El número máximo de iconos de beneficio a la vez."
L["The most buffs you can purge or steal one plate shows."] = "El número máximo de beneficios purgables o robables que muestra cada barra."
L["The most debuff icons at once."] = "El número máximo de iconos de perjuicio a la vez."
L["The most debuffs from other players, shown after yours. Only with Mine first, then others."] = "El número máximo de perjuicios de otros jugadores, mostrados después de los tuyos. Solo con «Los míos primero, luego los demás»."
L["The most group members the threat meter lists at once, under the damage meter."] = "El número máximo de miembros del grupo listados a la vez por el medidor de amenaza, bajo el medidor de daño."
L["The most group members the threat meter lists at once."] = "El número máximo de miembros del grupo listados a la vez por el medidor de amenaza."
L["The most icons this group shows at once."] = "El número máximo de iconos que muestra este grupo a la vez."
L["The most of your buffs one friendly plate shows."] = "El número máximo de tus beneficios que muestra una placa de nombre aliada."
L["The most of your debuffs one plate shows."] = "El número máximo de tus perjuicios que muestra una placa de nombre."
L["The most of your own debuffs shown at once."] = "El número máximo de tus propias perjuicios mostrados a la vez."
L["The mouseover border's color when Mouseover border color is set to Your own color."] = "El color del borde al pasar el ratón cuando «Color del borde al pasar el ratón» está en «Tu propio color»."
L["The name floats above the bar, at its outer end. Long names are cut short."] = "El nombre flota sobre la barra, en su extremo exterior. Los nombres largos se recortan."
L["The name of a buff or debuff as it lands on you."] = "El nombre de un beneficio o un perjuicio cuando se te aplica."
L["The name sits in a small tab above the frame. Long names are cut short."] = "El nombre se coloca en una pequeña pestaña sobre el marco. Los nombres largos se recortan."
L["The name's color when Name color is Custom."] = "El color del nombre cuando «Color del nombre» está en «Personalizado»."
L["The names on every unit frame, unless a frame picks its own. Class and reaction: players by class color, others by friendly, neutral or hostile."] = "Los nombres de todos los marcos de unidad, salvo que un marco elija los suyos. Clase y reacción: los jugadores según el color de clase; los demás según amistoso, neutral u hostil."
L["The names' color when Name color is Custom."] = "El color de los nombres cuando «Color del nombre» está en «Personalizado»."
L["The newest first. Click one to move it again."] = "Los más recientes primero. Haz clic en uno para moverlo de nuevo."
L["The note box shows after the fight."] = "El cuadro de notas se muestra después del combate."
L["The number on an icon showing how many stacks it has."] = "El número de un icono que indica cuántas acumulaciones tiene."
L["The numbers change color for the last seconds of the cooldown."] = "Los números cambian de color durante los últimos segundos del tiempo de reutilización."
L["The numbers in objectives, like 3/8."] = "Los números de los objetivos, como 3/8."
L["The numbers on the bar, e.g. 1,200 / 5,000 (+800), where +800 is your rested XP."] = "Los números de la barra, p. ej. 1.200 / 5.000 (+800), donde +800 es tu experiencia de descanso."
L["The numbers on the bar, e.g. 1,800 / 3,000."] = "Los números de la barra, p. ej. 1.800 / 3.000."
L["The numbers over what you hit."] = "Los números sobre lo que golpeas."
L["The off hand bar's color."] = "El color de la barra de mano izquierda."
L["The order of the quests inside each zone in the quest log on the map."] = "El orden de las misiones dentro de cada zona en el registro de misiones del mapa."
L["The outline every button is cut to. The icon, border and cooldown shade all follow it."] = "La forma a la que se recorta cada botón. El icono, el borde y la sombra del tiempo de reutilización la siguen."
L["The outline or glow in your accent color (Appearance), following it when it changes. When off, uses the colors below."] = "El contorno o el resplandor en tu color de acento (Apariencia), que lo sigue cuando cambia. Desactivado, usa los colores de abajo."
L["The outline's color when Target outline color is Custom color."] = "El color del contorno cuando «Color del contorno del objetivo» está en «Color personalizado»."
L["The panel behind the chat, with its border. When off, only the chat text shows."] = "El panel detrás del chat, con su borde. Desactivado, solo se muestra el texto del chat."
L["The panel's framed box behind the list, as tall as what's shown."] = "El cuadro enmarcado del panel detrás de la lista, tan alto como lo que se muestra."
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn the square off to have only this."] = "La barra de salud de la mascota adopta en su lugar el color de su humor: rojo si está descontenta, amarillo si está satisfecha, verde si está feliz. Desactiva el cuadrado para tener solo esto."
L["The pets' health text. General uses the font on General > Appearance."] = "El texto de salud de las mascotas. «General» usa la fuente de General > Apariencia."
L["The pets' names. General uses the font on General > Appearance."] = "Los nombres de las mascotas. «General» usa la fuente de General > Apariencia."
L["The piece of the bar you just earned flashes and \"+XP\" rises; a sweep on a level up. Needs Motion effects (General > Appearance)."] = "La porción de barra que acabas de ganar parpadea y «+PE» sube; un barrido al subir de nivel. Necesita los efectos de movimiento (General > Apariencia)."
L["The pips widen to span the whole frame, so the row reads like a bar."] = "Los puntos se ensanchan para cubrir todo el marco, así la fila se lee como una barra."
L["The pips' color with One color, or the color they start from with Color to full color."] = "El color de los puntos con «Un color», o su color de partida con «Color hasta color lleno»."
L["The players who keep DaylightUI going. Thank you."] = "Los jugadores que mantienen DaylightUI en marcha. Gracias."
L["The power bar's color when Power bar color is One color."] = "El color de la barra de poder cuando «Color de la barra de poder» está en «Un color»."
L["The power text shows while mana, rage or energy is full too. When off, it disappears at full."] = "El texto de poder se muestra también cuando el maná, la ira o la energía están llenos. Desactivado, desaparece cuando está lleno."
L["The pressed border's color when Pressed border color is set to Your own color."] = "El color del borde al pulsar cuando «Color del borde al pulsar» está en «Tu propio color»."
L["The priority quest's color while Priority quest color is set to Custom."] = "El color de la misión prioritaria cuando «Color de la misión prioritaria» está en «Personalizado»."
L["The proc border's color when Proc border is set to Your own color."] = "El color del borde de activación cuando «Borde de activación» está en «Tu propio color»."
L["The profile %s is ready. Choose it for this character (or a talent set) to use it."] = "El perfil %s está listo. Elígelo para este personaje (o un conjunto de talentos) para usarlo."
L["The profile %s: its settings, frame positions and Edit Mode layout. Ctrl+C to copy, then share it."] = "El perfil %s: sus ajustes, las posiciones de los marcos y el diseño del Modo de edición. Ctrl+C para copiar, y luego compártelo."
L["The profile for your first talent set. Changing it asks to reload."] = "El perfil de tu primer conjunto de talentos. Cambiarlo pide recargar."
L["The profile for your second talent set; swapping talents asks to switch."] = "El perfil de tu segundo conjunto de talentos; cambiar de talentos pide cambiar de perfil."
L["The profile in use as text to copy and share."] = "El perfil en uso, como texto para copiar y compartir."
L["The profile is ready. Reload to use it."] = "El perfil está listo. Recarga para usarlo."
L["The profile is used as it is; nothing in it changes."] = "El perfil se usa tal cual; nada de él cambia."
L["The profile this character uses. Changing it asks to reload."] = "El perfil que usa este personaje. Cambiarlo pide recargar."
L["The profile's Edit Mode layout will be set after the reload (%s)."] = "El diseño del Modo de edición del perfil se aplicará después de recargar (%s)."
L["The progress bars' color while Progress bar color is set to Custom."] = "El color de las barras de progreso cuando «Color de las barras de progreso» está en «Personalizado»."
L["The quest log on the world map."] = "El registro de misiones en el mapa del mundo."
L["The quest under the mouse stays bright, the others ease dimmer."] = "La misión bajo el ratón se mantiene brillante, las demás se atenúan suavemente."
L["The raid frames for 11 to 20 players. Show, fade, textures and fonts are on the Raid 10 page."] = "Los marcos de banda de 11 a 20 jugadores. Mostrar, desvanecer, texturas y fuentes están en la sección Banda 10."
L["The raid frames for 21 to 40 players. Show, fade, textures and fonts are on the Raid 10 page."] = "Los marcos de banda de 21 a 40 jugadores. Mostrar, desvanecer, texturas y fuentes están en la sección Banda 10."
L["The raid tiles' health text. General uses the font on General > Appearance."] = "El texto de salud de las casillas de banda. «General» usa la fuente de General > Apariencia."
L["The raid tiles' names. General uses the font on General > Appearance."] = "Los nombres de las casillas de banda. «General» usa la fuente de General > Apariencia."
L["The raid tiles' own name color. Same as the Colors page follows the name color every frame shares."] = "El color de nombre propio de las casillas de banda. «Como la sección Colores» sigue el color de nombre común a todos los marcos."
L["The ranged bar shows how far your target is instead of its name: Melee, Dead zone, 10 to 35 yd, Max range or Out of range."] = "La barra a distancia indica a qué distancia está tu objetivo en lugar de su nombre: Cuerpo a cuerpo, Zona muerta, 10 a 35 m, Alcance máx. o Fuera de alcance."
L["The ranged bar's color."] = "El color de la barra a distancia."
L["The red of a ring, name tab or raid tile while something is attacking the unit, or a color you pick."] = "El rojo de un anillo, de una pestaña de nombre o de una casilla de banda mientras algo ataca a la unidad, o un color a tu elección."
L["The reputation you're watching, always, on its own bar. Pick the faction on the Reputation page of the character window. Move it in unlock mode; drag its corner to resize."] = "La reputación que sigues, siempre, en su propia barra. Elige la facción en la sección Reputación de la ventana del personaje. Muévela en modo de desbloqueo; arrastra su esquina para cambiar su tamaño."
L["The ring (or name tab, or raid tile) that turns red while something is attacking the unit; an elite's dragon keeps its color, its eyes catch fire."] = "El anillo (o la pestaña de nombre, o la casilla de banda) que se pone rojo mientras algo ataca a la unidad; el dragón de un élite conserva su color, sus ojos arden."
L["The role icon stays in a fight. When off, it hides while you're fighting."] = "El icono de rol sigue visible en combate. Desactivado, se oculta mientras combates."
L["The row above the bar that holds the name and the health number."] = "La fila sobre la barra que contiene el nombre y el número de salud."
L["The same click again removes it."] = "El mismo clic de nuevo lo quita."
L["The same colors as in the game's chat settings: a change shows in every chat tab."] = "Los mismos colores que en los ajustes de chat del juego: un cambio se aplica a todas las pestañas del chat."
L["The same size as the top-right panel with its damage meter out."] = "El mismo tamaño que el panel de arriba a la derecha con su medidor de daño fuera."
L["The search failed. Try Refresh."] = "La búsqueda ha fallado. Prueba «Actualizar»."
L["The shade over the health your damage over time spells will still take, on the target and on enemy nameplates."] = "La sombra sobre la salud que tus hechizos de daño en el tiempo todavía van a quitar, en el objetivo y en las placas de nombre enemigas."
L["The shade that sweeps over a button while it's on cooldown."] = "La sombra que barre un botón mientras está en tiempo de reutilización."
L["The short tag before these messages. Left empty it stays [%s]."] = "La etiqueta corta delante de estos mensajes. Si se deja vacía, sigue siendo [%s]."
L["The side the whisper tiles and conversations slide out from. Left suits a chat on the right of your screen."] = "El lado desde el que deslizan las casillas y conversaciones de susurro. «Izquierda» conviene a un chat a la derecha de tu pantalla."
L["The size of each whisper tile."] = "El tamaño de cada casilla de susurro."
L["The size of the entrance, flight master, boat and zeppelin symbols on the world map. They keep this size as you zoom."] = "El tamaño de los símbolos de entrada, maestro de vuelo, barco y zepelín en el mapa del mundo. Mantienen este tamaño al hacer zoom."
L["The skull, star and other raid markers just left of the bar."] = "El cráneo, la estrella y los demás marcadores de banda justo a la izquierda de la barra."
L["The slim health bar. The name, the health number and the power line sit outside it."] = "La barra de salud fina. El nombre, el número de salud y la línea de poder quedan fuera de ella."
L["The small tab on the meter's left edge (it shows while the mouse is near) slides it out or back by hand."] = "La pequeña pestaña en el borde izquierdo del medidor (aparece cuando el ratón está cerca) lo saca o lo vuelve a meter manualmente."
L["The small tab that holds the name above the frame: its own border, corners, shadow, place and width."] = "La pequeña pestaña que contiene el nombre sobre el marco: su propio borde, esquinas, sombra, posición y anchura."
L["The small zone names over each group of quests."] = "Los pequeños nombres de zona sobre cada grupo de misiones."
L["The soft light behind the model on the Character page."] = "La luz suave detrás del modelo en la sección Personaje."
L["The soft light behind the model on the Character page. When off, only the window's background shows."] = "La luz suave detrás del modelo en la sección Personaje. Desactivado, solo se muestra el fondo de la ventana."
L["The sound when someone whispers you. The first five are gentle chimes made for DaylightUI; picking one plays it once."] = "El sonido cuando alguien te susurra. Los cinco primeros son suaves carillones diseñados para DaylightUI; elegir uno la reproduce una vez."
L["The space between the health bar and the power line under it."] = "El espacio entre la barra de salud y la línea de poder bajo ella."
L["The spell an enemy is casting, under its health bar."] = "El hechizo que lanza un enemigo, bajo su barra de salud."
L["The spell being cast, as a small icon left of the cast bar."] = "El hechizo que se está lanzando, como un pequeño icono a la izquierda de la barra de lanzamiento."
L["The spell name and time on the cast bars. General uses the font on General > Appearance."] = "El nombre del hechizo y el tiempo en las barras de lanzamiento. «General» usa la fuente de General > Apariencia."
L["The spell name and time on your cast bar."] = "El nombre del hechizo y el tiempo en tu barra de lanzamiento."
L["The spell name and time on your cast bar. General uses the font on General > Appearance."] = "El nombre del hechizo y el tiempo en tu barra de lanzamiento. «General» usa la fuente de General > Apariencia."
L["The spell name and time on your focus's cast bar. General uses the font on General > Appearance."] = "El nombre del hechizo y el tiempo en la barra de lanzamiento de tu foco. «General» usa la fuente de General > Apariencia."
L["The spell name and time on your focus's cast bar. Inside the frame it's kept small enough for the power bar."] = "El nombre del hechizo y el tiempo en la barra de lanzamiento de tu foco. Dentro del marco se mantiene lo bastante pequeño para la barra de poder."
L["The spell name and time on your target's cast bar. General uses the font on General > Appearance."] = "El nombre del hechizo y el tiempo en la barra de lanzamiento de tu objetivo. «General» usa la fuente de General > Apariencia."
L["The spell name and time on your target's cast bar. Inside the frame it's kept small enough for the power bar, unless Text size inside the frame is set."] = "El nombre del hechizo y el tiempo en la barra de lanzamiento de tu objetivo. Dentro del marco se mantiene lo bastante pequeño para la barra de poder, salvo que «Tamaño del texto dentro del marco» esté definido."
L["The spell name and timer on the target's cast bar."] = "El nombre del hechizo y el temporizador en la barra de lanzamiento del objetivo."
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 uses Target cast bar text size, kept small enough for the power bar."] = "El nombre del hechizo y el temporizador cuando la barra está dentro del marco del objetivo, incluso por encima de la altura de la barra de poder. 0 usa «Tamaño del texto de la barra de lanzamiento del objetivo», que se mantiene lo bastante pequeño para la barra de poder."
L["The spell's icon at the end of your focus's cast bar. Not while it sits inside the frame."] = "El icono del hechizo al final de la barra de lanzamiento de tu foco. No cuando está dentro del marco."
L["The spell's icon at the end of your target's cast bar. Not while it sits inside the frame."] = "El icono del hechizo al final de la barra de lanzamiento de tu objetivo. No cuando está dentro del marco."
L["The spell's name on every cast bar."] = "El nombre del hechizo en todas las barras de lanzamiento."
L["The spell's own"] = "La del hechizo"
L["The spell's own color (Renew green, a shield blue), or one you pick."] = "El color propio del hechizo (Renovar en verde, un escudo en azul), o un color a tu elección."
L["The spellbook and talent keys open DaylightUI's window. In a fight the game's own book opens, so you can still drag spells to your bars. Turn it off to always use the game's window."] = "Las teclas del libro de hechizos y de talentos abren la ventana de DaylightUI. En combate se abre el libro de hechizos del juego, para que puedas seguir arrastrando hechizos a tus barras. Desactívalo para usar siempre la ventana del juego."
L["The spellbook and talents, the profession windows, the professions book, the stable."] = "El libro de hechizos y talentos, las ventanas de profesiones, el libro de profesiones, el establo."
L["The square minimap in the panel."] = "El minimapa cuadrado en el panel."
L["The square's color when Heal indicator color is Custom color."] = "El color del cuadrado cuando «Color del indicador de sanación» está en «Color personalizado»."
L["The stat group headers and the headers on the other pages. Each its own: a color per stat group, used in turn on the other pages."] = "Los encabezados de los grupos de estadísticas y los de las demás secciones. «Cada uno el suyo»: un color por grupo de estadísticas, usados por turnos en las demás secciones."
L["The sweep can't start in combat."] = "El barrido no puede empezar en combate."
L["The swing timer's hand and time. General uses the font on General > Appearance."] = "La mano y el tiempo que muestra. «General» usa la fuente de General > Apariencia."
L["The tag after a PvP quest's title."] = "La etiqueta tras el título de una misión JcJ."
L["The tag after a dungeon quest's title."] = "La etiqueta tras el título de una misión de mazmorra."
L["The tag after a raid quest's title."] = "La etiqueta tras el título de una misión de banda."
L["The tag after an elite quest's title."] = "La etiqueta tras el título de una misión élite."
L["The talents you're using now."] = "Los talentos que estás usando ahora."
L["The target and focus cast bars' color for a moment after their cast is interrupted."] = "El color de las barras de lanzamiento del objetivo y del foco durante un momento tras una interrupción."
L["The target and focus cast bars' color while they cast."] = "El color de las barras de lanzamiento del objetivo y del foco durante un lanzamiento."
L["The target and focus cast bars' color while they channel."] = "El color de las barras de lanzamiento del objetivo y del foco durante una canalización."
L["The target's and target of target's class and power gradients run the other way, so they mirror yours. Only for a horizontal gradient."] = "Los degradados de clase y de poder del objetivo y del objetivo del objetivo van en sentido contrario, en espejo de los tuyos. Solo para un degradado horizontal."
L["The text in DaylightUI's windows (character, spellbook, professions, bags, quest journal) and the game's windows it restyles. General uses the font above."] = "El texto de las ventanas de DaylightUI (personaje, libro de hechizos, profesiones, bolsas, diario de misiones) y de las ventanas del juego que rediseña. «General» usa la fuente de arriba."
L["The textures above show on every bar at once, except where a frame's own page or the window bars below pick another. This puts every one of those back on the textures above."] = "Las texturas de arriba se muestran en todas las barras a la vez, salvo cuando la sección propia de un marco o las barras de ventana de abajo elijan otra. Esto devuelve todas ellas a las texturas de arriba."
L["The thin line under each header. Like the tab underline: whatever Tab underline below is set to. Class gradient uses your class's colors from the Gradients page."] = "La fina línea bajo cada encabezado. Como el subrayado de pestaña: lo que esté definido en «Subrayado de pestaña» más abajo. «Degradado de clase» usa los colores de tu clase de la sección Degradados."
L["The thin power bar under the health bar."] = "La fina barra de poder bajo la barra de salud."
L["The thin strip under the minimap with gold, gear, bag space and more."] = "La franja fina bajo el minimapa con el oro, el equipo, el espacio de las bolsas y más."
L["The threat bars' color when Bar color is One color."] = "El color de las barras de amenaza cuando «Color de la barra» está en «Un color»."
L["The threat colors slowly brighten and dim, quicker when a mob is about to switch. Needs the health bar, border or glow above."] = "Los colores de amenaza se aclaran y se oscurecen lentamente, más rápido cuando una criatura está a punto de cambiar de objetivo. Necesita la barra de salud, el borde o el resplandor de arriba."
L["The tick next to a finished objective."] = "La marca de verificación junto a un objetivo completado."
L["The time at the bottom of the minimap."] = "La hora en la parte inferior del minimapa."
L["The time before each message (the game's own setting)."] = "La hora antes de cada mensaje (ajuste del juego)."
L["The time left as a number on each icon."] = "El tiempo restante en números sobre cada icono."
L["The time left on a timed quest once it's under a minute."] = "El tiempo restante de una misión cronometrada cuando baja de un minuto."
L["The time left on a timed quest."] = "El tiempo restante de una misión cronometrada."
L["The time on every cast bar: what's left, what's left out of the whole cast, or nothing."] = "El tiempo en todas las barras de lanzamiento: lo que queda, lo que queda de la duración total del lanzamiento, o nada."
L["The tint on a button while your target is out of range, when Out of range is set to Tint the icon."] = "El tinte de un botón mientras tu objetivo está fuera de alcance, cuando «Fuera de alcance» está en «Teñir el icono»."
L["The tooltip text; titles are a little larger."] = "El texto de las descripciones emergentes; los títulos son un poco más grandes."
L["The top-right panel: experience bar on top, damage meter and minimap below. Move it in unlock mode."] = "El panel de arriba a la derecha: barra de experiencia arriba, medidor de daño y minimapa debajo. Muévelo en modo de desbloqueo."
L["The two ends of the bar's gradient. With Gradient off, the bar takes the bright end."] = "Los dos extremos del degradado de la barra. Con «Degradado» desactivado, la barra toma el extremo claro."
L["The two-color fills bars use when set to a gradient (Class gradient on unit frames and nameplates, power bars)."] = "Los rellenos bicolores que usan las barras cuando están en degradado («Degradado de clase» en los marcos de unidad y las placas de nombre, barras de poder)."
L["The unit you set as focus."] = "La unidad que has definido como foco."
L["The unit's health as text at the right end of the bar. Pick the format under Health text."] = "La salud de la unidad como texto en el extremo derecho de la barra. Elige el formato en «Texto de salud»."
L["The unit's health written on this frame."] = "La salud de la unidad escrita en este marco."
L["The unit's level at the left end of the bar, in the game's difficulty color; ?? for one far above you, + for an elite."] = "El nivel de la unidad en el extremo izquierdo de la barra, con el color de dificultad del juego; ?? para una unidad muy por encima de ti, + para un élite."
L["The whole Bank and alts window, slots, text and buttons together."] = "Toda la ventana de Banco y personajes: ranuras, texto y botones juntos."
L["The whole bag window, slots, text and buttons together."] = "Toda la ventana de las bolsas: ranuras, texto y botones juntos."
L["The whole bank window, slots, text and buttons together."] = "Toda la ventana del banco: ranuras, texto y botones juntos."
L["The whole bar, icons, text and background together."] = "Toda la barra: iconos, texto y fondo juntos."
L["The whole feed. Also the mouse wheel over its handle in /dui unlock."] = "Todo el flujo. También con la rueda del ratón sobre su asidero en /dui unlock."
L["The whole group shows only during a fight."] = "El grupo entero solo se muestra durante un combate."
L["The whole group shows only in a party or raid."] = "El grupo entero solo se muestra en grupo o en banda."
L["The whole pop-up, text and bar together."] = "Toda la ventana emergente: texto y barra juntos."
L["The width of a whisper conversation. It slides out beside the tiles, as tall as the chat."] = "La anchura de una conversación de susurro. Se desliza al lado de las casillas, con la misma altura que el chat."
L["The window's title shows the player's last name after their first name."] = "El título de la ventana muestra el apellido del jugador después de su nombre."
L["The world map's quest list and quest pages in DaylightUI style, with Track, Share and Abandon on each quest. Turn it off to use the game's own."] = "La lista de misiones del mapa del mundo y las secciones de misiones al estilo DaylightUI, con Seguir, Compartir y Abandonar en cada misión. Desactívalo para usar las del juego."
L["The zone or area you're in, at the top of the map (above the coordinates)."] = "La zona o el lugar donde estás, arriba del mapa (encima de las coordenadas)."
L["The zone or area you're in, at the top of the minimap."] = "La zona o el lugar donde estás, arriba del minimapa."
L["Their class icon"] = "Su icono de clase"
L["Their health as text at the right end of the bar."] = "Su salud en forma de texto en el extremo derecho de la barra."
L["Their initial"] = "Su inicial"
L["Their initial in their class's colors, or their class icon from the set picked in Unit Frames (Daylight UI's own or a Jiberish style)."] = "Su inicial en los colores de su clase, o su icono de clase del conjunto elegido en Marcos de unidad (el de Daylight UI o un estilo Jiberish)."
L["Their keybinds work even when hidden. Move them in unlock mode."] = "Sus atajos de teclado funcionan incluso ocultos. Muévelos en modo de desbloqueo."
L["Their level at the left end of the bar."] = "Su nivel en el extremo izquierdo de la barra."
L["Their own window"] = "Su propia ventana"
L["Their own window and the chat"] = "Su propia ventana y el chat"
L["Their own window: a tile beside the chat for each person you talk to; click one to open the conversation. The chat only: whispers stay in the chat like any other message."] = "Su propia ventana: una casilla junto al chat por cada persona con la que hablas; haz clic en una para abrir la conversación. Solo el chat: los susurros se quedan en el chat como cualquier otro mensaje."
L["These are for talent set %s; each talent set keeps its own."] = "Estos afectan al conjunto de talentos %s; cada conjunto de talentos conserva los suyos."
L["These talents use the profile %s. Switch to it?"] = "Estos talentos usan el perfil %s. ¿Cambiar a él?"
L["They come back if you log in on them."] = "Vuelven si entras con ellos."
L["Thick"] = "Grueso"
L["Thin"] = "Fino"
L["Thin lines split the bar into 20 parts, like the classic bar: each one is 5% of a level."] = "Las líneas finas dividen la barra en 20 partes, como la barra clásica: cada una vale un 5 % de un nivel."
L["This Legacy tree isn't available yet."] = "Este árbol Legado aún no está disponible."
L["This bar's own name size. Text size, under Whole group, sizes every bar's."] = "El tamaño de nombre propio de esta barra. «Tamaño del texto», bajo «Grupo entero», regula el de todas las barras."
L["This character"] = "Este personaje"
L["This character hasn't finished the setup guide, so moved frames go back when you log out. Type /dui install to finish it."] = "Este personaje no ha terminado la guía de configuración, así que los marcos movidos volverán a su sitio al cerrar sesión. Escribe /dui install para terminarla."
L["This character hasn't finished the setup guide, so what you change or move is lost when you log out. Finish the guide first, then make your changes."] = "Este personaje no ha terminado la guía de configuración, así que lo que cambies o muevas se perderá al cerrar sesión. Termina primero la guía y luego haz tus cambios."
L["This character's, for the talent set in use. Covers your player, target, target of target, pet, focus, party and raid frames."] = "Los de este personaje, para el conjunto de talentos activo. Afecta a tus marcos de jugador, objetivo, objetivo del objetivo, mascota, foco, grupo y banda."
L["This client has no aura container; target auras are off."] = "Este cliente no tiene contenedor de auras; las auras del objetivo están desactivadas."
L["This fight"] = "Este combate"
L["This frame's health text and large number. General uses the font on General > Appearance."] = "El texto de salud y el número grande de este marco. «General» usa la fuente de General > Apariencia."
L["This frame's names, and its level badge. General uses the font on General > Appearance."] = "Los nombres de este marco, y su distintivo de nivel. «General» usa la fuente de General > Apariencia."
L["This frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares."] = "El color de salud propio de este marco, para que pueda verse distinto a los demás. «Como la sección Colores» sigue el color común a todos los marcos."
L["This frame's own name color. Same as the Colors page follows the name color every frame shares."] = "El color de nombre propio de este marco. «Como la sección Colores» sigue el color de nombre común a todos los marcos."
L["This frame's own outline, corners and shadow, so it can stand apart from the rest of your UI."] = "El contorno, las esquinas y la sombra propios de este marco, para que destaque del resto de tu interfaz."
L["This frame's own power color. Same as the Colors page follows the color every frame shares."] = "El color de poder propio de este marco. «Como la sección Colores» sigue el color común a todos los marcos."
L["This frame's power text. General uses the font on General > Appearance."] = "El texto de poder de este marco. «General» usa la fuente de General > Apariencia."
L["This group's header. The other pages use the six colors in turn."] = "El encabezado de este grupo. Las demás secciones usan los seis colores por turnos."
L["This icon's own size. Whole group, below, sizes every icon in the group."] = "El tamaño propio de este icono. «Grupo entero», más abajo, regula todos los iconos del grupo."
L["This level"] = "Este nivel"
L["This session"] = "Esta sesión"
L["This set hasn't been used yet. Activate it to spend its points."] = "Este conjunto aún no se ha usado. Actívalo para gastar sus puntos."
L["This setting"] = "Este ajuste"
L["This zone"] = "Esta zona"
L["This zone only"] = "Solo esta zona"
L["Those quiet errors play one soft, low tick in place of the voice line, never in a burst. Follows Soft UI sounds (General > Sound)."] = "Estos errores discretos reproducen un tic suave y grave en lugar de la réplica de voz, nunca en ráfaga. Sigue la opción «Sonidos de interfaz suaves» (General > Sonido)."
