L["Turn the Party frame on or off."] = "Activar o desactivar el marco de grupo."
L["Turn the Pet frame on or off."] = "Activar o desactivar el marco de la mascota."
L["Turn the Player frame on or off."] = "Activar o desactivar el marco del jugador."
L["Turn the Target frame on or off."] = "Activar o desactivar el marco del objetivo."
