L["Two-color gradient"] = "Degradado bicolor"
L["Type"] = "Tipo"
L["Type DELETE for me"] = "Escribir ELIMINAR por mí"
L["Type a buff's name and pick where it belongs."] = "Escribe el nombre de un beneficio y elige dónde debe ir."
L["Uncommon (green) and up"] = "Poco común (verde) y superiores"
L["Under a day"] = "Menos de un día"
L["Under its owner"] = "Bajo su propietario"
L["Under the action bars"] = "Bajo las barras de acción"
L["Under the bar (the cast bar moves down) or over it (the name moves up)."] = "Bajo la barra (la barra de lanzamiento baja) o encima de ella (el nombre sube)."
L["Under the cast bar"] = "Bajo la barra de lanzamiento"
L["Under the frame (slides out)"] = "Bajo el marco (desplegable)"
L["Under the frame it continues the frame's angle and slides out as you cast. Above the frame or on its own it has its own size."] = "Bajo el marco, prolonga el ángulo del marco y se desliza al lanzar un hechizo. Encima del marco o independiente, tiene su propio tamaño."
L["Under the frame, it continues the frame's angle. When off, its end is straight."] = "Bajo el marco, prolonga el ángulo del marco. Desactivado, su extremo queda recto."
L["Under the frame, or over it, clear of the name. The target's buffs or debuffs on that side move out of the way."] = "Bajo el marco, o encima, apartado del nombre. Los beneficios o perjuicios del objetivo de ese lado se desplazan para dejar sitio."
L["Under the meter"] = "Bajo el medidor"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (left or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Bajo el medidor, surge desde la parte inferior del medidor de daño dentro del panel, tan ancho como él, y las líneas del medidor le hacen sitio. Anclado (a la izquierda o debajo), solo se muestra si el medidor de daño está abierto. Su propia ventana puede ir a cualquier lugar: muévela en modo de desbloqueo (/dui unlock) y arrastra su esquina para cambiar su tamaño."
L["Under the meter it's part of the panel, with no window of its own."] = "Bajo el medidor, forma parte del panel, sin ventana propia."
L["Under the panel"] = "Bajo el panel"
L["Underline color"] = "Color del subrayado"
L["Undo"] = "Deshacer"
L["Unexplored area brightness"] = "Brillo de las zonas no exploradas"
L["Unfold"] = "Desplegar"
L["Unfriendly"] = "Poco amistoso"
L["Unhook it"] = "Desengancharlo"
L["Unit Frames"] = "Marcos de unidad"
L["Unknown"] = "Desconocido"
L["Unknown command '%s'."] = "Comando desconocido «%s»."
L["Unknown spell"] = "Hechizo desconocido"
L["Unlearn"] = "Olvidar"
L["Unlist"] = "Quitar de la lista"
L["Unlock"] = "Desbloquear"
L["Unlock frames"] = "Desbloq. marcos"
L["Unlock the chat's size"] = "Desbloquear el tamaño del chat"
L["Unlock the chat: drag the tab row to move it, a corner to size it"] = "Desbloquear el chat: arrastra la fila de pestañas para moverlo, una esquina para cambiar el tamaño"
L["Unlocked. Drag to move, scroll to resize, right-click to put back, /dui lock when done."] = "Desbloqueado. Arrastra para mover, usa la rueda para cambiar el tamaño, clic derecho para devolverlo a su sitio, /dui lock al terminar."
L["Unpin"] = "Desanclar"
L["Untrack"] = "Dejar de seguir"
L["Untrack all"] = "Dejar de seguir todo"
L["Up"] = "Arriba"
L["Up and Down scroll the text in a straight line. Arc bursts it out to the side and curves it up."] = "«Arriba» y «Abajo» desplazan el texto en línea recta. «Arco» lo hace estallar hacia un lado y lo curva hacia arriba."
L["Up early. Even the murlocs are still asleep."] = "Madrugas mucho. Hasta los murlocs siguen durmiendo."
L["Up to three, at the debuffs' size, with a countdown. They only appear when a boss uses them. With the game's buff frames shown, the game shows them there instead."] = "Hasta tres, al tamaño de los perjuicios, con una cuenta atrás. Solo aparecen cuando un jefe los usa. Si los marcos de beneficios del juego están visibles, el juego los muestra allí en su lugar."
L["Up to two big icons in the middle, with a sweep for the time left. They only appear when a boss uses them."] = "Hasta dos iconos grandes en el centro, con una animación de barrido para el tiempo restante. Solo aparecen cuando un jefe los usa."
L["Up: newest at the bottom"] = "Hacia arriba: los más recientes abajo"
L["Update"] = "Actualizar"
L["Usable glow color"] = "Color del resplandor utilizable"
L["Usable or proc"] = "Utilizable o activación"
L["Usage: /dui buffs toggle <category name>"] = "Uso: /dui buffs toggle <nombre de categoría>"
L["Use"] = "Usar"
L["Use DaylightUI's"] = "Usar el de DaylightUI"
L["Use DaylightUI's Cooldown Manager"] = "Usar el gestor de reutilización de DaylightUI"
L["Use DaylightUI's quest tracker"] = "Usar el seguimiento de misiones de DaylightUI"
L["Use a setup I have"] = "Usar una configuración que ya tengo"
L["Use accent color"] = "Usar el color de acento"
L["Use guild money first"] = "Utilizar primero el dinero de la hermandad"
L["Use my language's font"] = "Usar la fuente de mi idioma"
L["Use my layout on this character"] = "Usar mi diseño en este personaje"
L["Use raid frames in a party"] = "Usar marcos de banda en un grupo"
L["Use this"] = "Usar esto"
L["Use this font for the game's text"] = "Usar esta fuente para el texto del juego"
L["Use this heal indicator"] = "Usar este indicador de sanación"
L["Used by all DaylightUI text, except where a frame's own page picks another font. Game font is the client's own, including a font you've replaced it with. Fonts other addons share (SharedMedia) are listed after ours."] = "Usada por todo el texto de DaylightUI, salvo cuando la sección de un marco elige otra fuente. «Fuente del juego» es la del cliente, incluida una fuente que le hayas sustituido. Las fuentes que comparten otros addons (SharedMedia) aparecen después de las nuestras."
L["Used when Unit Frames > Extras > Combo points > Colors is a gradient: All points fills every pip with one pair, Point 1 to 5 give each pip its own."] = "Se usa cuando Marcos de unidad > Extras > Puntos de combo > Colores es un degradado: «Todos los puntos» rellena cada punto con un mismo par, «Punto 1 a 5» da a cada punto el suyo."
L["Uses the Raid 10 frames, and the rows below are grayed out. Turn it off to give this raid size its own, starting from a copy of Raid 10."] = "Usa los marcos Raid 10, y las filas de abajo aparecen en gris. Desactívalo para dar a este tamaño de banda sus propios marcos, a partir de una copia de Raid 10."
L["Uses the game's own font in place of DaylightUI's fonts, which only have Latin letters. The options window changes after /reload."] = "Usa la fuente del juego en lugar de las de DaylightUI, que solo tienen letras latinas. La ventana de opciones cambia después de /reload."
L["Usually General."] = "Generalmente General."
L["Usually Local Defense."] = "Generalmente DefensaLocal."
L["Usually Looking for Group."] = "Generalmente BuscarGrupo."
L["Usually Trade."] = "Generalmente Comercio."
L["Usually a skill point"] = "Generalmente un punto de habilidad"
L["Varela Round"] = "Varela Round"
L["Vendor window"] = "Ventana del comerciante"
L["Vendors"] = "Comerciantes"
L["Vendors open in the NPC window too, with their goods on a shelf. Turn it off to use the game's vendor window."] = "Los comerciantes también se abren en la ventana de PNJ, con sus artículos en una estantería. Desactívalo para usar la ventana de comerciante del juego."
L["Version %s."] = "Versión %s."
L["Vertical (light on top)"] = "Vertical (claro arriba)"
L["Vertical bar"] = "Barra vertical"
L["View distance (yards)"] = "Distancia de visión (metros)"
L["Visibility"] = "Visibilidad"
L["Visible"] = "Visible"
L["Voice chat and channels"] = "Chat de voz y canales"
L["Volume"] = "Volumen"
L["Waist"] = "Cintura"
L["Wait for the talents being applied."] = "Espera a que se apliquen los talentos."
L["Walking Boots"] = "Botas de caminante"
L["Warlock"] = "Brujo"
L["Warm bell"] = "Campana cálida"
L["Warmed by the fire"] = "Calentado por el fuego"
L["Warns you when a mob is about to change target, or has."] = "Te avisa cuando un monstruo está a punto de cambiar de objetivo, o lo ha hecho."
L["Warrior"] = "Guerrero"
L["Weapon"] = "Arma"
L["Weapon Enchant"] = "Encantamiento de arma"
L["Weapon icon"] = "Icono de arma"
L["Weapon master"] = "Maestro de armas"
L["Weapons"] = "Armas"
L["Wearing it"] = "Equipado"
L["Web addresses in messages become links; click one to copy it."] = "Las direcciones web de los mensajes se convierten en enlaces; haz clic en una de ellas para copiarla."
L["Website: %s"] = "Sitio web: %s"
L["Welcome"] = "Hola"
L["Welcome back, %s"] = "Hola de nuevo, %s"
L["Went out"] = "Salió"
L["What Alt-click on a quest in the tracker does."] = "La acción de un Alt-clic sobre una misión en el seguimiento."
L["What a button does while your target is out of range. Not enough mana, rage or energy does the same (blue when tinted)."] = "El comportamiento de un botón cuando tu objetivo está fuera de alcance. La falta de maná, ira o energía hace lo mismo (en azul si está teñido)."
L["What a click on a quest in the tracker does. Clicking its icon always makes it your priority, and right-click opens its menu."] = "La acción de un clic sobre una misión en el seguimiento. Hacer clic en su icono siempre la convierte en tu prioridad, y el clic derecho abre su menú."
L["What a friendly NPC does (Innkeeper, Flight Master...) under its name, smaller."] = "La función de un PNJ amistoso (Posadero, Maestro de vuelo...) bajo su nombre, en letra más pequeña."
L["What an NPC does (Skinner, Flight Master...) under its name, smaller. Not inside instances."] = "La función de un PNJ (Desollador, Maestro de vuelo...) bajo su nombre, en letra más pequeña. No en estancias."
L["What an interrupted cast bar does: Blade slices it in two, Shatter breaks it into shards, Snap cracks it in the middle, Burn out burns the fill away, Rewind whips it back to empty, Shockwave bursts light from it, Fizzle lets its light leak out. Your own interrupts light up in your accent color. Point at a choice to see it on the preview."] = "El efecto de una barra de lanzamiento interrumpida: «Hoja» la parte en dos, «Fragmentar» la rompe en pedazos, «Quebrar» la raja por la mitad, «Consumir» quema su relleno, «Rebobinar» la devuelve de golpe a vacío, «Onda de choque» hace brotar luz de ella, «Chisporrotear» deja escapar su luz. Tus propias interrupciones se iluminan en tu color de acento. Pasa el ratón sobre una opción para verla en la vista previa."
L["What changed in each version."] = "Los cambios de cada versión."
L["What changed in each version. Click a version to open or close it."] = "Los cambios de cada versión. Haz clic en una versión para abrirla o cerrarla."
L["What each enemy plate shows on and around its bar, and its colors."] = "Lo que muestra cada placa de nombre enemiga sobre y alrededor de su barra, y sus colores."
L["What each item's icon shows in the Bank and alts window."] = "Lo que muestra el icono de cada objeto en la ventana Banco y personajes."
L["What each item's icon shows in the bank."] = "Lo que muestra el icono de cada objeto en el banco."
L["What each item's icon shows."] = "Lo que muestra el icono de cada objeto."
L["What each slot shows, left to right. The clock, framerate and coordinates are on the minimap too."] = "Estos datos se mostrarán en la barra de datos inferior al minimapa. Hay datos, como los FPS, coordenadas y el reloj que también pueden estar dentro del mismo configurados desde la sección de Minimapa"
L["What fades, and when"] = "Qué se desvanece, y cuándo"
L["What happens to the fights you have so far when you enter a dungeon, raid or battleground: keep them, ask whether to reset, or reset at once. Running back after you die doesn't count."] = "Qué pasa con los combates que tienes hasta ahora cuando entras en una mazmorra, banda o campo de batalla: conservarlos, preguntar si restablecer o restablecer de inmediato. Volver tras morir no cuenta."
L["What happens to the fights you have so far when you join a group: keep them, ask whether to reset, or reset at once."] = "Qué pasa con los combates que tienes hasta ahora cuando te unes a un grupo: conservarlos, preguntar si restablecer o restablecer de inmediato."
L["What it shows"] = "Lo que muestra"
L["What sits between the text's parts."] = "Lo que hay entre las partes del texto."
L["What the away message says."] = "Lo que dice el mensaje de ausencia."
L["What the meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more. The button on the meter changes it too."] = "Lo que lista el medidor: daño, sanación, daño recibido, interrupciones, disipaciones, muertes y más. El botón del medidor también lo cambia."
L["What the second meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more."] = "Lo que lista el segundo medidor: daño, sanación, daño recibido, interrupciones, disipaciones, muertes y más."
L["What the target's or focus's cast bar does when its cast is interrupted. Your own interrupts light up in your accent color."] = "El efecto de la barra de lanzamiento del objetivo o del foco cuando su lanzamiento se interrumpe. Tus propias interrupciones se iluminan en tu color de acento."
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave."] = "Lo que hace el seguimiento cuando entras en una mazmorra, banda o campo de batalla. Vuelve a aparecer cuando sales."
L["What this extra text shows first, like the name, the level or the guild."] = "Lo que muestra primero este texto adicional, como el nombre, el nivel o la hermandad."
L["What this group takes. Click to change."] = "Lo que admite este grupo. Haz clic para cambiarlo."
L["What this slot on the data text strip shows. Slots count from the left."] = "Lo que muestra esta ranura de la barra de información. Las ranuras se cuentan desde la izquierda."
L["What you loot and your skill-ups, sliding in as ribbons at the bottom right."] = "Tu botín y tus subidas de habilidad, que aparecen deslizándose como cintas abajo a la derecha."
L["What you loot slides in at the bottom right of the screen in its quality color, more of the same adding to its count, and fades a few seconds later. Point at a line for the item's tooltip. Move it with /dui unlock."] = "Tu botín aparece deslizándose abajo a la derecha de la pantalla en el color de su calidad; las copias del mismo objeto suman a su contador, y se desvanece unos segundos después. Pasa el ratón sobre una línea para ver la descripción emergente del objeto. Muévelo con /dui unlock."
L["What's Training is still reading your spells."] = "What's Training sigue leyendo tus hechizos."
L["What's included"] = "Contenido"
L["What's new"] = "Novedades"
L["Wheel: louder or quieter"] = "Rueda: más alto o más bajo"
L["When Threat colors are on, they replace this color while showing."] = "Cuando los colores de amenaza están activados, sustituyen a este color mientras se muestran."
L["When a buff runs out, the spells after it slide over to fill its spot. When off, every spell keeps its place. A spell set to Keep its spot (Behavior tab) keeps it either way."] = "Cuando un beneficio expira, los hechizos siguientes se desplazan para ocupar su lugar. Desactivado, cada hechizo conserva su sitio. Un hechizo configurado en «Mantener su sitio» (pestaña Comportamiento) lo conserva en cualquier caso."
L["When a cast is interrupted, the bar stays full for a moment and says Interrupted."] = "Cuando un lanzamiento se interrumpe, la barra permanece llena un instante y muestra «Interrumpido»."
L["When a reputation goes up a standing, like Friendly to Honored, the new standing rises in at the top of the screen in its color, with the faction's name and a bar showing how far into it you are. Follows Motion effects (General > Appearance)."] = "Cuando una reputación sube de rango, por ejemplo de Amistoso a Honorable, el nuevo rango aparece en la parte superior de la pantalla en su color, con el nombre de la facción y una barra que muestra cuánto has avanzado en él. Sigue los Efectos de movimiento (General > Apariencia)."
L["When an NPC has only one thing to offer (a vendor, flight master, banker or trainer) and no quests, its window opens straight away. Hold Shift to see the dialogue."] = "Cuando un PNJ solo tiene una cosa que ofrecer (un comerciante, un maestro de vuelo, un banquero o un instructor) y ninguna misión, su ventana se abre directamente. Mantén pulsada Mayús para ver el diálogo."
L["When auto loot is on, everything is picked up at once instead of one item at a time."] = "Cuando el botín automático está activado, todo se recoge de una vez en lugar de un objeto cada vez."
L["When hovering a button shows its spell or item tooltip."] = "Al pasar el ratón sobre un botón se muestra la descripción emergente de su hechizo u objeto."
L["When it shows"] = "Cuándo se muestra"
L["When not usable"] = "Cuando no se puede usar"
L["When off, any debuff with a type (Magic, Curse, Disease, Poison) shows, even one you can't remove."] = "Desactivado, se muestra cualquier perjuicio con tipo (Magia, Maldición, Enfermedad, Veneno), incluso uno que no puedas disipar."
L["When off, the game's own bag windows are used."] = "Desactivado, se usan las ventanas de bolsas del juego."
L["When off, the game's tracker stays where Edit Mode puts it."] = "Desactivado, el seguimiento del juego se queda donde lo coloca el Modo de edición."
L["When ready"] = "Cuando esté listo"
L["When someone writes your name where people talk, it lights up in your accent color and the tab it lands in glows."] = "Cuando alguien escribe tu nombre donde se habla, se resalta en tu color de acento y la pestaña en la que aparece brilla."
L["When the accent color is a gradient (Daylight's or your class's), window borders run along it."] = "Cuando el color de acento es un degradado (el de Daylight o el de tu clase), los bordes de las ventanas lo siguen."
L["When the away message answers."] = "Cuando el mensaje de ausencia responde."
L["When the shown bag bar fades and how far."] = "Cuándo se desvanece la barra de bolsas mostrada, y hasta qué punto."
L["When the shown micro menu fades and how far."] = "Cuándo se desvanece el micromenú mostrado, y hasta qué punto."
L["When to show"] = "Cuándo mostrar"
L["When you destroy a good item, the confirmation box is filled in. You still press the button."] = "Cuando destruyes un objeto valioso, el cuadro de confirmación se rellena por ti. Aun así tienes que pulsar el botón."
L["When you dodge, parry or an attack misses you."] = "Cuando esquivas, paras o un ataque falla contra ti."
L["When you go away, the world dims, the UI fades and your character stands beside a card with your name, zone, rested XP and a fun fact. Move, click or press any key to come back. Never in combat, boss fights, keystones or PvP matches."] = "Cuando te ausentas, el mundo se oscurece, la interfaz se desvanece y tu personaje se queda de pie junto a una tarjeta con tu nombre, tu zona, tu PE de descanso y un dato curioso. Muévete, haz clic o pulsa cualquier tecla para volver. Nunca en combate, en combates contra jefes, con piedras angulares míticas ni en partidas JcJ."
L["When you have forms"] = "Si tienes formas"
L["When you have totems"] = "Si tienes tótems"
L["When your next auto-attack lands: a bar for each hand you swing with."] = "Cuando impacte tu siguiente ataque automático: una barra por cada mano con la que golpeas."
L["Where \"Kicked by\" and the name show: beside the cast bar or under it."] = "Dónde se muestran «Interrumpido por» y el nombre: junto a la barra de lanzamiento o debajo de ella."
L["Where along the frame the row starts: the angled end facing the middle of your screen, the middle, or the far end."] = "Dónde empieza la fila a lo largo del marco: el extremo biselado orientado hacia el centro de la pantalla, el centro o el extremo opuesto."
L["Where along the frame's top the tab sits. A full-width tab always starts at the outer end. Or drag the tab in Design mode."] = "Dónde se sitúa la pestaña a lo largo de la parte superior del marco. Una pestaña de ancho completo siempre empieza en el extremo exterior. También puedes arrastrar la pestaña en el modo de diseño."
L["Where along the power bar the power text sits."] = "Dónde se sitúa el texto de poder a lo largo de la barra de poder."
L["Where new lines come in."] = "Por dónde entran las líneas nuevas."
L["Where on the button its key shows."] = "Dónde se muestra la tecla en el botón."
L["Where on the frame this square sits."] = "Dónde se sitúa este cuadrado en el marco."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text."] = "Dónde aparece el cuadro en el que escribes. «Debajo del panel» le reserva una franja bajo el chat, para que nunca tape ningún texto."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text. At the bottom, the Daylight chat box lifts its messages over the box while you type."] = "Dónde aparece el cuadro en el que escribes. «Debajo del panel» le reserva una franja bajo el chat, para que nunca tape ningún texto. «Abajo», el cuadro de chat de Daylight eleva sus mensajes por encima del cuadro mientras escribes."
L["Where the dispel icon sits on each frame, or just outside it."] = "Dónde se sitúa el icono de disipación en cada marco, o justo fuera de él."
L["Where the interrupter's name shows: right of the cast bar or under it."] = "Dónde se muestra el nombre del interruptor: a la derecha de la barra de lanzamiento o debajo de ella."
L["Where the leader crown sits on each frame, or just outside it."] = "Dónde se sitúa la corona de líder en cada marco, o justo fuera de él."
L["Where the name sits across the bar, while it's on the bar: left, center or right."] = "Dónde se sitúa el nombre a lo largo de la barra, mientras esté sobre la barra: izquierda, centro o derecha."
L["Where the name sits across the bar: left, center or right."] = "Dónde se sitúa el nombre a lo largo de la barra: izquierda, centro o derecha."
L["Where the name sits inside its tab: left, center or right."] = "Dónde se sitúa el nombre dentro de su pestaña: izquierda, centro o derecha."
L["Where the numbers open when you hover the bar. Automatic opens them toward the middle of the screen."] = "Hacia dónde se abren los números cuando pasas el ratón sobre la barra. «Automático» los abre hacia el centro de la pantalla."
L["Where the raid marker sits on each frame, or just outside it."] = "Dónde se sitúa el marcador de banda en cada marco, o justo fuera de él."
L["Where the ready check answer sits on each frame, or just outside it."] = "Dónde se sitúa la respuesta a la comprobación de disponibilidad en cada marco, o justo fuera de él."
L["Where the role icon sits on each frame, or just outside it."] = "Dónde se sitúa el icono de rol en cada marco, o justo fuera de él."
L["Where the role, marker, crown and dispel icons sit on a tile."] = "Dónde se sitúan los iconos de rol, marcador, corona y disipación en una casilla."
L["Where things sit on your screen."] = "Dónde se colocan los elementos en tu pantalla."
L["Where this category sits on the bar."] = "Dónde se sitúa esta categoría en la barra."
L["Where this extra text sits on the frame, or just outside it."] = "Dónde se sitúa este texto adicional en el marco, o justo fuera de él."
L["Where this group sits in the bag."] = "Dónde se sitúa este grupo en la bolsa."
L["Where to start"] = "Por dónde empezar"
L["Where you put it"] = "Donde lo coloques"
L["Where your frames sit. Healers get the group as big tiles in the middle of the screen."] = "Dónde se sitúan tus marcos. Los sanadores ven el grupo como casillas grandes en el centro de la pantalla."
L["Whether each raid group is a column, side by side, or a row, stacked down."] = "Si cada grupo de banda es una columna, una al lado de otra, o una fila, apilada hacia abajo."
L["Whether the meter counts the fight you're in or every fight since the last reset."] = "Si el medidor cuenta el combate en el que estás o todos los combates desde el último restablecimiento."
L["Whether the name tab's end is cut at an angle. Same as the frame follows the frame's own end."] = "Si el extremo de la pestaña de nombre está recortado en ángulo. «Igual que el marco» sigue el extremo propio del marco."
L["Whether the party frames stack down or line up across."] = "Si los marcos del grupo se apilan hacia abajo o se alinean en horizontal."
L["Whether the second meter counts the fight you're in or every fight since the last reset."] = "Si el segundo medidor cuenta el combate en el que estás o todos los combates desde el último restablecimiento."
L["Whether this extra group shows debuffs or buffs."] = "Si este grupo adicional muestra perjuicios o beneficios."
L["Whether your bars and your frame step aside when you're not fighting. Every part has its own Visible setting later."] = "Si tus barras y tu marco se apartan cuando no estás en combate. Cada elemento tiene luego su propio ajuste de visibilidad."
L["Which bar the rows below set."] = "La barra que ajustan las filas de abajo."
L["Which buffs show."] = "Qué beneficios se muestran."
L["Which buffs this group shows."] = "Qué beneficios muestra este grupo."
L["Which buttons the look rows on this page change. A bar keeps what you change for it; the rest follows All bars."] = "Qué botones modifican las filas de apariencia de esta sección. Una barra conserva lo que cambias para ella; el resto sigue a «Todas las barras»."
L["Which corner of the button its count shows in."] = "En qué esquina del botón se muestra su número."
L["Which debuffs show."] = "Qué perjuicios se muestran."
L["Which debuffs this group shows."] = "Qué perjuicios muestra este grupo."
L["Which end of the group stays put when a spell in it hides."] = "Qué extremo del grupo permanece fijo cuando se oculta un hechizo de él."
L["Which frame the pips sit on."] = "En qué marco se sitúan los puntos."
L["Which key accepts, continues and completes. Enter is also the key that opens chat."] = "Qué tecla acepta, continúa y completa. Intro es también la tecla que abre el chat."
L["Which numbers"] = "Qué números"
L["Which of the four squares the rows below set."] = "Cuál de los cuatro cuadrados ajustan las filas de abajo."
L["Which part's fade the rows below set."] = "El elemento cuyo desvanecimiento ajustan las filas de abajo."
L["Which quest tracker?"] = "¿Qué seguimiento de misiones?"
L["Which side of its owner's frame each pet bar sits on."] = "En qué lado del marco de su dueño se sitúa cada barra de mascota."
L["Which side of the list the quest item buttons sit on."] = "En qué lado de la lista se sitúan los botones de objetos de misión."
L["Which stat groups start open. By class and spec: Attributes and the one that matters for you. Groups you open or fold yourself are remembered for each character."] = "Qué grupos de estadísticas empiezan abiertos. «Según clase y especialización»: los Atributos y el que te importa. Los grupos que abres o pliegas tú mismo se recuerdan para cada personaje."
L["Which way the color runs along a bar."] = "En qué sentido recorre el color una barra."
L["Which way the row adds its icons, starting from its position."] = "En qué sentido añade la fila sus iconos, a partir de su posición."
L["Which way the row of icons fills from its first icon."] = "En qué sentido se rellena la fila de iconos desde su primer icono."
L["While Heroic Strike, Cleave or Maul waits for your next swing, the melee bars change color and show its name."] = "Mientras «Golpe heroico», «Rajar» o «Magullar» espera a tu próximo golpe, las barras cuerpo a cuerpo cambian de color y muestran su nombre."
L["While it's off cooldown but you can't cast it: Overpower before a dodge, Riposte before a parry, Execute on a healthy target. Show leaves it dimmed. Hide keeps its gap: the other spells don't move."] = "Mientras no esté en reutilización pero no puedas lanzarlo: Abrumar antes de una esquiva, Contraataque antes de una parada, Ejecutar sobre un objetivo con salud alta. «Mostrar» lo deja atenuado. «Ocultar» mantiene su hueco: los demás hechizos no se mueven."
L["While moving frames, edges and centers line up with other frames. Hold Shift to drop anywhere."] = "Mientras mueves marcos, los bordes y los centros se alinean con otros marcos. Mantén pulsada Mayús para soltarlos en cualquier lugar."
L["While possessing"] = "Durante una posesión"
L["While swinging"] = "Durante los golpes"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting."] = "Durante los golpes: cada barra solo mientras dura su golpe, oculta entre golpes. En combate: todas tus barras mientras luchas."
L["While the buff or debuff isn't up, it keeps its spot as a grayed icon or an empty bar, so you see what's missing."] = "Mientras el beneficio o el perjuicio no esté activo, conserva su sitio como icono en gris o como barra vacía, para que veas lo que falta."
L["While the panel is away, how long each message stays before it fades. A new message doesn't bring old ones back. Move the mouse over the chat to see them all again."] = "Mientras el panel está oculto, cuánto tiempo permanece cada mensaje antes de desvanecerse. Un mensaje nuevo no hace volver a los anteriores. Pasa el ratón sobre el chat para volver a verlos todos."
L["While you cast, the power the spell will use is shaded on your power bar."] = "Mientras lanzas, el poder que consumirá el hechizo se sombrea en tu barra de poder."
L["While you have a bow, gun, crossbow, thrown weapon or wand."] = "Si tienes un arco, un arma de fuego, una ballesta, un arma arrojadiza o una varita."
L["While you have a target, every other plate fades so your target stands out. A plate that starts casting comes back to full."] = "Cuando tienes un objetivo, todas las demás placas de nombre se desvanecen para que destaque. Una placa que empieza a lanzar un hechizo vuelve a verse por completo."
L["While you have a target, your target's plate and all other plates use the sizes below (relative to Width, Health bar height and Scale)."] = "Cuando tienes un objetivo, su placa de nombre y todas las demás usan los tamaños de abajo (relativos a Anchura, Altura de la barra de salud y Escala)."
L["While you have a weapon in your off hand."] = "Si tienes un arma en la mano izquierda."
L["Whisper"] = "Susurrar"
L["Whisper %s"] = "Susurrar a %s"
L["Whisper color"] = "Color de los susurros"
L["Whisper sound"] = "Sonido de susurros"
L["Whisper tiles"] = "Casillas de susurro"
L["Whisper tiles show"] = "Las casillas de susurro muestran"
L["Whispered"] = "Susurros"
L["Battle.net whispers"] = "Susurros de Battle.net"
L["Game window skins"] = "Diseño de ventanas"
L["More windows"] = "Otras ventanas"
L["Spellbook, inspect, professions, group finder, mailbox, social and Legacy: each window's switch, its size and its own extras."] = "Libro de hechizos, inspeccionar, profesiones, buscador de grupos, buzón, social y Legado: el interruptor de cada ventana, su tamaño y sus extras."
L["Whispers"] = "Susurros"
L["Whispers are part of the Daylight chat box: /dui chat daylight to use it."] = "Los susurros forman parte del cuadro de chat de Daylight: /dui chat daylight para usarlo."
L["Whispers button"] = "Botón de susurros"
L["Whispers from your Battle.net friends, and yours to them."] = "Susurros de tus amigos de Battle.net, y los tuyos hacia ellos."
L["Whispers in their own tab"] = "Susurros en su propia pestaña"
L["Whispers open on the"] = "Los susurros se abren en el lado"
L["Whispers show in"] = "Los susurros se muestran en"
L["Whispers you get and send."] = "Los susurros que recibes y envías."
L["White"] = "Blanco"
L["White, the unit's class color, or one you pick."] = "Blanco, el color de clase de la unidad o uno que elijas."
L["Who"] = "Quién"
L["Who a player or creature is targeting, in their color (\">> You <<\" when it's you)."] = "A quién apunta un jugador o una criatura, en su color («>> Tú <<» cuando eres tú)."
L["Who interrupted position"] = "Posición de quien interrumpió"
L["Who to whisper?"] = "¿A quién susurrar?"
L["Who your target is looking at."] = "Lo que mira tu objetivo."
L["Who's closest to pulling your target, in a small window that slides out of the damage meter's left edge, along its bottom, or anywhere on its own."] = "Quién está más cerca de quitarle la amenaza a tu objetivo, en una pequeña ventana que sale del borde izquierdo del medidor de daño, a lo largo de su parte inferior, o en cualquier lugar, de forma independiente."
L["Whole bar"] = "Barra entera"
L["Whole group"] = "Grupo entero"
L["Whole row in full color at max points"] = "Fila entera en color pleno con el máximo de puntos"
L["Width"] = "Anchura"
L["William Pestle"] = "William Pestle"
L["Window"] = "Ventana"
L["Window background opacity"] = "Opacidad del fondo de las ventanas"
L["Window bar background"] = "Fondo de las barras de la ventana"
L["Window bar texture"] = "Textura de las barras de la ventana"
L["Window border"] = "Borde de la ventana"
L["Window font"] = "Fuente de la ventana"
L["Window height"] = "Altura de la ventana"
L["Window scale"] = "Escala de la ventana"
L["Window: talking opens a window at the side. Immersive: the talk is a card on the right, the camera comes in over your shoulder and the rest of the UI fades away until you're done. Vendors and trainers stay a window."] = "Ventana: hablar abre una ventana al lado. Inmersivo: la conversación es una tarjeta a la derecha, la cámara se acerca por encima de tu hombro y el resto de la interfaz se desvanece hasta que termines. Los vendedores y los instructores siguen siendo una ventana."
L["Windows"] = "Ventanas"
L["Windows glide in and out, tooltips fade in, a spell's icon pops when it's ready, gold and XP count up. When off, everything snaps into place."] = "Las ventanas se deslizan al abrirse y cerrarse, los avisos emergentes aparecen poco a poco, el icono de un hechizo destaca cuando está listo, y el oro y los PE suben contando. Si está desactivado, todo se coloca al instante."
L["Windows open & close"] = "Apertura y cierre de las ventanas"
L["Wisdom"] = "Sabiduría"
L["With Keep its spot (Buff missing), it shows only when you need to cast it, like Battle Shout."] = "Con «Conservar su sitio» (beneficio ausente), solo se muestra cuando necesitas lanzarlo, como Grito de batalla."
L["With Show under Buff missing, Hide makes it appear only when you need to cast it, like Battle Shout."] = "Con Mostrar bajo «Beneficio ausente», Ocultar hace que aparezca solo cuando necesitas lanzarlo, como Grito de batalla."
L["With a fishing pole equipped, a quick right-click on the world casts Fishing. With no bait on the pole, the first click puts on the best bait in your bags. Holding the button still turns the camera, and clicking an NPC, an object or the bobber works as usual. Hold Shift, Ctrl or Alt to skip the cast."] = "Con una caña de pescar equipada, un clic derecho rápido sobre el mundo lanza Pesca. Si no hay cebo en la caña, el primer clic pone el mejor cebo de tus bolsas. Mantener pulsado el botón sigue girando la cámara, y hacer clic en un PNJ, un objeto o el flotador funciona como de costumbre. Mantén pulsada Mayús, Ctrl o Alt para no lanzar."
L["With a pet"] = "Con una mascota"
L["With both on, it shows only when you're in a group and in combat. The second meter follows these too."] = "Si ambos están activados, solo se muestra cuando estás en grupo y en combate. El segundo medidor también sigue estos ajustes."
L["With chat open, Shift-click links the quest first."] = "Con el chat abierto, Mayús+clic inserta primero un enlace a la misión."
L["With items in categories, stacks of the same item show as one, with the total. They show apart while you trade or have the mailbox or auction house open, so you can Shift-click one to split it."] = "Con los objetos ordenados por categorías, las pilas de un mismo objeto se muestran como una sola, con el total. Se muestran por separado durante un intercambio o cuando el buzón o la casa de subastas están abiertos, para que puedas dividir una con Mayús+clic."
L["With items in categories, your Soul Shards show as one, with how many you have, though each still takes its own slot."] = "Con los objetos ordenados por categorías, tus fragmentos de alma se muestran como uno, con cuántos tienes, aunque cada uno siga ocupando su propia casilla."
L["With no portrait and no name tab, the role, marker, crown and dispel icons sit in the frame's corners."] = "Sin retrato ni pestaña de nombre, los iconos de rol, marcador, corona y disipación se sitúan en las esquinas del marco."
L["With the chat input at the bottom: while you type, the messages slide up and the box you type in sits under them, so it never covers a line."] = "Con la entrada del chat abajo: mientras escribes, los mensajes suben y el cuadro en el que escribes se sitúa debajo de ellos, para que nunca tape una línea."
L["With the immersive look, the NPC's words appear letter by letter and the choices drift in after them. Click or press the accept key to see them all at once."] = "Con el aspecto inmersivo, las palabras del PNJ aparecen letra a letra y las opciones llegan después. Haz clic o pulsa la tecla de aceptar para verlas todas de una vez."
L["With the immersive look, the camera comes in over your shoulder and looks at the NPC while you talk, then goes back to how you had it. Not while mounted or in a fight."] = "Con el aspecto inmersivo, la cámara se acerca por encima de tu hombro y mira al PNJ mientras hablas, y luego vuelve a como la tenías. No montado ni en combate."
L["With the immersive look, the whole UI fades away while you talk, so only the NPC and the talk are left. A fight brings everything back at once."] = "Con el aspecto inmersivo, toda la interfaz se desvanece mientras hablas, de modo que solo quedan el PNJ y la conversación. Un combate lo devuelve todo al instante."
L["Withdraw"] = "Retirar"
L["Withdraw gold"] = "Retirar oro"
L["Within each zone. Most recent progress moves a quest up when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "Dentro de cada zona. «Progreso más reciente» sube una misión cuando cuenta una baja, un objeto o un objetivo. «Más cercana primero» se vuelve a calcular cada pocos segundos mientras te desplazas, nunca en combate ni en mazmorra. Nada se mueve en combate."
L["Wood pop"] = "Chasquido de madera"
L["Words to light up"] = "Palabras que destacar"
L["Words to light up, separated by commas"] = "Palabras que destacar, separadas por comas"
L["World"] = "Mundo"
L["World map"] = "Mapa del mundo"
L["World markers"] = "Marcadores en el suelo"
L["World of Warcraft"] = "World of Warcraft"
L["Wowhead link"] = "Enlace de Wowhead"
L["Wowhead link (Ctrl+C copies it):"] = "Enlace de Wowhead (Ctrl+C para copiarlo):"
L["Wrists"] = "Muñecas"
L["Write a letter..."] = "Escribir una carta..."
L["Write a note to list for %s."] = "Escribe una nota para anotarte en %s."
L["Write a subject."] = "Escribe un asunto."
L["Write the full name: first and last."] = "Escribe el nombre completo: nombre y apellidos."
L["Writes zone names in capital letters. When off, they're written as the game writes them."] = "Escribe los nombres de zona en mayúsculas. Desactivado, se escriben como los escribe el juego."
L["XP"] = "PE"
L["XP bar"] = "Barra de experiencia"
L["XP bar position"] = "Posición de la barra de experiencia"
L["XP bar, damage meter and a square minimap in one corner panel."] = "Barra de experiencia, medidor de daño y minimapa cuadrado en un solo panel de esquina."
L["XP gain effects"] = "Efectos de ganancia de PE"
L["XP, reputation and skills"] = "PE, reputación y habilidades"
L["Yards under the arrow"] = "Metros bajo la flecha"
L["Yell"] = "Gritar"
L["Yell color"] = "Color de los gritos"
L["Yes"] = "Sí"
L["You"] = "Tú"
L["You block about 1 in %d attacks with your shield."] = "Bloqueas aproximadamente 1 de cada %d ataques con tu escudo."
L["You can also drag the chat's bottom-right corner to size it."] = "También puedes arrastrar la esquina inferior derecha del chat para cambiar su tamaño."
L["You can also switch with the button next to its search box."] = "También puedes cambiar con el botón junto a su cuadro de búsqueda."
L["You can also switch with the button next to the bank's search box."] = "También puedes cambiar con el botón junto al cuadro de búsqueda del banco."
L["You can also switch with the button next to the search box."] = "También puedes cambiar con el botón junto al cuadro de búsqueda."
L["You can make %d"] = "Puedes fabricar: %d"
L["You can reach rank %d this week"] = "Puedes alcanzar el rango %d esta semana"
L["You can track up to %d quests."] = "Puedes seguir hasta %d misiones."
L["You can't parry yet."] = "Todavía no puedes parar."
L["You carry %s."] = "Llevas %s."
L["You choose one of these:"] = "Eliges una de estas recompensas:"
L["You dodge about 1 in %d attacks."] = "Esquivas aproximadamente 1 de cada %d ataques."
L["You don't block yet."] = "No bloqueas todavía."
L["You don't dodge attacks yet."] = "Todavía no esquivas ataques."
L["You don't have that much gold."] = "No tienes tanto oro."
L["You get back %.0f mana every 5 seconds while not casting."] = "Recuperas %.0f puntos de maná cada 5 segundos mientras no lanzas hechizos."
L["You keep"] = "Conservas"
L["You parry about 1 in %d attacks from the front."] = "Paras aproximadamente 1 ataque frontal de cada %d."
L["You shoot every %.2f seconds. Lower is faster."] = "Disparas cada %.2f segundos. Cuanto más bajo, más rápido."
L["You'll also get:"] = "También obtendrás:"
L["You'll choose one of these:"] = "Elegirás una de estas recompensas:"
L["You're in a group: the leader tools work for real. Leave the group to practice with sample members."] = "Estás en grupo: las herramientas de líder funcionan de verdad. Abandona el grupo para practicar con miembros ficticios."
L["You're in combat; this finishes as soon as it ends."] = "Estás en combate; esto terminará en cuanto acabe."
L["You're not in a guild."] = "Aún no te has unido a una hermandad."
L["You're not in a raid."] = "No perteneces a ninguna banda."
L["You're on talent set %d, which has no profile. New and Import make one for it."] = "Estás en el conjunto de talentos %d, que no tiene perfil. Nuevo e Importar crean uno."
L["You're on talent set %d. The buttons below work on its profile, %s."] = "Estás en el conjunto de talentos %d. Los botones de abajo actúan sobre su perfil, %s."
L["You've already learned talents this build doesn't have. A trainer can reset them."] = "Ya has aprendido talentos que esta distribución no tiene. Un instructor puede restablecerlos."
L["Your Legacy Points, their rewards, the challenges that earn them and the Legacy trees, in one window, in DaylightUI style."] = "Tus puntos de legado, sus recompensas, los desafíos que los otorgan y los árboles de legado, en una sola ventana, con el estilo de DaylightUI."
L["Your accent, when the accent color is set to Custom color."] = "Tu acento, cuando el color de acento se ajusta a «Color personalizado»."
L["Your action bars and their buttons."] = "Tus barras de acción y sus botones."
L["Your attacks don't land critical hits yet."] = "Tus ataques todavía no logran golpes críticos."
L["Your attacks and spells miss %.1f%% less often."] = "Tus ataques y hechizos fallan %.1f%% menos a menudo."
L["Your bags are full."] = "Tus bolsas están llenas."
L["Your bank and your other characters' bags, from anywhere."] = "Tu banco y las bolsas de tus otros personajes, desde cualquier lugar."
L["Your bank from anywhere, and your other characters' bags and banks."] = "Tu banco desde cualquier lugar, y las bolsas y bancos de tus otros personajes."
L["Your bindings"] = "Tus atajos"
L["Your buffs"] = "Tus beneficios"
L["Your buffs and debuffs."] = "Tus beneficios y perjuicios."
L["Your buffs grow direction"] = "Sentido de crecimiento de tus beneficios"
L["Your buffs left / right"] = "Tus beneficios izquierda / derecha"
L["Your buffs position"] = "Posición de tus beneficios"
L["Your buffs sorted into color-coded groups; debuffs edged by type."] = "Tus beneficios ordenados en grupos con código de color; perjuicios con borde según su tipo."
L["Your buffs up / down"] = "Tus beneficios arriba / abajo"
L["Your buffs, minimap and info panel, quest tracker and chat fade away too, so only the fire and the world are left. Point at any of them to see it."] = "Tus beneficios, el minimapa, el panel de información, el seguimiento de misiones y el chat también se desvanecen, de modo que solo quedan el fuego y el mundo. Pasa el ratón sobre uno de ellos para verlo."
L["Your buffs, sorted into colored categories. Right-click a buff to cancel it; shift-click to move it to another category. The bar sits beside the info panel; to move it, turn off Attach to the info panel."] = "Tus beneficios, ordenados en categorías de colores. Clic derecho en un beneficio para cancelarlo; Mayús+clic para moverlo a otra categoría. La barra se sitúa junto al panel de información; para moverla, desactiva «Acoplar al panel de información»."
L["Your cast bar's color for a moment after your cast is interrupted."] = "El color de tu barra de lanzamiento durante un instante después de que se interrumpa tu lanzamiento."
L["Your cast bar's color while you cast."] = "El color de tu barra de lanzamiento mientras lanzas."
L["Your cast bar's color while you channel."] = "El color de tu barra de lanzamiento mientras canalizas."
L["Your cast bar's colors"] = "Colores de tu barra de lanzamiento"
L["Your casts and channels in your class color, or your class's gradient with a two-color fill. Not with the Daylight gradient."] = "Tus lanzamientos y canalizaciones en el color de tu clase, o en el degradado de tu clase con un relleno de dos colores. No con el degradado Daylight."
L["Your character window: gear, model, stats and the other pages. It opens with C, as always."] = "Tu ventana de personaje: equipo, modelo, estadísticas y las demás secciones. Se abre con C, como siempre."
L["Your chat also comes back the next time you log in on this character, under a gray line with when you left."] = "Tu chat también vuelve la próxima vez que inicies sesión con este personaje, bajo una línea gris que indica cuándo te fuiste."
L["Your class"] = "Tu clase"
L["Your class can heal; pick Healer if you do."] = "Tu clase puede curar; elige Sanador si es tu caso."
L["Your class's pick"] = "La elección de tu clase"
L["Your class's pick (%s)"] = "La elección de tu clase (%s)"
L["Your class's pick follows your class on every character. Pick one to watch it instead."] = "«La elección de tu clase» sigue a tu clase en cada personaje. Elige una para seguirla en su lugar."
L["Your damage over time spells: the end of the health they will still take is shaded darker."] = "Tus hechizos de daño en el tiempo: la parte de la salud que aún van a quitar se sombrea más oscura."
L["Your damage over time spells: the end of the health they will still take is shaded darker. The color is on Unit Frames > Colors."] = "Tus hechizos de daño en el tiempo: la parte de la salud que aún van a quitar se sombrea más oscura. El color se ajusta en Marcos de unidad > Colores."
L["Your debuffs"] = "Tus perjuicios"
L["Your debuffs, crowd control and buffs you can remove, on enemy plates."] = "Tus perjuicios, control de masas y beneficios que puedes disipar, en las placas de nombre enemigas."
L["Your focus's cast bar fills from the right. Not while it sits inside the frame."] = "La barra de lanzamiento de tu foco se llena desde la derecha. No mientras está dentro del marco."
L["Your focus's casts, while they last. It uses the target cast bar's colors."] = "Los lanzamientos de tu foco, mientras duren. Usa los colores de la barra de lanzamiento del objetivo."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange."] = "Color de salud propio de tu marco, para que pueda verse distinto de los demás. «Como la sección Colores» sigue el color que comparten todos los marcos; «Degradado Daylight» va del azul al naranja del logotipo."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange; Accent color follows your accent on General > Appearance, gradient included."] = "Color de salud propio de tu marco, para que pueda verse distinto de los demás. «Como la sección Colores» sigue el color que comparten todos los marcos; «Degradado Daylight» va del azul al naranja del logotipo; «Color de acento» sigue tu acento de General > Apariencia, degradado incluido."
L["Your frames"] = "Tus marcos"
L["Your frames per second beside the clock."] = "Tus imágenes por segundo junto al reloj."
L["Your frames per second beside the clock. Hover it for latency, addon CPU and memory."] = "Tus imágenes por segundo junto al reloj. Pasa el ratón sobre ellas para ver la latencia, la CPU y la memoria de los addons."
L["Your friends, recent allies, friend requests and the raid, in one window, in DaylightUI style."] = "Tus amigos, aliados recientes, solicitudes de amistad y la banda, en una sola ventana, con el estilo de DaylightUI."
L["Your group is too big for a %d-player activity."] = "Tu grupo es demasiado grande para una actividad de %d jugadores."
L["Your guild's officer chat."] = "El canal de oficiales de tu hermandad."
L["Your heals over time and shields, everything you cast, or all of them. A class without heals sees everything it casts."] = "Tus sanaciones en el tiempo y escudos, todo lo que lanzas, o todos. Una clase sin sanaciones ve todo lo que lanza."
L["Your health and mana come back faster while you're not fighting or casting."] = "Tu salud y tu maná se recuperan más rápido mientras no combates ni lanzas hechizos."
L["Your health and power just under your character, the way Legion's personal display sat at your feet."] = "Tu salud y tu poder justo debajo de tu personaje, como la barra personal de Legion a tus pies."
L["Your health bar, your power under it and, for rogues and druids, your combo points, just under your character. It follows the camera as you zoom."] = "Tu barra de salud, tu poder debajo y, para pícaros y druidas, tus puntos de combo, justo debajo de tu personaje. Sigue a la cámara al hacer zoom."
L["Your health. Each point adds about 10; you have %.0f."] = "Tu salud. Cada punto añade unos 10; tienes %.0f."
L["Your last name after your first, at the top of the window."] = "Tu apellido, después de tu nombre, en la parte superior de la ventana."
L["Your letters, sending, and what you made through the mail and the auction house, in one window, in DaylightUI style."] = "Tus cartas, el envío y lo que has obtenido por correo y por la casa de subastas, en una sola ventana, con el estilo de DaylightUI."
L["Your listing"] = "Tu anuncio"
L["Your main hand swings every %.2f seconds. Lower is faster."] = "Tu mano derecha ataca cada %.2f segundos. Cuanto más bajo, más rápido."
L["Your mana, rage or energy under the health bar."] = "Tu maná, ira o energía bajo la barra de salud."
L["Your melee attacks hit harder: Strength adds attack power."] = "Tus ataques cuerpo a cuerpo golpean más fuerte: la Fuerza aumenta el poder de ataque."
L["Your own buffs and heals over time, in a row above the name."] = "Tus propios beneficios y sanaciones en el tiempo, en una fila encima del nombre."
L["Your own color"] = "Tu propio color"
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. One layout per talent set, for this character."] = "Tu propio diseño de reutilización: cada hechizo que sigue el gestor de reutilización, en icono o en barra, colocado donde quieras y ajustado a los demás. Un diseño por conjunto de talentos, para este personaje."
L["Your own frame sits with the party's. When off, only the rest of the party shows."] = "Tu propio marco se coloca junto a los del grupo. Si está desactivado, solo se muestra el resto del grupo."
L["Your own frame."] = "Tu propio marco."
L["Your own groups"] = "Tus propios grupos"
L["Your own layout on this character. When off, this character's spells show where the game puts them, still in DaylightUI's look. Saved for this character."] = "Tu propio diseño en este personaje. Si está desactivado, los hechizos de este personaje se muestran donde los coloca el juego, siempre con el aspecto de DaylightUI. Guardado para este personaje."
L["Your own tile sits with the raid's. When off, only the rest of the raid shows."] = "Tu propia casilla se coloca junto a las de la banda. Si está desactivado, solo se muestra el resto de la banda."
L["Your party and raid as square tiles under you, dispels easy to spot."] = "Tu grupo y tu banda en casillas cuadradas bajo ti, con las disipaciones fáciles de localizar."
L["Your party: bars like your own frame, or square tiles. Set how they line up, what shows, and move them as one in unlock mode."] = "Tu grupo: barras como tu propio marco, o casillas cuadradas. Ajusta cómo se alinean y qué se muestra, y muévelos a la vez en el modo de desbloqueo."
L["Your pet"] = "Tu mascota"
L["Your pet or minion."] = "Tu mascota o esbirro."
L["Your pet's damage"] = "Daño de tu mascota"
L["Your pet's or totem's hits too."] = "También los golpes de tu mascota o de tus tótems."
L["Your picks are saved into %s."] = "Tus elecciones se guardan en %s."
L["Your portrait ring, or your name tab without a portrait, turns red while you're in combat."] = "El anillo de tu retrato, o tu pestaña de nombre sin retrato, se pone rojo mientras estás en combate."
L["Your priority quest is the one the marker and arrow lead to."] = "Tu misión prioritaria es aquella a la que llevan el marcador y la flecha."
L["Your profession's recipes in one window, in DaylightUI style."] = "Las recetas de tu profesión en una sola ventana, con el estilo de DaylightUI."
L["Your quest tracker."] = "Tu seguimiento de misiones."
L["Your quests in the DaylightUI look, with item buttons and smooth motion."] = "Tus misiones con el aspecto de DaylightUI, con botones de objetos y animaciones fluidas."
L["Your role"] = "Tu rol"
L["Your setup"] = "Tu configuración"
L["Your shots don't land critical hits yet."] = "Tus disparos todavía no logran golpes críticos."
L["Your spellbook and talents in one window, in DaylightUI style."] = "Tu libro de hechizos y tus talentos en una sola ventana, con el estilo de DaylightUI."
L["Your spells don't land critical hits yet."] = "Tus hechizos todavía no logran golpes críticos."
L["Your target's cast bar fills from the right. Not while it sits inside the frame."] = "La barra de lanzamiento de tu objetivo se llena desde la derecha. No mientras está dentro del marco."
L["Your target's casts, while they last."] = "Los lanzamientos de tu objetivo, mientras duren."
L["Your unit frames, shown here with sample units so you can see each choice."] = "Tus marcos de unidad, mostrados aquí con unidades ficticias para que veas cada elección."
L["Your watched quests, under the info panel. Move it in unlock mode."] = "Tus misiones seguidas, bajo el panel de información. Muévelo en el modo de desbloqueo."
L["Your x, y position at the top of the map. Blank in dungeons and raids."] = "Tu posición x, y en la parte superior del mapa. En blanco en mazmorras y bandas."
L["Your x, y position at the top of the minimap. Blank in dungeons and raids."] = "Tu posición x, y en la parte superior del minimapa. En blanco en mazmorras y bandas."
