L["[G] for General, [T] for Trade, [G] for guild (in guild green), [P] for party, [S] for say, [Y] for yell, [W] for whispers. Lines already in chat stay as they were."] = "[G] para General, [C] para Comercio, [H] para hermandad (en verde de hermandad), [Gp] para grupo, [D] para decir, [Gr] para gritar, [Su] para susurros. Las líneas que ya están en el chat se quedan como estaban."
L["[G] for General, [T] for Trade, [G] for guild (in guild green), [P] for party, [S] for say, [Y] for yell, [W] for whispers. Lines already in chat stay as they were. A chat tab's Show window sets your own tags."] = "[G] para General, [C] para Comercio, [H] para hermandad (en verde de hermandad), [Gp] para grupo, [D] para decir, [Gr] para gritar, [Su] para susurros. Las líneas que ya están en el chat se quedan como estaban. La opción Mostrar de una pestaña del chat define tus propias etiquetas."
L["\"Kicked by\" and the player's name in their class color, beside the cast bar for a moment."] = "«Interrumpido por» y el nombre del jugador en el color de su clase, junto a la barra de lanzamiento durante un instante."
L["\"Kicked by\" and the player's name in their class color, beside the target's or focus's cast bar for a moment."] = "«Interrumpido por» y el nombre del jugador en el color de su clase, junto a la barra de lanzamiento del objetivo o del foco durante un instante."
L["\"You create...\" and other crafting messages."] = "«Creas...» y otros mensajes de elaboración."
