-- DaylightUI 1.6.5.1

L["A ! after each crit."] = "Un signo ! tras cada crítico."
L["A - before damage and a + before heals."] = "Un − antes del daño y un + antes de las sanaciones."
L["A border and shadow around the experience bar's box and the threat meter's window."] = "Un borde y una sombra alrededor de la caja de la barra de experiencia y de la ventana del medidor de amenaza."
L["A border and shadow around the minimap's box."] = "Un borde y una sombra alrededor de la caja del minimapa."
L["A color for each kind"] = "Un color para cada tipo"
L["A copy of the profile you're using, used by the talent set you're in from now on."] = "Una copia del perfil que usas, asignada desde ahora al conjunto de talentos en el que estás."
L["A layout string from the game's own Cooldown Manager (its Export), a guide or another UI. It becomes a new profile, used by the talent set you're in."] = "Un texto de diseño del gestor de reutilización del juego (su exportación), de una guía o de otra interfaz. Pasa a ser un perfil nuevo, usado por el conjunto de talentos en el que estás."
L["A line of light under each crit."] = "Una línea de luz bajo cada crítico."
L["A mob that needs you slowly brightens and dims, quicker when it's about to switch. For a tank that's a mob you lost, for damage and healers one attacking you. Needs the health bar, border or glow above."] = "Un enemigo que te necesita se aclara y se oscurece despacio, más rápido cuando está a punto de cambiar. Para un tanque es un enemigo que has perdido; para daño y sanadores, uno que te ataca. Hace falta la barra de salud, el borde o el brillo de arriba."
L["A moving glow around the button while its spell is queued or being cast."] = "Un brillo en movimiento alrededor del botón mientras su hechizo está en cola o se está lanzando."
L["A new group starts empty and waits in your bag: drag items onto its name, or click the search beside it here to fill it by itself."] = "Un grupo nuevo empieza vacío y espera en la bolsa: arrastra objetos sobre su nombre, o pulsa la búsqueda a su lado para que se llene solo."
L["A new name for the profile you're using."] = "Un nombre nuevo para el perfil que usas."
L["A profile from the Profiles page, used as it is."] = "Un perfil de la página Perfiles, usado tal cual."
L["A quest under the mouse shows its objectives and clicks beside the tracker. When off, nothing shows and clicks work the same."] = "Una misión bajo el ratón muestra sus objetivos y los clics junto al rastreador. Al desactivarlo, no se muestra nada y los clics funcionan igual."
L["A second bar above it."] = "Una segunda barra encima."
L["A second chat box with its own tabs, for loot, guild or a combat log. Right-click a chat tab to move it over, or drag it onto the other panel. Typing and whispers stay in the main chat."] = "Una segunda caja de chat con sus propias pestañas, para el botín, la hermandad o un registro de combate. Clic derecho en una pestaña para pasarla, o arrástrala al otro panel. Escribir y los susurros se quedan en el chat principal."
L["A shield landing on you."] = "Un escudo que te llega."
L["A slim angled bar at the bottom of the screen: the clock in the middle, your data texts on both sides."] = "Una barra estrecha e inclinada al pie de la pantalla: el reloj en el centro y tus textos de datos a ambos lados."
L["A small badge at the foot of the portrait"] = "Una pequeña insignia al pie del retrato"
L["A small button at the top-right of the chat for the game's chat menu: pick the language you speak, emotes, say, yell and more."] = "Un botón pequeño arriba a la derecha del chat para el menú de chat del juego: elige el idioma, emociones, decir, gritar y más."
L["A small crown tab that opens ready check, role check, a pull timer, and target and world markers. It shows while you lead the group or assist in a raid. When off, these are only in the game's slash commands."] = "Una pequeña pestaña de corona que abre la comprobación de listos, la de función, un temporizador de inicio y los marcadores de objetivo y del mundo. Se muestra mientras lideras el grupo o asistes en una banda. Al desactivarla, eso solo está en los comandos del juego."
L["A small icon and count at the end of a quest's line when others in your party have it too, here and in the quest log on the map."] = "Un icono pequeño y un contador al final de la línea de una misión cuando otros del grupo también la tienen, aquí y en el registro de misiones del mapa."
L["A small icon before each text, in your accent color."] = "Un icono pequeño antes de cada texto, en tu color de acento."
L["A small skull by the bar once your damage over time is enough to finish that enemy."] = "Una calavera pequeña junto a la barra cuando tu daño en el tiempo basta para rematar a ese enemigo."
L["A small slanted mark beside each line, in its color."] = "Una marca inclinada pequeña junto a cada línea, en su color."
L["A soft shadow under each line."] = "Una sombra suave bajo cada línea."
L["A warning that stays up while your health or mana is low."] = "Un aviso que permanece mientras tu salud o tu maná están bajos."
L["A whole look at once. Daylight leans the numbers along the UI's slant and lights up crits. Calm is small and slow. Punchy is big and flung out both ways. Classic curves like the game's own. Changing a row below makes it Custom."] = "Un aspecto completo de una vez. Daylight inclina los números con la inclinación de la interfaz y resalta los críticos. Calma es pequeño y lento. Contundente es grande y sale despedido a ambos lados. Clásico se curva como el del juego. Cambiar una fila de abajo lo deja en Personalizado."
L["About to switch"] = "A punto de cambiar"
L["Absorb shields gained"] = "Escudos de absorción ganados"
L["Active border and glow color"] = "Color del borde y del brillo activos"
L["Addons made by other people on top of DaylightUI: plugins with features of their own, and profile packs with ready-made setups."] = "Addons de otras personas sobre DaylightUI: plugins con funciones propias y paquetes de perfiles con configuraciones listas."
L["After you cast a spell that costs mana, a light crosses your mana bar for the 5 seconds until your Spirit regen is back. Shows on your player frame and personal display."] = "Tras lanzar un hechizo que cuesta maná, una luz cruza tu barra de maná durante los 5 segundos hasta que vuelve la regeneración de Espíritu. Se muestra en tu marco de jugador y en la barra personal."
L["Alerts & Loot Won"] = "Alertas y botín ganado"
L["Always shown"] = "Siempre visible"
L["Always, or only while you hold this key."] = "Siempre, o solo mientras mantienes esta tecla."
L["Amounts shortened (12.3K) or in full (12,345), on both meters, the breakdown and reports."] = "Cantidades abreviadas (12,3 mil) o completas (12.345), en ambos medidores, el desglose y los informes."
L["An empty profile, used by the talent set you're in."] = "Un perfil vacío, usado por el conjunto de talentos en el que estás."
L["An outline keeps the text readable over bright ground and spell effects."] = "Un contorno mantiene el texto legible sobre suelo claro y efectos de hechizos."
L["Angled frame"] = "Marco inclinado"
L["Answers whispers for you, once per person every 15 minutes. Someone you whispered in that time doesn't get it."] = "Responde susurros por ti, una vez por persona cada 15 minutos. Quien te susurró en ese tiempo no lo recibe."
L["Anything else you can use lights up too: doors, levers, mailboxes."] = "También se ilumina lo demás que puedes usar: puertas, palancas, buzones."
L["Apply opacity to every window"] = "Aplicar la opacidad a todas las ventanas"
L["As the main chat"] = "Como el chat principal"
L["Attacking you"] = "Te está atacando"
L["Attacks that didn't land on you."] = "Ataques que no te alcanzaron."
L["Automatic is your Appearance font. The sample above shows it at once; the numbers in the world change after you restart the game."] = "Automática es la fuente de Apariencia. La muestra de arriba cambia al momento; los números del mundo cambian tras reiniciar el juego."
L["Automatic uses your Appearance font."] = "Automática usa la fuente de Apariencia."
L["Bag bar and menu"] = "Barra de bolsas y menú"
L["Bags background opacity"] = "Opacidad del fondo de las bolsas"
L["Bar background opacity"] = "Opacidad del fondo de la barra"
L["Bars and your frame fade after a fight."] = "Las barras y tu marco se desvanecen tras un combate."
L["Basics"] = "Básicos"
L["Battle.net Logins"] = "Conexiones de Battle.net"
L["Beside the meter"] = "Junto al medidor"
L["Boss color"] = "Color de jefe"
L["Boss health bars in the color below, so they stand out in a crowd. Threat colors still show over it."] = "Las barras de salud de los jefes en el color de abajo, para que destaquen entre muchos. Los colores de amenaza se siguen viendo por encima."
L["Bosses in their own color"] = "Jefes en su propio color"
L["Breath bar"] = "Barra de respiración"
L["Brew"] = "Destilación"
L["Brings in the pack's newer version of this profile: its settings and frame positions replace yours. Your Edit Mode layout stays as it is."] = "Trae la versión más nueva de este perfil del paquete: sus ajustes y las posiciones de los marcos sustituyen a los tuyos. Tu diseño del Modo de edición se queda como está."
L["Buffs gained and lost"] = "Beneficios ganados y perdidos"
L["By zone"] = "Según la zona"
L["By zone: green in friendly lands, amber in contested ones, red in hostile ones, blue in sanctuaries. One color: always the color below."] = "Según la zona: verde en tierras amistosas, ámbar en las en disputa, rojo en las hostiles, azul en los santuarios. Un color: siempre el color de abajo."
L["CC Alert"] = "Alerta de control"
L["Calm"] = "Calma"
