L["Cast spells by clicking your unit frames, or by hovering them and pressing your usual keys."] = "Lanza hechizos al hacer clic en tus marcos de unidad, o al pasar el ratón por ellos y pulsar tus teclas de siempre."
L["Caster color"] = "Color de lanzador"
L["Casters in their own color"] = "Lanzadores en su propio color"
L["Casts, interrupts and more"] = "Lanzamientos, interrupciones y más"
L["Changed"] = "Cambios"
L["Character window background opacity"] = "Opacidad del fondo de la ventana de personaje"
L["Chat input text size"] = "Tamaño del texto al escribir"
L["Chat menu button"] = "Botón del menú de chat"
L["Chat tab text size"] = "Tamaño del texto de las pestañas"
L["Chests, crates and barrels light up. A crate or barrel may take one loot before it's recognized."] = "Cofres, cajas y barriles se iluminan. Una caja o un barril puede necesitar un botín antes de reconocerse."
L["Class-colored names and numbers"] = "Nombres y números con color de clase"
L["Clock color"] = "Color del reloj"
L["Color spell hits by school"] = "Color de los impactos de hechizo según la escuela"
L["Combat text outline"] = "Contorno del texto de combate"
L["Combat text preset"] = "Aspecto del texto de combate"
L["Combat text shadow"] = "Sombra del texto de combate"
L["Coordinates color"] = "Color de las coordenadas"
L["Coordinates text size"] = "Tamaño de las coordenadas"
L["Copy profile"] = "Copiar perfil"
L["Crit exclamation mark"] = "Signo de exclamación en críticos"
L["Crit light"] = "Luz de crítico"
L["Crit style"] = "Estilo de crítico"
L["Crit underline"] = "Subrayado de crítico"
L["Crits"] = "Críticos"
L["Custom active border and glow color"] = "Color propio del borde y del brillo activos"
L["Custom guild color"] = "Color de hermandad personalizado"
L["Custom job color"] = "Color de función personalizado"
L["Custom threat % color"] = "Color personalizado del % de amenaza"
L["Cuts both ends of the bar at an angle. Off, they're straight."] = "Corta los dos extremos de la barra en ángulo. Al desactivarlo, quedan rectos."
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not inside the frame or sliding out under it."] = "Corta el extremo de la barra de lanzamiento de tu objetivo en ángulo. Al desactivarlo, el extremo queda recto. No dentro del marco ni al deslizarse por debajo."
L["Cuts the right end of each bar at an angle. When off, the ends are square."] = "Corta el extremo derecho de cada barra en ángulo. Al desactivarlo, los extremos quedan rectos."
L["Cuts the right end of the breath bar at an angle, on the fatigue and feign death bars too. When off, the end is straight."] = "Corta el extremo derecho de la barra de respiración en ángulo, y también las de fatiga y de fingir muerte. Al desactivarlo, el extremo queda recto."
L["Cuts the right end of the flight timer at an angle. When off, the end is straight."] = "Corta el extremo derecho del temporizador de vuelo en ángulo. Al desactivarlo, el extremo queda recto."
L["Data bar"] = "Barra de datos"
L["Data Bar"] = "Barra de datos"
L["Data bar accent line"] = "Línea de acento de la barra de datos"
L["Data bar angled ends"] = "Extremos inclinados de la barra de datos"
L["Data bar background opacity"] = "Opacidad del fondo de la barra de datos"
L["Data bar border opacity"] = "Opacidad del borde de la barra de datos"
L["Data bar height"] = "Altura de la barra de datos"
L["Data bar icons"] = "Iconos de la barra de datos"
L["Data bar labels"] = "Etiquetas de la barra de datos"
L["Data bar text size"] = "Tamaño del texto de la barra de datos"
L["Data bar width"] = "Anchura de la barra de datos"
L["Daybreak"] = "Alba"
L["Debuffs gained and lost"] = "Perjuicios ganados y perdidos"
L["Delete profile"] = "Eliminar perfil"
L["Deletes the profile you're using, for every character of this class. Talent sets that used it have none."] = "Elimina el perfil que usas, para todos los personajes de esta clase. Los conjuntos de talentos que lo usaban se quedan sin perfil."
L["Draining line"] = "Línea que se vacía"
L["Draws the turning map a little closer, so its corners never go empty when you face a diagonal. Off: the full view, with the corners cut."] = "Acerca un poco el mapa al girar, para que las esquinas no queden vacías en diagonal. Al desactivarlo: la vista completa, con las esquinas recortadas."
L["Each item in the loot window flashes in its color as the light running down it passes, and again as you take it. When off, the light still runs and the items still ease in, without the flash."] = "Cada objeto de la ventana de botín destella en su color cuando pasa la luz, y otra vez al recogerlo. Al desactivarlo, la luz sigue y los objetos entran igual, sin el destello."
L["Error Messages"] = "Mensajes de error"
L["Everything stays on screen."] = "Todo permanece en pantalla."
L["Experience bar fade"] = "Desvanecimiento de la barra de experiencia"
L["Experience bar has its own fade"] = "La barra de experiencia tiene su propio desvanecimiento"
L["Fill the corners while turning"] = "Rellenar las esquinas al girar"
L["Fire orange, frost blue, shadow purple. When off, they use the Spell hits color."] = "Fuego naranja, escarcha azul, sombras púrpura. Al desactivarlo, usan el color de impactos de hechizo."
L["Fishing water"] = "Agua de pesca"
L["Fixed"] = "Correcciones"
L["Flare lands big in a burst of soft light. Slam lands bigger and faster. Pop is a small bump. Plain is just bigger text."] = "Bengala llega grande en un estallido de luz suave. Golpe llega más grande y más rápido. Salto es un pequeño impulso. Simple es solo texto más grande."
L["Flip the loot feed left and right"] = "Invertir el flujo de botín a izquierda y derecha"
L["Forge"] = "Forja"
L["Framerate color"] = "Color de los fotogramas"
L["Full (1,234)"] = "Completo (1.234)"
L["Full (12,345)"] = "Completo (12.345)"
L["Full numbers, or short ones for high-level play."] = "Números completos, o abreviados para niveles altos."
L["Game window background opacity"] = "Opacidad del fondo de las ventanas del juego"
L["Gives the box you type in its own text size, set in the row below. When off, it matches the messages' text size."] = "Da a la caja donde escribes su propio tamaño de texto, en la fila de abajo. Al desactivarlo, coincide con el de los mensajes."
L["Gives the second chat panel its own background opacity, set in the row below. When off, it's as see-through as the main chat panel."] = "Da al segundo panel de chat su propia opacidad de fondo, en la fila de abajo. Al desactivarlo, es tan transparente como el panel principal."
L["Gives the window its own background opacity, set in the row below. When off, it's as see-through as the info panel's boxes (General page)."] = "Da a la ventana su propia opacidad de fondo, en la fila de abajo. Al desactivarlo, es tan transparente como las cajas del panel de información (página General)."
L["Glow on an active spell"] = "Brillo en un hechizo activo"
L["Glow on chests"] = "Brillo en cofres"
L["Glow on everything else"] = "Brillo en todo lo demás"
L["Glow on ore and herbs"] = "Brillo en menas y hierbas"
L["Glow on quest objects"] = "Brillo en objetos de misión"
L["Glow on your fishing bobber"] = "Brillo en tu boya"
L["Gone until a fight or a change."] = "Oculto hasta un combate o un cambio."
L["Group finder background opacity"] = "Opacidad del fondo del buscador de grupos"
L["Group name color"] = "Color del nombre del grupo"
L["Group names"] = "Nombres del grupo"
L["Guild names in the player's class color, plain white, or one color."] = "Nombres de hermandad en el color de clase del jugador, en blanco o en un color."
L["Guild size"] = "Tamaño de hermandad"
L["Heals"] = "Sanaciones"
L["Heals over time"] = "Sanaciones en el tiempo"
L["Heals you receive."] = "Sanaciones que recibes."
L["Health text position"] = "Posición del texto de salud"
L["Hides messages with these in public channels, never guild, group or whispers. Whole words; capitals don't matter. Chat style: Daylight only."] = "Oculta los mensajes que las contengan en canales públicos, nunca en hermandad, grupo o susurros. Palabras completas; las mayúsculas no importan. Estilo de chat: solo Daylight."
L["Hits you take from spells."] = "Golpes de hechizo que recibes."
L["Hits you take from weapons."] = "Golpes de arma que recibes."
L["Hover a text for details, click it to open its window. Move it in unlock mode (/dui unlock). When it reaches the screen's corners, chat and the damage meters' windows start above it unless you've moved them."] = "Pasa el ratón sobre un texto para ver el detalle y haz clic para abrir su ventana. Muévelo en modo de desbloqueo (/dui unlock). Al llegar a las esquinas de la pantalla, el chat y las ventanas de los medidores de daño empiezan por encima, salvo que los hayas movido."
L["Hovering an icon says what it is. While the mouse is on an icon, mouseover casting misses that player. Clicks always go through to the frame."] = "Al pasar el ratón por un icono dice qué es. Mientras el ratón está sobre un icono, lanzar al pasar el ratón no alcanza a ese jugador. Los clics siempre llegan al marco."
L["How a big hit or heal, or a spell lighting up, lands."] = "Cómo llega un golpe o una sanación grandes, o un hechizo que se ilumina."
L["How big the coordinates are."] = "El tamaño de las coordenadas."
L["How big the number of stacks is on each buff icon."] = "El tamaño del número de acumulaciones en cada icono de beneficio."
L["How big the number of stacks is on each debuff icon."] = "El tamaño del número de acumulaciones en cada icono de perjuicio."
L["How big the texts are. The one in the middle is a little bigger."] = "El tamaño de los textos. El del centro es un poco más grande."
L["How big the time left is on each buff icon."] = "El tamaño del tiempo restante en cada icono de beneficio."
L["How big the time left is on each debuff icon."] = "El tamaño del tiempo restante en cada icono de perjuicio."
L["How big the zone name is."] = "El tamaño del nombre de la zona."
L["How bright the light behind a crit is. At 0 there is none."] = "La intensidad de la luz detrás de un crítico. En 0 no hay."
L["How far a line travels. Stack ignores this."] = "Cuánto recorre una línea. Apilar lo ignora."
L["How far the angled end leans, docked bars included. Set to 0 to use the Slant angle on Extras."] = "Cuánto se inclina el extremo, barras acopladas incluidas. En 0 usa el ángulo de Inclinación en Extras."
L["How far under the object's name the light sits once you can reach it. The game doesn't say how tall an object is, so this is a best fit for most of them."] = "A qué distancia bajo el nombre del objeto queda la luz cuando puedes alcanzarlo. El juego no dice la altura del objeto, así que esto encaja con la mayoría."
L["How long each buff and debuff has left, on its icon."] = "Cuánto le queda a cada beneficio y perjuicio, en su icono."
L["How low your health or mana gets before the warning shows."] = "Hasta dónde bajan tu salud o tu maná antes de que salga el aviso."
L["How much of the screen's width the bar takes, in percent."] = "Qué parte del ancho de la pantalla ocupa la barra, en porcentaje."
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, chat, the info panel, the quest box and the buff bars. One with a separate opacity on its own page keeps that."] = "La transparencia de cada ventana y panel: bolsas, personaje, libro de hechizos, PNJ, buscador de grupos, las ventanas del juego que rediseñamos, el chat, el panel de información, el marco de misiones y las barras de beneficios. La que tenga una opacidad propia en su página la conserva."
L["How see-through it is while shown, whatever the fade does. At 0 it never shows, even under the mouse or in a fight."] = "La transparencia mientras se muestra, haga lo que haga el desvanecimiento. En 0 no se muestra nunca, ni bajo el ratón ni en combate."
L["How see-through the box around the minimap (and the damage meter in it) is: 0 is fully see-through."] = "La transparencia de la caja del minimapa (y del medidor de daño que hay dentro): 0 es del todo transparente."
L["How see-through the experience bar's box and the meters' own windows are."] = "La transparencia de la caja de la barra de experiencia y de las ventanas propias de los medidores."
L["How see-through the experience bar's box and the meters' own windows are (a meter window can have its own, on its page)."] = "La transparencia de la caja de la barra de experiencia y de las ventanas propias de los medidores (una ventana de medidor puede tener la suya, en su página)."
L["How solid the border around the bar is: 0 is no border."] = "Lo sólido que es el borde de la barra: 0 es sin borde."
L["How solid the second chat panel's background is: 0 is fully see-through."] = "Lo sólido que es el fondo del segundo panel de chat: 0 es del todo transparente."
L["How solid the window's background is: 0 is fully see-through, leaving only the bars."] = "Lo sólido que es el fondo de la ventana: 0 es del todo transparente y solo quedan las barras."
L["How tall a crit is once it settles."] = "La altura de un crítico cuando se asienta."
L["How tall a line of text is."] = "La altura de una línea de texto."
L["How tall the data bar is."] = "La altura de la barra de datos."
L["How thick the Flat border is. The Daylight frame follows the border size on General > Appearance."] = "El grosor del borde Plano. El marco Daylight sigue el tamaño de borde de General > Apariencia."
L["Import a layout"] = "Importar un diseño"
L["In a group, colors a mob by who it's attacking; solo plates never change. Red while it's attacking you, yellow while it's attacking someone else, orange when it's about to switch."] = "En un grupo, colorea a un enemigo según a quién ataca; en solitario las placas no cambian. Rojo mientras te ataca, amarillo mientras ataca a otro, naranja cuando está a punto de cambiar."
L["Inspect window background opacity"] = "Opacidad del fondo de la ventana de inspección"
L["Its own section in the list on the left, under Plugins."] = "Su propia sección en la lista de la izquierda, bajo Complementos."
L["Its ready-made profiles are on the Profiles page and in the setup guide."] = "Sus perfiles listos están en la página Perfiles y en la guía de instalación."
L["Its tooltips in the Daylight UI frame, in your background opacity. Its layout, words and stat colors stay."] = "Sus descripciones emergentes en el marco de Daylight UI, con tu opacidad de fondo. Su diseño, textos y colores de estadísticas se quedan."
L["Job"] = "Función"
L["Job color"] = "Color de la función"
L["Job size"] = "Tamaño de la función"
L["Just your main bar."] = "Solo tu barra principal."
L["Keep tracking on"] = "Mantener el rastreo"
L["Large"] = "Grande"
L["Left stream"] = "Flujo izquierdo"
L["Left stream alignment"] = "Alineación del flujo izquierdo"
L["Left stream crit size"] = "Tamaño de crítico del flujo izquierdo"
L["Left stream most lines at once"] = "Máximo de líneas a la vez del flujo izquierdo"
L["Left stream motion"] = "Movimiento del flujo izquierdo"
L["Left stream text size"] = "Tamaño de texto del flujo izquierdo"
L["Left stream time on screen"] = "Tiempo en pantalla del flujo izquierdo"
L["Left stream travel distance"] = "Distancia del flujo izquierdo"
L["Legacy window background opacity"] = "Opacidad del fondo de la ventana clásica"
L["Light the border on an active spell"] = "Iluminar el borde de un hechizo activo"
L["Loot Rolls"] = "Tiradas de botín"
L["Loot Window"] = "Ventana de botín"
L["Loot window"] = "Ventana de botín"
L["Loot window flash"] = "Destello de la ventana de botín"
L["Lost"] = "Perdida"
L["Low health warning at"] = "Aviso de salud baja en"
L["Mailbox background opacity"] = "Opacidad del fondo del buzón"
L["Mana regen sweep"] = "Barrido de regeneración de maná"
L["Medium"] = "Mediano"
L["Melee and ranged hits"] = "Golpes cuerpo a cuerpo y a distancia"
L["Meter numbers"] = "Números del medidor"
L["Meter window background opacity"] = "Opacidad del fondo de la ventana del medidor"
L["Minimap box background opacity"] = "Opacidad del fondo de la caja del minimapa"
L["Minimap tracking"] = "Rastreo del minimapa"
L["Mining veins and herbs light up."] = "Las vetas y las hierbas se iluminan."
L["Mirrors the feed: lines line up on the left, slide in from the left and leave to the right, with the icon at the right end. Handy when the feed sits on the left of the screen. When off, lines line up on the right."] = "Invierte el flujo: las líneas se alinean a la izquierda, entran por la izquierda y salen por la derecha, con el icono al extremo derecho. Útil cuando el flujo está a la izquierda de la pantalla. Al desactivarlo, las líneas se alinean a la derecha."
L["Missing health shows nothing while you're at full."] = "La salud que falta no muestra nada mientras estás al máximo."
L["Mobs that use mana in the color below: the ones to interrupt or pull out of line of sight. A boss or rare keeps its own color. Threat colors still show over it."] = "Los enemigos que usan maná, en el color de abajo: los que hay que interrumpir o sacar de la línea de visión. Un jefe o un raro conserva su color. Los colores de amenaza se siguen viendo por encima."
L["Mouseover casting"] = "Lanzar al pasar el ratón"
L["Mouseover key"] = "Tecla al pasar el ratón"
L["Move the text"] = "Mover el texto"
L["Move the text streams"] = "Mover los flujos de texto"
L["Moves your cast bar under the personal display, as wide as it."] = "Pasa tu barra de lanzamiento bajo la barra personal, con su misma anchura."
L["Moves your swing timers under the personal display, as wide as it."] = "Pasa el tiempo de golpes bajo la barra personal, con su misma anchura."
L["NPC jobs in soft tan, plain white, or one color."] = "Las funciones de los PNJ en tostado suave, en blanco o en un color."
L["NPC window background opacity"] = "Opacidad del fondo de la ventana de PNJ"
L["Names of the players in your party or raid in their own color."] = "Los nombres de los jugadores de tu grupo o banda en su propio color."
L["New options"] = "Opciones nuevas"
L["Not attacking you"] = "No te ataca"
L["Nudges it left or right from under the health bar, in pixels. In Design mode on the preview, drag it there."] = "Lo desplaza a izquierda o derecha desde debajo de la barra de salud, en píxeles. En modo Diseño, en la vista previa, arrástralo hasta allí."
L["Nudges it up or down from under the health bar, in pixels. In Design mode on the preview, drag it there."] = "Lo desplaza arriba o abajo desde debajo de la barra de salud, en píxeles. En modo Diseño, en la vista previa, arrástralo hasta allí."
L["Number format"] = "Formato de los números"
L["Numbers"] = "Números"
L["Object glow"] = "Brillo de objetos"
L["Object glow color"] = "Color del brillo de objetos"
L["Object glow height"] = "Altura del brillo de objetos"
L["Object glow in dungeons and raids"] = "Brillo de objetos en mazmorras y bandas"
L["Object glow in fights"] = "Brillo de objetos en combate"
L["Object glow look"] = "Aspecto del brillo de objetos"
L["Objects glow in dungeons, raids and battlegrounds too."] = "Los objetos también brillan en mazmorras, bandas y campos de batalla."
L["Objects in the world"] = "Objetos del mundo"
L["Objects keep glowing while you're in a fight."] = "Los objetos siguen brillando mientras estás en combate."
L["Objects your quests need light up."] = "Se iluminan los objetos que piden tus misiones."
L["Off, the experience bar fades with the panel. On, it follows the settings here, attached or separate."] = "Al desactivarlo, la barra de experiencia se desvanece con el panel. Al activarlo, sigue los ajustes de aquí, unida o separada."
L["On you"] = "Sobre ti"
L["One color for each threat state, or a gradient for each. The gradients are also on General > Gradients."] = "Un color para cada estado de amenaza, o un degradado para cada uno. Los degradados también están en General > Degradados."
L["One row"] = "Una fila"
L["Ore, herbs, chests, quest objects and your fishing bobber light up as you come near, dim from afar and bright once you can reach them. Ore and herbs only glow for a character who can gather them. This changes a few of the game's interact settings while it's on, and gives them back when it's off."] = "Menas, hierbas, cofres, objetos de misión y tu boya se iluminan al acercarte, tenues de lejos y brillantes cuando puedes alcanzarlos. Menas y hierbas solo brillan para un personaje que pueda recogerlas. Mientras está activo cambia algunos ajustes de interacción del juego, y los devuelve al apagarlo."
L["Paging: this bar can show another page of buttons while you're in a stance or form, or while you hold a key. Pick a spare page to fill it with spells of its own."] = "Paginación: esta barra puede mostrar otra página de botones mientras estás en una postura o forma, o mientras mantienes una tecla. Elige una página libre para llenarla con hechizos propios."
L["Party members on a quest"] = "Miembros del grupo en una misión"
L["Past this the oldest line leaves early, so a big pull never floods the screen."] = "A partir de aquí la línea más antigua sale antes, para que un grupo grande de enemigos no llene la pantalla."
L["Paste a string"] = "Pegar un texto"
L["Personal absorbs"] = "Absorciones personales"
L["Personal display angle"] = "Ángulo de la barra personal"
L["Personal health bar"] = "Barra de salud personal"
L["Personal incoming heals"] = "Sanaciones entrantes personales"
L["Plays it in the middle of the screen. Also /dui glow."] = "Lo reproduce en el centro de la pantalla. También /dui glow."
L["Plays it now; move to end it. Also /dui brew."] = "Lo reproduce ahora; muévete para terminarlo. También /dui brew."
L["Plays it now; move to end it. Also /dui fishing."] = "Lo reproduce ahora; muévete para terminarlo. También /dui fishing."
L["Plays it now; move to end it. Also /dui forge."] = "Lo reproduce ahora; muévete para terminarlo. También /dui forge."
L["Plays it now; move to end it. Also /dui sewing."] = "Lo reproduce ahora; muévete para terminarlo. También /dui sewing."
L["Plays it now; move to end it. Also /dui workshop."] = "Lo reproduce ahora; muévete para terminarlo. También /dui workshop."
L["Plus and minus signs"] = "Signos más y menos"
L["Preview the brew"] = "Vista previa de la destilación"
L["Preview the fishing water"] = "Vista previa del agua de pesca"
L["Preview the forge"] = "Vista previa de la forja"
L["Preview the object glow"] = "Vista previa del brillo de objetos"
L["Preview the sewing"] = "Vista previa de la sastrería"
L["Preview the workshop"] = "Vista previa del taller"
L["Profession window background opacity"] = "Opacidad del fondo de la ventana de profesión"
L["Puts this font on the game's own text as well: menus, tooltips, quest text, popups, nameplate names. Sizes and outlines stay the game's."] = "Pone esta fuente también en el texto propio del juego: menús, descripciones emergentes, texto de misiones, avisos y nombres de las placas. Los tamaños y contornos siguen siendo los del juego."
L["QuestieDB isn't on, so the arrow is left out: it needs QuestieDB to know where each mob is."] = "QuestieDB no está activo, así que la flecha no se incluye: hace falta QuestieDB para saber dónde está cada enemigo."
L["Rare and rare elite health bars in the color below. Threat colors still show over it."] = "Las barras de salud de raros y raros de élite en el color de abajo. Los colores de amenaza se siguen viendo por encima."
L["Rare color"] = "Color de raro"
L["Rares in their own color"] = "Raros en su propio color"
L["Recipe names take the rarity color of what they make. Off, they show how likely a skill-up is. The same switch sits beside the window's search."] = "Los nombres de receta toman el color de rareza de lo que fabrican. Al desactivarlo, muestran lo probable que es subir la habilidad. El mismo interruptor está junto a la búsqueda de la ventana."
L["Rename profile"] = "Renombrar perfil"
L["Replaces the game's damage meter window. The tab on the panel's edge, on the meter's side, also shows or hides it."] = "Sustituye la ventana del medidor de daño del juego. La pestaña del borde del panel, en el lado del medidor, también lo muestra o lo oculta."
L["Rest the mouse on a frame and press a spell on your action bars: it goes to that player, with no click and no change of target. Works on anyone the mouse is on, in the world too, and with mouse buttons bound to your bars. This is the game's own setting."] = "Deja el ratón sobre un marco y pulsa un hechizo de tus barras de acción: va a ese jugador, sin clic y sin cambiar de objetivo. Funciona con cualquiera que tenga el ratón encima, también en el mundo, y con botones del ratón asignados a las barras. Es el ajuste propio del juego."
L["Right stream"] = "Flujo derecho"
L["Right stream alignment"] = "Alineación del flujo derecho"
L["Right stream crit size"] = "Tamaño de crítico del flujo derecho"
L["Right stream most lines at once"] = "Máximo de líneas a la vez del flujo derecho"
L["Right stream motion"] = "Movimiento del flujo derecho"
L["Right stream text size"] = "Tamaño de texto del flujo derecho"
L["Right stream time on screen"] = "Tiempo en pantalla del flujo derecho"
L["Right stream travel distance"] = "Distancia del flujo derecho"
L["Rows added after this version carry a NEW tag as you go through the pages. Search for new to list them all."] = "Las filas añadidas después de esta versión llevan la etiqueta NUEVO al recorrer las páginas. Busca new para verlas todas."
L["Second chat panel"] = "Segundo panel de chat"
L["Second meter window background opacity"] = "Opacidad del fondo de la segunda ventana del medidor"
L["Second panel"] = "Segundo panel"
L["Second panel background opacity"] = "Opacidad del fondo del segundo panel"
L["Second panel height"] = "Altura del segundo panel"
L["Second panel hides"] = "El segundo panel se oculta"
L["Second panel width"] = "Anchura del segundo panel"
L["Seconds a line stays before it fades."] = "Segundos que una línea permanece antes de desvanecerse."
L["Separate NPC window background opacity"] = "Opacidad de fondo independiente para la ventana de PNJ"
L["Separate bags background opacity"] = "Opacidad de fondo independiente para las bolsas"
L["Separate character window background opacity"] = "Opacidad de fondo independiente para la ventana de personaje"
L["Separate chat input text size"] = "Tamaño de texto independiente al escribir"
L["Separate data bar background opacity"] = "Opacidad de fondo independiente para la barra de datos"
L["Separate game window background opacity"] = "Opacidad de fondo independiente para las ventanas del juego"
L["Separate group finder background opacity"] = "Opacidad de fondo independiente para el buscador de grupos"
L["Separate inspect window background opacity"] = "Opacidad de fondo independiente para la ventana de inspección"
L["Separate legacy window background opacity"] = "Opacidad de fondo independiente para la ventana clásica"
L["Separate mailbox background opacity"] = "Opacidad de fondo independiente para el buzón"
L["Separate meter window background opacity"] = "Opacidad de fondo independiente para la ventana del medidor"
L["Separate profession window background opacity"] = "Opacidad de fondo independiente para la ventana de profesión"
L["Separate second meter window background opacity"] = "Opacidad de fondo independiente para la segunda ventana del medidor"
L["Separate second panel background opacity"] = "Opacidad de fondo independiente para el segundo panel"
L["Separate social window background opacity"] = "Opacidad de fondo independiente para la ventana social"
L["Separate spellbook background opacity"] = "Opacidad de fondo independiente para el libro de hechizos"
L["Set to 0 to follow the name size."] = "En 0 sigue el tamaño del nombre."
L["Set to 0 to match the bar height."] = "En 0 coincide con la altura de la barra."
L["Sewing"] = "Sastrería"
L["Short (12.3K)"] = "Corto (12,3 mil)"
L["Short labels like Gear, Bags and Guild before each number. They drop off when the bar is too narrow."] = "Etiquetas cortas como Equipo, Bolsas y Hermandad antes de cada número. Desaparecen si la barra es demasiado estrecha."
L["Show NEW on options added since"] = "Mostrar NUEVO en opciones añadidas desde"
L["Show combat text"] = "Mostrar texto de combate"
L["Show keybind"] = "Mostrar atajo"
L["Show keybinds on icons"] = "Mostrar atajos en los iconos"
L["Show leader tools"] = "Mostrar herramientas del líder"
L["Show quest tooltips"] = "Mostrar descripciones de misión"
L["Show the data bar"] = "Mostrar la barra de datos"
L["Show the left stream"] = "Mostrar el flujo izquierdo"
L["Show the right stream"] = "Mostrar el flujo derecho"
L["Show the top stream"] = "Mostrar el flujo superior"
L["Shows a handle on every spot. Drag to move it."] = "Muestra un asa en cada sitio. Arrastra para moverlo."
L["Side bars that fade until you need them."] = "Barras laterales que se desvanecen hasta que las necesitas."
L["Slant leans along the UI's angle. Rise and Fall go straight. Arc curves away from you. Fountain sprays both ways. Stack stays put, and new lines push the older ones up."] = "Inclinado sigue el ángulo de la interfaz. Subida y Bajada van rectas. Arco se curva alejándose. Fuente sale hacia ambos lados. Apilar se queda quieto y las líneas nuevas empujan hacia arriba a las anteriores."
L["Slanted mark"] = "Marca inclinada"
L["Small"] = "Pequeño"
L["Social window background opacity"] = "Opacidad del fondo de la ventana social"
L["Soft trail"] = "Estela suave"
L["Spark"] = "Chispa"
L["Special mobs"] = "Enemigos especiales"
L["Spell hits"] = "Impactos de hechizo"
L["Spell icon side"] = "Lado del icono de hechizo"
L["Spellbook background opacity"] = "Opacidad del fondo del libro de hechizos"
L["Streams"] = "Flujos"
L["Sunrise"] = "Amanecer"
L["Sweep"] = "Barrido"
L["Sweep: a ring with a light running round it. Angled frame: the Daylight UI shape on the ground with a light running round it. Daybreak: a beam of light leaning down onto the object. Sunrise: a low sun rising behind it."] = "Barrido: un anillo con una luz que lo recorre. Marco inclinado: la forma de Daylight UI en el suelo con una luz que lo recorre. Alba: un haz de luz inclinado sobre el objeto. Amanecer: un sol bajo que sale detrás."
L["Swing timers on the personal display"] = "Tiempo de golpes en la barra personal"
L["Switching"] = "Cambiando"
L["Talent set 1"] = "Conjunto de talentos 1"
L["Tan"] = "Tostado"
L["The NPC job's color when Job color is One color."] = "El color de la función del PNJ cuando Color de la función es Un color."
L["The bar along the bottom of the screen."] = "La barra a lo largo de la parte inferior de la pantalla."
L["The bar's color when it's set to One color."] = "El color de la barra cuando está en Un color."
L["The bar's own color, so it can look unlike your player frame. Same as the Colors page follows the color every frame shares."] = "El color propio de la barra, para que pueda verse distinto de tu marco de jugador. Igual que la página Colores sigue el color que comparten todos los marcos."
L["The border's color. The border still lights up in your accent color while you drag a corner to size the chat."] = "El color del borde. El borde sigue iluminándose en tu color de acento mientras arrastras una esquina para cambiar el tamaño del chat."
L["The box around the minimap, with the damage meter and data texts in it. The experience bar and the meters' own windows keep the General page's background."] = "La caja alrededor del minimapa, con el medidor de daño y los textos de datos dentro. La barra de experiencia y las ventanas propias de los medidores conservan el fondo de la página General."
L["The button's border lights up while its spell is queued, like Heroic Strike waiting for your next swing, or being cast."] = "El borde del botón se ilumina mientras su hechizo está en cola, como Golpe heroico esperando tu siguiente golpe, o mientras se lanza."
L["The color of the clock."] = "El color del reloj."
L["The color of the coordinates."] = "El color de las coordenadas."
L["The color of the framerate."] = "El color de los fotogramas."
L["The color of the lit border and the glow on an active spell."] = "El color del borde iluminado y del brillo de un hechizo activo."
L["The color of your party and raid members' names."] = "El color de los nombres de los miembros de tu grupo y de tu banda."
L["The edge round every chat panel: the main one, the second one and a chat window pulled out on its own. As the chat style gives the Daylight chat box the Daylight frame and the Classic style a thin line. Daylight is the warm band inside a dark outline, Flat a plain line."] = "El borde de cada panel de chat: el principal, el segundo y una ventana de chat sacada aparte. Según el estilo, el chat Daylight lleva el marco Daylight y el estilo Clásico una línea fina. Daylight es la banda cálida dentro de un contorno oscuro; Plano, una línea simple."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the crowd control alert. Also the game's own character and inspect windows while Daylight UI's are off."] = "El menú del juego, la lista de addons, macros, reloj, botín, engarces, mejoras, el desguazador, la casa de subastas, el libro de profesiones, el marco del mapa del mundo, la barra de respiración y la alerta de control. También las ventanas propias de personaje e inspección del juego mientras las de Daylight UI están apagadas."
L["The game's numbers that pop off what you hit."] = "Los números del juego que salen de lo que golpeas."
L["The game's other short messages: an interrupt, a dispel, an extra attack."] = "Los otros mensajes cortos del juego: una interrupción, una disipación, un ataque extra."
L["The guild name's color when Guild color is One color."] = "El color del nombre de hermandad cuando Color de hermandad es Un color."
L["The healer's name beside each heal. In a fight the game can hide who it was, so your own heals may show your name too."] = "El nombre del sanador junto a cada sanación. En combate el juego puede ocultar quién fue, así que tus propias sanaciones pueden mostrar también tu nombre."
L["The health bar's color on a boss."] = "El color de la barra de salud de un jefe."
L["The health bar's color on a mob that uses mana."] = "El color de la barra de salud de un enemigo que usa maná."
L["The health bar's color on a rare."] = "El color de la barra de salud de un raro."
L["The health text shows at full health too. When off, it disappears while you're at full."] = "El texto de salud también se muestra con la salud al máximo. Al desactivarlo, desaparece mientras estás al máximo."
L["The key that casts each spell, on its icon. It reads your action bars, so a spell on no bar shows none. Any icon can change this in the layout editor."] = "La tecla que lanza cada hechizo, en su icono. Lee tus barras de acción, así que un hechizo que no esté en ninguna no muestra nada. Cualquier icono puede cambiar esto en el editor de diseño."
L["The key that casts this spell, read from your action bars."] = "La tecla que lanza este hechizo, leída de tus barras de acción."
L["The line along the top of the bar, in your accent color."] = "La línea a lo largo de la parte superior de la barra, en tu color de acento."
L["The mob is attacking you."] = "El enemigo te está atacando."
L["The mob is in the fight, but attacking someone else."] = "El enemigo está en el combate, pero ataca a otro."
L["The name of a buff as it lands on you or leaves."] = "El nombre de un beneficio cuando te llega o se va."
L["The name of a debuff as it lands on you or leaves."] = "El nombre de un perjuicio cuando te llega o se va."
L["The number's color when Threat % color is One color."] = "El color del número cuando Color del % de amenaza es Un color."
L["The size of the words on the chat tabs."] = "El tamaño de las palabras de las pestañas del chat."
L["The size of what you type in the chat box."] = "El tamaño de lo que escribes en la caja del chat."
L["The small tab on the meter's outer edge (it shows while the mouse is near) slides it out or back by hand."] = "La pestaña pequeña del borde exterior del medidor (se muestra con el ratón cerca) lo saca o lo guarda a mano."
L["The spell being cast, as a small icon by the cast bar."] = "El hechizo que se lanza, como un icono pequeño junto a la barra de lanzamiento."
L["The spell's icon at the end of your target's cast bar. Not inside the frame or sliding out under it."] = "El icono del hechizo al extremo de la barra de lanzamiento de tu objetivo. No dentro del marco ni al deslizarse por debajo."
L["The text scrolling around your character. When off, none shows, the game's own included."] = "El texto que se desplaza alrededor de tu personaje. Al desactivarlo no se muestra nada, ni el del juego."
L["The text scrolling around your character: hits you take, heals, procs and more."] = "El texto que se desplaza alrededor de tu personaje: golpes que recibes, sanaciones, procs y más."
L["The threat number on the nameplates. General uses the health text font."] = "El número de amenaza de las placas de nombre. General usa la fuente del texto de salud."
L["The ticks of a heal over time on you."] = "Los ticks de una sanación en el tiempo sobre ti."
L["The zone name's color when Zone name color is One color."] = "El color del nombre de la zona cuando Color del nombre de zona es Un color."
L["Their color when Active border and glow color is set to Your own color."] = "Su color cuando Color del borde y del brillo activos está en Tu propio color."
L["Threat %"] = "% de amenaza"
L["Threat % color"] = "Color del % de amenaza"
L["Threat % font"] = "Fuente del % de amenaza"
L["Threat % left / right"] = "% de amenaza izquierda / derecha"
L["Threat % position"] = "Posición del % de amenaza"
L["Threat % size"] = "Tamaño del % de amenaza"
L["Threat % up / down"] = "% de amenaza arriba / abajo"
L["Threat color"] = "Color de amenaza"
L["Threat color style"] = "Estilo del color de amenaza"
L["Threat color: white, turning orange or red only when the enemy needs you, as with the breathing pulse. Or always white, your accent color, or one color you pick."] = "Color de amenaza: blanco, y naranja o rojo solo cuando el enemigo te necesita, como el pulso. O siempre blanco, tu color de acento, o un color que elijas."
L["Threat: attacking you"] = "Amenaza: te ataca"
L["Threat: not attacking you"] = "Amenaza: no te ataca"
L["Ticket Status"] = "Estado del ticket"
L["Time left position"] = "Posición del tiempo restante"
L["Tooltip on hover"] = "Descripción al pasar el ratón"
L["Top Center Status"] = "Estado superior central"
L["Top stream"] = "Flujo superior"
L["Top stream alignment"] = "Alineación del flujo superior"
L["Top stream crit size"] = "Tamaño de crítico del flujo superior"
L["Top stream most lines at once"] = "Máximo de líneas a la vez del flujo superior"
L["Top stream motion"] = "Movimiento del flujo superior"
L["Top stream text size"] = "Tamaño de texto del flujo superior"
L["Top stream time on screen"] = "Tiempo en pantalla del flujo superior"
L["Top stream travel distance"] = "Distancia del flujo superior"
L["Tracking from a spell, like Find Minerals, comes back after you log out, change zones or die. Turn it off yourself and it stays off."] = "El rastreo de un hechizo, como Buscar minerales, vuelve tras cerrar sesión, cambiar de zona o morir. Si lo apagas tú, se queda apagado."
L["Turns off every separate background opacity, so every window and panel matches Window background opacity."] = "Apaga cada opacidad de fondo independiente, para que todas las ventanas y paneles coincidan con Opacidad del fondo de las ventanas."
L["Two rows"] = "Dos filas"
L["Two rows and side bars"] = "Dos filas y barras laterales"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (beside or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Bajo el medidor sale del borde inferior del medidor de daño, dentro del panel, con su misma anchura, y las filas del medidor le hacen sitio. Acoplado (al lado o debajo), solo se muestra mientras el medidor de daño está abierto. Su propia ventana va a cualquier sitio: muévela en modo de desbloqueo (/dui unlock) y arrastra su esquina para cambiar el tamaño."
L["Used when Nameplates > Threat > Threat color style is Two-color gradient."] = "Se usa cuando Placas de nombre > Amenaza > Estilo del color de amenaza es Degradado bicolor."
L["What the bar shows. Pick None to leave a slot empty, and the others close up."] = "Lo que muestra la barra. Elige Ninguno para dejar un hueco vacío, y los demás se juntan."
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave. This zone only keeps the quests for where you are; All over the list shows the rest until you leave."] = "Qué hace el rastreador al entrar en una mazmorra, banda o campo de batalla. Vuelve al salir. Solo esta zona conserva las misiones de donde estás; Por toda la lista muestra el resto hasta que sales."
L["When off, nothing shows here, even for the messages that go to it."] = "Al desactivarlo, aquí no se muestra nada, ni siquiera los mensajes que irían ahí."
L["When the second panel gets out of the way, on its own: keep a loot or combat log panel up while the main chat floats away, or the other way round. Idle time and how long messages stay are the main chat's."] = "Cuándo el segundo panel se aparta, por su cuenta: deja visible un panel de botín o de registro de combate mientras el chat principal se va, o al revés. El tiempo de inactividad y cuánto permanecen los mensajes son los del chat principal."
L["When you're away"] = "Cuando estás ausente"
L["Where along the health bar the health text sits."] = "En qué punto de la barra de salud se sitúa el texto de salud."
L["Where the time sits: on the icon's top edge, across its middle, or on its bottom edge."] = "Dónde se sitúa el tiempo: en el borde superior del icono, por el centro o en el borde inferior."
L["Which end of the cast bar it sits at. In Design mode on the preview, drag it there."] = "En qué extremo de la barra de lanzamiento se sitúa. En modo Diseño, en la vista previa, arrástralo hasta allí."
L["Which profile this talent set uses. Your class's profiles show here, from every character of this class."] = "Qué perfil usa este conjunto de talentos. Aquí salen los perfiles de tu clase, de todos los personajes de esta clase."
L["Which side of the minimap the damage meter slides out of, with the threat meter beside it. Automatic picks the side toward the middle of the screen, so it follows when you move the panel."] = "Por qué lado del minimapa sale el medidor de daño, con el medidor de amenaza al lado. Automático elige el lado hacia el centro de la pantalla, así que sigue al panel cuando lo mueves."
L["Which side of the spot the lines line up on."] = "En qué lado del sitio se alinean las líneas."
L["While you do engineering, two brass gears turn at the bottom of the screen with sparks where they meet, a brass tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "Mientras haces ingeniería, dos engranajes de latón giran al pie de la pantalla con chispas donde se tocan, una marea de latón muestra lo avanzado del lote, y tus barras de acción y marcos de unidad se desvanecen. Muévete, selecciona un objetivo o lanza otra cosa y todo vuelve; un combate lo devuelve al momento."
L["While you make potions, a flask sits at the bottom of the screen with bubbles rising past it, a green tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "Mientras haces pociones, un frasco se queda al pie de la pantalla con burbujas que suben, una marea verde muestra lo avanzado del lote, y tus barras de acción y marcos de unidad se desvanecen. Muévete, selecciona un objetivo o lanza otra cosa y todo vuelve; un combate lo devuelve al momento."
L["While you smith, an anvil and hammer work along the bottom of the screen with sparks on each finished item, a molten tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "Mientras forjas, un yunque y un martillo trabajan al pie de la pantalla con chispas en cada objeto terminado, una marea fundida muestra lo avanzado del lote, y tus barras de acción y marcos de unidad se desvanecen. Muévete, selecciona un objetivo o lanza otra cosa y todo vuelve; un combate lo devuelve al momento."
L["While you tailor, a spool sits at the bottom of the screen, a tide of cloth with a growing seam shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "Mientras coses, una bobina se queda al pie de la pantalla, una marea de tela con una costura que crece muestra lo avanzado del lote, y tus barras de acción y marcos de unidad se desvanecen. Muévete, selecciona un objetivo o lanza otra cosa y todo vuelve; un combate lo devuelve al momento."
L["While your line is in, calm water lies along the bottom of the screen with a little bobber on it, and your action bars and unit frames fade away. When a fish comes in the water splashes. Move, target or cast something else and everything comes back; a fight brings it back at once. The game doesn't tell addons when a fish bites, so the splash comes on the catch, not the bite."] = "Mientras el sedal está echado, un agua en calma recorre el pie de la pantalla con una boya pequeña, y tus barras de acción y marcos de unidad se desvanecen. Cuando entra un pez, el agua salpica. Muévete, selecciona un objetivo o lanza otra cosa y todo vuelve; un combate lo devuelve al momento. El juego no avisa a los addons de la picada, así que el salpicón llega al pescar, no al morder."
L["Who else gets the crown tab in a party, for the markers: the party's tank, or everyone. Ready check and the pull timer stay with the leader. In a raid only the leader and assists can mark."] = "Quién más tiene la pestaña de corona en un grupo, para los marcadores: el tanque del grupo, o todos. La comprobación de listos y el temporizador de inicio se quedan con el líder. En una banda solo el líder y los asistentes pueden marcar."
L["Who's closest to pulling your target, in a small window that slides out beside the damage meter, along its bottom, or anywhere on its own."] = "Quién está más cerca de atraer a tu objetivo, en una ventana pequeña que sale junto al medidor de daño, a lo largo de su base, o en cualquier sitio por su cuenta."
L["Within each zone. Most recent progress moves a quest and its zone to the top when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "Dentro de cada zona. El progreso más reciente sube una misión y su zona cuando cuenta una muerte, un objeto o un objetivo. El más cercano vuelve a mirar cada pocos segundos mientras te mueves, nunca en combate ni en una mazmorra. En combate no se mueve nada."
L["Words and phrases to hide"] = "Palabras y frases a ocultar"
L["Workshop"] = "Taller"
L["You can also drag the panel's bottom-right corner to size it."] = "También puedes arrastrar la esquina inferior derecha del panel para cambiar su tamaño."
L["Your accent color, or a color that says what the object is: copper for ore, green for herbs, gold for quests, blue for chests."] = "Tu color de acento, o un color que dice qué es el objeto: cobre para menas, verde para hierbas, oro para misiones, azul para cofres."
L["Your bobber lights up while your line is in the water."] = "Tu boya se ilumina mientras el sedal está en el agua."
L["Your health on the display. Turn it off to keep just your power bar. Needs the power bar on."] = "Tu salud en la vista. Apágala para dejar solo la barra de poder. Hace falta la barra de poder."
L["Your health written on the personal display's health bar."] = "Tu salud escrita en la barra personal."
L["Your mana, rage or energy under the health bar. Needs the health bar on."] = "Tu maná, ira o energía bajo la barra de salud. Hace falta la barra de salud."
L["Your mana, rage or energy written on the personal display's power bar."] = "Tu maná, ira o energía escritos en la barra personal."
L["Your target's cast bar fills from the right. Not inside the frame or sliding out under it."] = "La barra de lanzamiento de tu objetivo se llena desde la derecha. No dentro del marco ni al deslizarse por debajo."
L["Your threat on each enemy as a number by its health bar: at 100% it turns on you. Shows in a group or with a pet. Works with Threat colors on or off."] = "Tu amenaza sobre cada enemigo, como un número junto a su barra de salud: al 100% se vuelve contra ti. Se muestra en grupo o con una mascota. Funciona con los colores de amenaza activados o no."
L["Zone name text size"] = "Tamaño del nombre de la zona"
L["A new group starts empty. Hold Shift while dragging an item to see your empty groups in the bag, and drop it on one's name. Or click the search beside it here to fill it by itself."] = "Un grupo nuevo empieza vacío. Mantén Mayús al arrastrar un objeto para ver tus grupos vacíos en la bolsa y suéltalo sobre el nombre de uno. O pulsa la búsqueda a su lado para que se llene solo."
L["A ring over the outer end. Class icons show for players; NPCs show their face."] = "Un anillo en el extremo exterior. Los jugadores muestran el icono de clase; los PNJ, su cara."
L["A small headset button at the top-right of the chat. It opens the game's Chat Channels window, where you join voice chat with your party, raid or a channel."] = "Un botón pequeño de auriculares arriba a la derecha del chat. Abre la ventana de canales de chat del juego, donde te unes al chat de voz con tu grupo, banda o un canal."
L["Boss"] = "Jefe"
L["By difficulty: the game's gray, green, yellow, orange and red for how hard the enemy is for your level. Or always white, your accent color, or one color you pick. ?? stays red."] = "Según la dificultad: el gris, verde, amarillo, naranja y rojo del juego, según lo duro que es el enemigo para tu nivel. O siempre blanco, tu color de acento, o un color que elijas. ?? sigue en rojo."
L["Caster"] = "Lanzador"
L["Custom level color"] = "Color de nivel personalizado"
L["Detach as group"] = "Separar como grupo"
L["Detach the main hand, off hand or ranged bar from the others to move and size it on its own."] = "Separa la barra de mano principal, mano izquierda o a distancia de las demás para moverla y cambiar su tamaño por su cuenta."
L["Detached bars"] = "Barras separadas"
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar. A bar detached on its own has its own."] = "La mano de cada barra (o el ataque en cola) y el tiempo hasta el siguiente golpe, escritos en la barra. Una barra separada por su cuenta tiene los suyos."
L["Each bar's name and number in that player's class color."] = "El nombre y el número de cada barra en el color de clase de ese jugador."
L["Hide friendly plates in instances"] = "Ocultar placas amistosas en estancias"
L["How big the number is. 0 fits it to the tag."] = "El tamaño del número. En 0 se ajusta a la etiqueta."
L["How dungeons, quests and zones are listed when you list yourself: lowest level first, or A to Z. The Sort button on that page changes it too."] = "Cómo se listan mazmorras, misiones y zonas cuando te apuntas: primero el nivel más bajo, o de la A a la Z. El botón Ordenar de esa página también lo cambia."
L["How solid the empty part and outline of each bar are. At 0 only the colored bars show."] = "Lo sólidas que son la parte vacía y el contorno de cada barra. En 0 solo se ven las barras de color."
L["How tall the tag is. 0 matches the name tab."] = "La altura de la etiqueta. En 0 coincide con la pestaña del nombre."
L["How wide the tag is."] = "La anchura de la etiqueta."
L["In instances"] = "En estancias"
L["Level color"] = "Color del nivel"
L["Level size"] = "Tamaño del nivel"
L["Loot window animations"] = "Animaciones de la ventana de botín"
L["No plates over friendly players and NPCs in dungeons, raids, battlegrounds and arenas. They come back as you leave."] = "Sin placas sobre jugadores y PNJ amistosos en mazmorras, bandas, campos de batalla y arenas. Vuelven al salir."
L["Nudges the tag sideways. Only while it sits on the frame."] = "Desplaza la etiqueta a un lado. Solo mientras está sobre el marco."
L["Nudges the tag up or down. Only while it sits on the frame."] = "Desplaza la etiqueta arriba o abajo. Solo mientras está sobre el marco."
L["On its own, the tag leaves the frame and you can move it anywhere in unlock mode, like near the middle of the screen."] = "Por su cuenta, la etiqueta sale del marco y puedes moverla a cualquier sitio en modo de desbloqueo, por ejemplo cerca del centro de la pantalla."
L["Only when detached as a group."] = "Solo cuando está separada como grupo."
L["Only when detached as a group. Hung under the player frame, the bars match its width."] = "Solo cuando está separada como grupo. Colgadas bajo el marco del jugador, las barras igualan su anchura."
L["Only when detached as a group. Main hand at the bottom, the others above it."] = "Solo cuando está separada como grupo. La mano principal abajo y las demás encima."
L["Only when detached on its own."] = "Solo cuando está separada por su cuenta."
L["Opens the layout editor right on your screen, on the profile your talent set uses: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "Abre el editor de diseño en la pantalla, sobre el perfil que usa tu conjunto de talentos: sube hechizos desde la bandeja, arrástralos donde quieras, engánchalos y haz clic en uno para cambiarlo. Escribe /cdm para abrirlo cuando quieras. Solo fuera de combate."
L["Rare"] = "Raro"
L["Roleplay names"] = "Nombres de rol"
L["Show empty groups"] = "Mostrar grupos vacíos"
L["Sort activities by"] = "Ordenar actividades por"
L["Takes the bars out from under the player frame so you can move them together (/dui unlock); they slide out of their own box. When off, they hang under the player frame, under the cast bar while it hangs there, even with the cast bar detached."] = "Saca las barras de debajo del marco del jugador para moverlas juntas (/dui unlock); salen deslizándose de su propia caja. Al desactivarlo, cuelgan bajo el marco del jugador, bajo la barra de lanzamiento mientras está ahí, aunque esa barra esté separada."
L["The hand (or the queued attack, or the range) written on the bar. Only when detached on its own."] = "La mano (o el ataque en cola, o la distancia) escrita en la barra. Solo cuando está separada por su cuenta."
L["The hand and time on the bar. Only when detached on its own."] = "La mano y el tiempo en la barra. Solo cuando está separada por su cuenta."
L["The level's color when Level color is One color."] = "El color del nivel cuando Color del nivel es Un color."
L["The light running down the loot window as it opens, items easing in behind it, the shine on rare items, taken items rising away, and the window fading in and out. When off, the loot window opens and closes with none of them."] = "La luz que recorre la ventana de botín al abrirse, los objetos que entran detrás, el brillo de los objetos raros, los objetos recogidos que suben, y la ventana que aparece y desaparece. Al desactivarlo, la ventana de botín se abre y se cierra sin nada de eso."
L["The number's color. By threat goes orange as you get close to pulling, red once it's on you."] = "El color del número. Según la amenaza pasa a naranja cuando estás cerca de atraer al enemigo, y a rojo cuando ya te ataca."
L["The small framed box behind the number. When off, only the number shows."] = "La caja pequeña con marco detrás del número. Al desactivarla, solo se ve el número."
L["The spell name and time on your target's cast bar. Not inside the frame: there it's Text size inside the frame."] = "El nombre del hechizo y el tiempo en la barra de lanzamiento de tu objetivo. No dentro del marco: ahí es Tamaño del texto dentro del marco."
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 sizes them to fit the power bar."] = "El nombre del hechizo y el temporizador mientras la barra está dentro del marco del objetivo, incluso por encima de la altura de la barra de poder. En 0 se ajustan a la barra de poder."
L["The tag's end is angled like the frame. When off, both ends are straight."] = "El extremo de la etiqueta está inclinado como el marco. Al desactivarlo, los dos extremos quedan rectos."
L["The time to the next swing, written on the bar. Only when detached on its own."] = "El tiempo hasta el siguiente golpe, escrito en la barra. Solo cuando está separada por su cuenta."
L["The weapon's picture at the start of the bar. Only when detached on its own."] = "La imagen del arma al principio de la barra. Solo cuando está separada por su cuenta."
L["Threat tag angled end"] = "Extremo inclinado de la etiqueta de amenaza"
L["Threat tag box"] = "Caja de la etiqueta de amenaza"
L["Threat tag color"] = "Color de la etiqueta de amenaza"
L["Threat tag height"] = "Altura de la etiqueta de amenaza"
L["Threat tag left / right"] = "Etiqueta de amenaza izquierda / derecha"
L["Threat tag position"] = "Posición de la etiqueta de amenaza"
L["Threat tag text size"] = "Tamaño del texto de la etiqueta de amenaza"
L["Threat tag up / down"] = "Etiqueta de amenaza arriba / abajo"
L["Threat tag width"] = "Anchura de la etiqueta de amenaza"
L["Voice chat button"] = "Botón de chat de voz"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting. A bar detached on its own has its own."] = "Mientras golpeas: cada barra solo mientras dura su golpe, y desaparece entre golpes. En combate: todas tus barras mientras luchas. Una barra separada por su cuenta tiene el suyo."
L["While swinging: only while its swing runs. In combat: while you're fighting. Only when detached on its own."] = "Mientras golpeas: solo mientras dura su golpe. En combate: mientras luchas. Solo cuando está separada por su cuenta."
L["Your groups with nothing in them always show in the bag. When off, they show only while you hold Shift with an item on the cursor."] = "Tus grupos vacíos se muestran siempre en la bolsa. Al desactivarlo, solo se ven mientras mantienes Mayús con un objeto en el cursor."
L["Your main hand's bar. Turn it off to keep only your other bars, like a hunter's ranged bar."] = "La barra de tu mano principal. Apágala para dejar solo las otras, como la de a distancia de un cazador."
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. Layouts are profiles: as many per class as you like, one for each talent set."] = "Tu propio diseño de reutilización: cada hechizo que sigue el gestor, como icono o como barra, colocado donde quieras y encajado con los demás. Los diseños son perfiles: tantos por clase como quieras, uno por cada conjunto de talentos."
L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. "] = "DPS/Tanque, en calma para hacer misiones: tus barras de acción y tu marco se desvanecen un rato tras un combate (vuelven bajo el ratón, en combate o si estás herido), el medidor de daño empieza plegado (un clic en la pestaña del panel lo saca), el minimapa es un poco más pequeño y la barra de PE muestra su porcentaje. Nada se desvanece en mazmorras, bandas, campos de batalla o arenas (General > Apariencia, Desvanecer solo en el mundo abierto). Elígelo arriba para usarlo."
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. "] = "DPS/Tanque con tu grupo y tu banda como baldosas bajo ti (tú incluido, con la salud que les falta y las disipaciones fáciles de ver), y tu marco y el de tu objetivo un poco más altos. Todo lo que ajusta está en las páginas Grupo y Banda; mueve cualquiera en modo de desbloqueo. Elígelo arriba para usarlo."

-- DaylightUI 1.6.5.2

