L["How big the numbers are. 1 is the game's own size."] = "El tamaño de los números. 1 es el del propio juego."
L["By power type: mana blue, rage red, energy yellow, each as its gradient from General > Gradients. Or one color you pick."] = "Por tipo de poder: el maná en azul, la ira en rojo y la energía en amarillo, cada uno con su degradado de General > Degradados. O un color que elijas."
L["Mana, rage or energy as a thin bar under the health bar: see a caster running dry, or a rogue saving up energy. The cast bar moves down under it."] = "Maná, ira o energía como una barra fina bajo la barra de salud: ves a un lanzador quedarse sin maná, o a un pícaro acumulando energía. La barra de lanzamiento baja y se coloca debajo."
L["Players and mana users: every enemy player, and the mobs that cast. Everyone with power: warriors' rage and the like too. Your target only: just the one you have selected."] = "Jugadores y usuarios de maná: cada jugador enemigo y los monstruos que lanzan hechizos. Todos los que tengan poder: también la ira de los guerreros y similares. Solo tu objetivo: únicamente el que tengas seleccionado."
L["Players and mana users"] = "Jugadores y usuarios de maná"
L["Everyone with power"] = "Todos los que tengan poder"
L["Your target only"] = "Solo tu objetivo"
L["Power bar gap"] = "Separación de la barra de poder"
L["Power bar on"] = "Barra de poder en"
L["The space between the health bar and the power bar. Set to 0 to join them."] = "El espacio entre la barra de salud y la barra de poder. Ponlo a 0 para unirlas."
L["Their mana, rage or energy as a thin bar under the health bar: see a healer running low. Who gets one, its size and color follow Health & Names > Power bar."] = "Su maná, ira o energía como una barra fina bajo la barra de salud: ves a un sanador quedarse sin maná. Quién la tiene, su tamaño y su color siguen a Salud y nombres > Barra de poder."
L["When off, every bar, border and highlight uses one flat color instead of two blended ones. The colors below still pick that color: the middle of each pair."] = "Desactivado, cada barra, borde y resaltado usa un solo color plano en lugar de dos mezclados. Los colores de abajo siguen eligiendo ese color: el punto medio de cada par."
