L["Takes the main hand bar out of the group onto a handle of its own (/dui unlock), with the settings below. It rises into place as it fades in."] = "Saca la barra de mano derecha del grupo y le da un tirador propio (/dui unlock), con los ajustes de abajo. Sube a su sitio mientras aparece."
L["Takes the off hand bar out of the group onto a handle of its own (/dui unlock), with the settings below. It rises into place as it fades in."] = "Saca la barra de mano secundaria del grupo y le da un tirador propio (/dui unlock), con los ajustes de abajo. Sube a su sitio mientras aparece."
