L["Which page of buttons this bar shows while you hold Shift. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra mientras mantienes Mayús. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows while you hold Ctrl. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra mientras mantienes Ctrl. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows while you hold Alt. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra mientras mantienes Alt. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows while you prowl. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra mientras acechas. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows in Cat Form. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Forma de gato. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows in Bear Form. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Forma de oso. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows in Stealth. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Sigilo. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows in Battle Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Actitud de batalla. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows in Defensive Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Actitud defensiva. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."
L["Which page of buttons this bar shows in Berserker Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Actitud rabiosa. Tus atajos lanzan lo que muestra la barra. «Sin cambios» conserva los botones propios de la barra."

-- DaylightUI 1.6.7

L["Spell casts for you, your target, focus and party."] = "Lanzamientos de hechizos para ti, tu objetivo, el foco y el grupo."
L["Party cast bars"] = "Barras de lanzamiento del grupo"
L["Show party cast bars"] = "Mostrar las barras de lanzamiento del grupo"
L["Each party member's casts on their own frame, while they last. They use the target cast bar's colors."] = "Los lanzamientos de cada miembro del grupo en su propio marco, mientras duran. Usan los colores de la barra de lanzamiento del objetivo."
L["Which side of each party frame a detached cast bar sits on."] = "En qué lado de cada marco de grupo se sitúa una barra de lanzamiento separada."
L["Moves the detached cast bars sideways from their side."] = "Desplaza las barras de lanzamiento separadas hacia los lados desde su lado."
L["Moves the detached cast bars up or down from their side."] = "Desplaza las barras de lanzamiento separadas hacia arriba o hacia abajo desde su lado."
L["How wide each detached cast bar is. Under the frame it matches the frame's width."] = "Anchura de cada barra de lanzamiento separada. Bajo el marco coincide con la anchura del marco."
L["How tall each party cast bar is. Not inside the frame, where it takes the power bar's place."] = "Altura de cada barra de lanzamiento del grupo. No dentro del marco, donde ocupa el lugar de la barra de poder."
L["The spell's icon at the end of each detached cast bar."] = "El icono del hechizo al final de cada barra de lanzamiento separada."
L["Cuts the end of each detached cast bar at an angle. When off, its end is straight."] = "Corta el extremo de cada barra de lanzamiento separada en diagonal. Desactivado, su extremo es recto."
L["Party cast bar text size"] = "Tamaño del texto de la barra de lanzamiento del grupo"
L["The spell name and time on the party's cast bars. Inside the frame it's kept small enough for the power bar."] = "El nombre del hechizo y el tiempo en las barras de lanzamiento del grupo. Dentro del marco se mantiene lo bastante pequeño para la barra de poder."
L["The spell name and timer while the bar sits inside a party frame, even past the power bar's height. 0 sizes them to fit the power bar."] = "El nombre del hechizo y el temporizador mientras la barra está dentro de un marco de grupo, incluso por encima de la altura de la barra de poder. En 0 se ajustan a la barra de poder."
L["Each detached cast bar fills from the right."] = "Cada barra de lanzamiento separada se llena desde la derecha."
L["The spell name and timer on the party's cast bars."] = "El nombre del hechizo y el temporizador en las barras de lanzamiento del grupo."
L["When short of power"] = "Cuando falta poder"
L["While it's off cooldown but you lack the energy, rage or mana for it: Kick shows only once you can afford it. Show tints it blue. Hide keeps its gap: the other spells don't move."] = "Mientras está fuera de reutilización pero te falta energía, ira o maná: Patada solo se muestra cuando puedes pagarla. «Mostrar» la tiñe de azul. «Ocultar» mantiene su hueco: los demás hechizos no se mueven."
L["Glows while the buff is up: Clearcasting, Nightfall."] = "Se ilumina mientras el beneficio está activo: Claridad mental, Ocaso."
L["PvP Frames"] = "Objetivo JcJ"
L["PvP frames"] = "Objetivo JcJ"
L["Show the PvP frames"] = "Mostrar el marco de JcJ"
L["As the chat style"] = "Según el estilo del chat"
L["Soul Shards"] = "Fragmentos de alma"

-- DaylightUI 1.6.8

L["Be a VIP supporter"] = "Hazte mecenas VIP"
L["Become a Daylight UI VIP on Patreon: press Ctrl+C to copy the link, then paste it in your browser."] = "Hazte mecenas VIP de Daylight UI en Patreon: pulsa Ctrl+C para copiar el enlace y pégalo en el navegador."
L["Click again to train all"] = "Haz clic de nuevo para aprenderlos todos"
L["Tip Daylight"] = "Apoyar a Daylight"
L["A light running round the ring, a slow breath, or no movement."] = "Una luz que recorre el anillo, una respiración lenta, o ningún movimiento."
L["A ring follows your mouse cursor, so it's easy to find in a busy fight."] = "Un anillo sigue al cursor del ratón, para encontrarlo con facilidad en un combate cargado."
L["A soft light around the ring."] = "Una luz suave alrededor del anillo."
L["A square in the spell's color, or the spell's own icon edged in that color."] = "Un cuadrado del color del hechizo, o el icono del hechizo con el borde de ese color."
L["A trail of light follows the cursor as it moves."] = "Una estela de luz sigue al cursor mientras se mueve."
L["All the time, or only during a fight."] = "Todo el tiempo, o solo durante un combate."
L["Both keeps it in its spot: the buff's time while it's up, then the cooldown. Buff only shows it just while the buff is up."] = "«Ambos» lo mantiene en su sitio: el tiempo del beneficio mientras está activo y, después, el tiempo de reutilización. «Solo beneficio» lo muestra solo mientras el beneficio está activo."
L["Casts on the cursor ring"] = "Lanzamientos en el anillo del cursor"
L["Change with forms and stances"] = "Cambiar con formas y actitudes"
L["Paging: this bar can show another page of buttons while you hold a key. Your stances and forms change it too, unless you switch that off below. Pick a spare page to fill it with spells of its own."] = "Paginación: esta barra puede mostrar otra página de botones mientras mantienes una tecla. Tus formas y actitudes también la cambian, salvo que lo desactives abajo. Elige una página libre para llenarla con hechizos propios."
L["Class uses your class's pair from the Gradients page. Daylight is the Daylight UI gradient."] = "«Clase» usa el par de tu clase de la sección Degradados. «Daylight» es el degradado de Daylight UI."
L["Copy its setup"] = "Copiar su configuración"
L["Cursor ring"] = "Anillo del cursor"
L["Cursor ring color"] = "Color del anillo del cursor"
L["Cursor ring glow"] = "Brillo del anillo del cursor"
L["Cursor ring motion"] = "Movimiento del anillo del cursor"
L["Cursor ring opacity"] = "Opacidad del anillo del cursor"
L["Cursor ring size"] = "Tamaño del anillo del cursor"
L["Cursor trail"] = "Estela del cursor"
L["Custom cursor ring color"] = "Color personalizado del anillo del cursor"
L["Druid bars height"] = "Altura de las barras del druida"
L["Druid bars numbers"] = "Números de las barras del druida"
L["Druid bars width"] = "Anchura de las barras del druida"
L["Druid resource bars"] = "Barras de recursos del druida"
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar. Each bar's own switches under Detached bars can turn off one or the other."] = "La mano de cada barra (o el ataque en cola) y el tiempo hasta el siguiente golpe, escritos en la barra. Los interruptores de cada barra, en «Barras separadas», pueden apagar uno u otro."
L["Fills by"] = "Se llena según"
L["Flash when the global cooldown ends"] = "Destello al acabar la reutilización global"
L["Frames grow"] = "Los marcos crecen"
L["Groups grow"] = "Los grupos crecen"
L["Lines grow"] = "Las líneas crecen"
L["Gives the second chat panel its own text size, set in the row below. When off, it matches the main chat's text size."] = "Da al segundo panel de chat su propio tamaño de texto, en la fila de abajo. Desactivado, coincide con el del chat principal."
L["Global cooldown on the ring"] = "Reutilización global en el anillo"
L["Happiness left / right"] = "Felicidad izquierda / derecha"
L["Happiness look"] = "Aspecto de la felicidad"
L["Happiness position"] = "Posición de la felicidad"
L["Happiness size"] = "Tamaño de la felicidad"
L["Happiness up / down"] = "Felicidad arriba / abajo"
L["Heal indicator look"] = "Aspecto del indicador de sanación"
L["Hide on cooldown"] = "Ocultar en reutilización"
L["Hide on global cooldown"] = "Ocultar en la reutilización global"
L["Hide while buff is up"] = "Ocultar mientras el beneficio está activo"
L["How big it is."] = "Su tamaño."
L["How long a new item stays in Recent before it goes to its own group. Right-click Recent to clear it sooner."] = "Tiempo que un objeto nuevo permanece en «Reciente» antes de pasar a su propio grupo. Clic derecho en «Reciente» para vaciarlo antes."
L["How long each bar is."] = "Longitud de cada barra."
L["How much of each power you have, on its bar."] = "Cuánto tienes de cada poder, en su barra."
L["How solid the ring is."] = "Lo sólido que es el anillo."
L["How tall each bar is."] = "Altura de cada barra."
L["How wide the ring is."] = "Anchura del anillo."
L["In a fight the window stays: scroll it, switch tabs and click a spell to cast it. The search and section buttons wait until the fight ends. Turn it off to get the game's own book in a fight, where you can drag spells to your bars."] = "En combate la ventana se queda: puedes desplazarla, cambiar de pestaña y hacer clic en un hechizo para lanzarlo. La búsqueda y los botones de sección esperan a que acabe el combate. Desactívalo para que en combate se abra el libro del juego, donde puedes arrastrar hechizos a las barras."
L["Instances are dungeons, raids and battlegrounds."] = "«Instancias» son mazmorras, bandas y campos de batalla."
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it; right-click Recent to clear it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "Objetos ordenados en grupos por tipo. Para mover un objeto a otro grupo, arrástralo sobre el encabezado de ese grupo o haz Alt+clic derecho sobre él. Haz clic en un encabezado para plegarlo; clic derecho en «Reciente» para vaciarlo. Alt+clic derecho también bloquea un objeto para que nunca se venda ni desencante."
L["Keep the spellbook in a fight"] = "Mantener el libro de hechizos en combate"
L["Move back"] = "Mover atrás"
L["Move forward"] = "Mover adelante"
L["No dark sweep over the icon while the spell is on cooldown."] = "Sin barrido oscuro sobre el icono mientras el hechizo está en reutilización."
L["Not usable"] = "No se puede usar"
L["Nudges it sideways."] = "Lo desplaza hacia los lados."
L["Nudges it up or down."] = "Lo desplaza hacia arriba o hacia abajo."
L["Once you're warmed by the fire, sitting on doesn't fade your UI away again for this long, so you can chat by the fire. 0 fades it every minute."] = "Cuando el fuego ya te ha calentado, seguir sentado no vuelve a desvanecer la interfaz durante este tiempo, para que puedas hablar junto al fuego. En 0 se desvanece cada minuto."
L["Pet happiness (hunters)"] = "Felicidad de la mascota (cazadores)"
L["Replaces this frame's size, bars, names, texts, icons and auras with the frame above's. Whether it's shown, its fade, where it sits and how a group is laid out stay."] = "Sustituye el tamaño, las barras, los nombres, los textos, los iconos y las auras de este marco por los del marco de arriba. Si se muestra, su desvanecimiento, dónde está y cómo se dispone un grupo se quedan."
L["Rest before it fades again (minutes)"] = "Descanso antes de que se desvanezca otra vez (minutos)"
L["Ring around the cursor"] = "Anillo alrededor del cursor"
L["Second panel text size"] = "Tamaño del texto del segundo panel"
L["Separate second panel text size"] = "Tamaño de texto propio del segundo panel"
L["Share your groups"] = "Compartir tus grupos"
L["Short of power"] = "Falta de poder"
L["Show the cursor ring"] = "Mostrar el anillo del cursor"
L["Show when alone"] = "Mostrar sin grupo"
L["Shows this square on each member while its spell is on them. Group buffs (Mark of the Wild, Fortitude, the Blessings) show from anyone, and count down their last minute."] = "Muestra este cuadrado en cada miembro mientras su hechizo está sobre él. Los beneficios de grupo (Marca de lo salvaje, Fortaleza, las Bendiciones) se muestran vengan de quien vengan, y cuentan el último minuto."
L["Small bars for the druid powers you're not using right now: rage and energy in caster form, mana in bear or cat form. Each shows once you know its form. Move them in unlock mode."] = "Barras pequeñas de los poderes de druida que no estás usando ahora: ira y energía en forma de lanzador, maná en forma de oso o de gato. Cada una aparece cuando conoces su forma. Muévelas en el modo de desbloqueo."
L["Start from another frame's setup instead of setting this one up from scratch."] = "Empieza con la configuración de otro marco en lugar de ajustar este desde cero."
L["Swap with the one after"] = "Intercambiar con el siguiente"
L["Swap with the one before"] = "Intercambiar con el anterior"
L["The empty part of every bar in the group. A spell's own background wins."] = "La parte vacía de cada barra del grupo. El fondo propio de un hechizo tiene prioridad."
L["The frame whose setup to copy onto this one."] = "El marco cuya configuración se copia en este."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the crowd control alert, the box that splits a stack. Also the game's own character and inspect windows while Daylight UI's are off."] = "El menú del juego, la lista de addons, macros, reloj, botín, engarces, mejoras, el desguazador, la casa de subastas, el libro de profesiones, el marco del mapa del mundo, la barra de respiración, la alerta de control y el cuadro para dividir una pila. También las ventanas propias de personaje e inspección del juego mientras las de Daylight UI están apagadas."
L["The global cooldown sweeps around the ring after each spell, so you see when the next one is ready."] = "El tiempo de reutilización global recorre el anillo tras cada hechizo, para ver cuándo está listo el siguiente."
L["The hand (or the queued attack, or the range) written on the bar, attached or detached."] = "La mano (o el ataque en cola, o la distancia) escrita en la barra, unida o separada."
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn Pet happiness off to have only this."] = "La barra de salud de la mascota toma el color del ánimo: rojo si está infeliz, amarillo si está contenta, verde si está feliz. Desactiva «Felicidad de la mascota» para quedarte solo con esto."
L["The pet's mood face edged in its color, or a square filled with it."] = "La cara de ánimo de la mascota con el borde de su color, o un cuadrado relleno con ese color."
L["The ring lights up the moment your next spell is ready."] = "El anillo se ilumina en el momento en que el siguiente hechizo está listo."
L["The ring's color when Cursor ring color is Custom."] = "El color del anillo cuando «Color del anillo del cursor» está en Personalizado."
L["The size of the messages on the second chat panel."] = "El tamaño de los mensajes del segundo panel de chat."
L["The spellbook and talent keys open DaylightUI's window. Turn it off to always use the game's window."] = "Las teclas del libro de hechizos y de talentos abren la ventana de DaylightUI. Desactívalo para usar siempre la ventana del juego."
L["The time to the next swing, written on the bar, attached or detached."] = "El tiempo hasta el siguiente golpe, escrito en la barra, unida o separada."
L["This icon's own size. Whole group sizes every icon in the group."] = "El tamaño propio de este icono. «Grupo entero» ajusta el de todos los iconos del grupo."
L["Trades places with the spell after it in the group. Each keeps its own look and options."] = "Intercambia el sitio con el hechizo siguiente del grupo. Cada uno conserva su aspecto y sus opciones."
L["Trades places with the spell before it in the group. Each keeps its own look and options."] = "Intercambia el sitio con el hechizo anterior del grupo. Cada uno conserva su aspecto y sus opciones."
L["Where on or around the frame it sits."] = "Dónde se sitúa, en el marco o a su alrededor."
L["Where the next line of frames goes once one is full."] = "Hacia dónde va la siguiente línea de marcos cuando una se llena."
L["Which way the frames run from the first one. Up or Left starts them at the bottom or the right, so a small group sits by that edge."] = "Hacia dónde van los marcos desde el primero. «Arriba» o «Izquierda» los empieza abajo o a la derecha, así un grupo pequeño queda junto a ese borde."
L["Your accent color (a gradient accent runs across the ring), your class's colors, or one you pick."] = "Tu color de acento (un acento en degradado recorre el anillo), los colores de tu clase, o uno que elijas."
L["Your casts and channels fill a thin ring around it."] = "Tus lanzamientos y canalizaciones llenan un anillo fino a su alrededor."
L["Your own frame shows here even when you're not in a group."] = "Tu propio marco se muestra aquí aunque no estés en un grupo."
L["Your pet's mood beside the frame: red while it's unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "El ánimo de tu mascota junto al marco: rojo si está infeliz, amarillo si está contenta, verde si está feliz. Pasa el ratón para ver su daño, lealtad y dieta."
L["Your stances, forms, stealth and the page keys swap this bar's buttons, as in the game. Off, it always shows its own buttons. Vehicles still take it over."] = "Tus actitudes, formas, el sigilo y las teclas de página cambian los botones de esta barra, como en el juego. Desactivado, muestra siempre sus propios botones. Los vehículos siguen ocupándola."
L["Light runs round it"] = "Una luz lo recorre"
L["Breathes"] = "Respira"
L["Still"] = "Quieto"
L["Mood face"] = "Cara de ánimo"
L["Color square"] = "Cuadrado de color"
L["Colored square"] = "Cuadrado de color"
L["Instances"] = "Instancias"
L["Open world"] = "Mundo abierto"

-- DaylightUI 1.6.8.1

L["%d groups: %s%s."] = "%d grupos: %s%s."
L["%s an item to move it to another group, lock it so it's never sold, or sell it as junk. %s at the top shows your bank and your other characters' bags from anywhere."] = "%s sobre un objeto para moverlo a otro grupo, bloquearlo para que nunca se venda, o venderlo como chatarra. %s, arriba, muestra tu banco y las bolsas de tus otros personajes desde cualquier sitio."
L["%s is no longer junk."] = "%s ya no es chatarra."
L["%s on the options' Home page runs it any time."] = "%s, en la página de inicio de las opciones, lo ejecuta cuando quieras."
L["%s will be sold as junk."] = "%s se venderá como chatarra."
L[", and %d more"] = ", y %d más"
L["/dui platefix - run while nameplates are invisible, one step each time, and say which step brought them back"] = "/dui platefix - úsalo mientras las placas de nombre no se ven, un paso cada vez, y di qué paso las ha devuelto"
L["/dui tour - a short tour of what Daylight UI adds"] = "/dui tour - un recorrido breve de lo que añade Daylight UI"
L["A minute to see what Daylight UI does that the game doesn't: the damage meter, buff and bag groups, moving frames and where every setting lives."] = "Un minuto para ver lo que hace Daylight UI y el juego no: el medidor de daño, los grupos de beneficios y de bolsas, mover los marcos y dónde está cada ajuste."
L["Abilities"] = "Habilidades"
L["Add by ID"] = "Añadir por ID"
L["Add point"] = "Añadir punto"
L["All characters of this faction"] = "Todos los personajes de esta facción"
L["Also supporting"] = "Otros mecenas"
L["Alt-right-click"] = "Alt+clic derecho"
L["At a glance"] = "De un vistazo"
L["Bag groups someone shared, added to yours."] = "Grupos de bolsas que alguien ha compartido, añadidos a los tuyos."
L["Bags in groups"] = "Bolsas en grupos"
L["Browse profiles"] = "Ver perfiles"
L["Buffs in groups"] = "Beneficios en grupos"
L["Buy a stack"] = "Comprar una pila"
L["Choose reward"] = "Elegir recompensa"
L["Clear recent items"] = "Vaciar objetos recientes"
L["Click: the game asks you to confirm first"] = "Clic: el juego pide confirmación antes"
L["Compare items"] = "Comparar objetos"
L["Cooldown layout report saved. Type /reload, then send your DaylightUI.lua file."] = "Informe del diseño de reutilización guardado. Escribe /reload y envía tu fichero DaylightUI.lua."
L["Copy the text in the box and send it to the Daylight UI team, then /reload."] = "Copia el texto del cuadro, envíalo al equipo de Daylight UI y después escribe /reload."
L["Crit"] = "Crít."
L["Ctrl + mouse wheel"] = "Ctrl + rueda del ratón"
L["Damage, healing and more for every fight, beside the minimap. Hover it for its buttons: which fight, what it counts, %s and reset. Hover a name for the breakdown of that player's spells."] = "Daño, sanación y más de cada combate, junto al minimapa. Pasa el ratón para ver sus botones: qué combate, qué cuenta, %s y reiniciar. Pasa el ratón sobre un nombre para el desglose de los hechizos de ese jugador."
L["Daylight UI: %s"] = "Daylight UI: %s"
L["Dragging spells to your bars works out of combat."] = "Arrastrar hechizos a las barras funciona fuera de combate."
L["Dressing room"] = "Probador"
L["Every piece of Daylight UI moves. %s shows a handle on each: drag it, scroll to resize, right-click to put it back. %s shows every frame with sample units, to style them without a group."] = "Cada pieza de Daylight UI se mueve. %s muestra un asa en cada una: arrástrala, usa la rueda para cambiar el tamaño y haz clic derecho para devolverla. %s muestra todos los marcos con unidades de muestra, para darles estilo sin un grupo."
L["Every setting"] = "Cada ajuste"
L["Export bag groups"] = "Exportar grupos de bolsas"
L["Export groups"] = "Exportar grupos"
L["Find your perfect setup"] = "Encuentra tu configuración ideal"
L["Flash Heal"] = "Sanación relámpago"
L["Flying"] = "Volando"
L["Forget this profession and every recipe you know in it, to make room for another. You can learn it again from a trainer, starting over from skill 1."] = "Olvida esta profesión y todas las recetas que conoces en ella, para hacer sitio a otra. Puedes volver a aprenderla con un instructor, empezando de nuevo desde la habilidad 1."
L["Form or stance"] = "Forma o actitud"
L["From your mount, talents, gear and buffs."] = "De tu montura, talentos, equipo y beneficios."
L["Gold, gear, free bag slots and who's online, turning amber then red when gear or bags run low. Hover one for details, click it for its window."] = "Oro, equipo, huecos libres en las bolsas y quién está conectado. Pasan a ámbar y luego a rojo cuando el equipo o las bolsas se quedan cortos. Pasa el ratón sobre uno para los detalles y haz clic para abrir su ventana."
L["Import bag groups"] = "Importar grupos de bolsas"
L["Import groups"] = "Importar grupos"
L["Import one here"] = "Importar uno aquí"
L["Imported %d bag groups."] = "Se han importado %d grupos de bolsas."
L["it has no groups in it"] = "no trae ningún grupo"
L["It starts folded away: the tab on the panel's edge slides it out."] = "Empieza plegado: la pestaña del borde del panel lo despliega."
L["it's from a newer Daylight UI; update to import it"] = "es de un Daylight UI más nuevo; actualízalo para importarlo"
L["Item ID:"] = "ID de objeto:"
L["Junk, sold at the next vendor"] = "Chatarra, se vende en el próximo comerciante"
L["Keybind"] = "Atajo"
L["Mark the bag item under the mouse as junk"] = "Marcar como chatarra el objeto de la bolsa bajo el ratón"
L["Monthly supporters"] = "Mecenas del mes"
L["Move anything"] = "Mover cualquier cosa"
L["N"] = "N"
L["Nameplate report"] = "Informe de placas de nombre"
L["No item has that ID."] = "Ningún objeto tiene esa ID."
L["No spell has that ID."] = "Ningún hechizo tiene esa ID."
L["Not junk"] = "No es chatarra"
L["Numbers from before the fight."] = "Números de antes del combate."
L["On land"] = "En tierra"
L["Paste bag groups (Ctrl+V). A group with the same name as one of yours is updated; the others are added."] = "Pega grupos de bolsas (Ctrl+V). Un grupo con el mismo nombre que uno de los tuyos se actualiza; los demás se añaden."
L["Play it again"] = "Reproducir otra vez"
L["Play the quest's voice"] = "Reproducir la voz de la misión"
L["Press Escape and pick Daylight UI in the game menu, or type %s. Search finds any setting. %s over any Daylight UI window sizes it. %s on Home runs this tour again."] = "Pulsa Esc y elige Daylight UI en el menú del juego, o escribe %s. La búsqueda encuentra cualquier ajuste. %s sobre cualquier ventana de Daylight UI cambia su tamaño. %s en Inicio lo vuelve a ejecutar."
L["Profiles shared by Daylight UI players: press Ctrl+C to copy the link, then paste it in your browser."] = "Perfiles compartidos por jugadores de Daylight UI: pulsa Ctrl+C para copiar el enlace y pégalo en el navegador."
L["Put on a controller bar"] = "Poner en una barra de mando"
L["Ready-made profiles from other Daylight UI players, from calm questing looks to raid healer layouts. Pick one you like, copy its string, import it in a click."] = "Perfiles preparados de otros jugadores de Daylight UI, desde un estilo tranquilo de misiones hasta diseños de sanador de banda. Elige uno, copia su texto e impórtalo en un clic."
L["Remove point"] = "Quitar punto"
L["Run /dui platefix first, while the nameplates are invisible."] = "Ejecuta antes /dui platefix, mientras las placas de nombre no se ven."
L["Sell as junk"] = "Vender como chatarra"
L["Share in chat"] = "Compartir en el chat"
L["Shared by players"] = "Compartidos por jugadores"
L["Shift-right-click"] = "Mayús+clic derecho"
L["Show all levels"] = "Mostrar todos los niveles"
L["Show me around"] = "Guíame"
L["Speed"] = "Velocidad"
L["Spell ID:"] = "ID de hechizo:"
L["Stacks and charges"] = "Acumulaciones y cargas"
L["Stop the voice"] = "Detener la voz"
L["Swimming"] = "Nadando"
L["Swipe"] = "Barrido"
L["Take a tour?"] = "¿Hacemos un recorrido?"
L["Take the tour"] = "Hacer el recorrido"
L["that isn't a Daylight UI bag groups string"] = "eso no es un texto de grupos de bolsas de Daylight UI"
L["That item has no use to time."] = "Ese objeto no tiene un uso que cronometrar."
L["the string is damaged (was all of it copied?)"] = "el texto está dañado (¿se ha copiado entero?)"
L["The tour waits until the fight is over."] = "El recorrido espera a que acabe el combate."
L["Top 10"] = "Los 10 primeros"
L["Top Donators"] = "Mejores mecenas"
L["Tour skipped. %s on the options' Home page shows it again."] = "Recorrido omitido. %s, en la página de inicio de las opciones, lo muestra otra vez."
L["Type a number."] = "Escribe un número."
L["Unlearn %s"] = "Olvidar %s"
L["you have no groups of your own yet"] = "aún no tienes grupos propios"
L["You move at %.0f%% of a normal run: on foot, mounted, swimming or flying, by what you're doing."] = "Te mueves al %.0f%% de una carrera normal: a pie, montado, nadando o volando, según lo que estés haciendo."
L["Your bags sort items into groups by kind. Press %s to open them."] = "Tus bolsas ordenan los objetos en grupos por tipo. Pulsa %s para abrirlas."
L["Your buffs sort themselves into groups. A buff in the wrong one? %s it and pick its group."] = "Tus beneficios se ordenan solos en grupos. ¿Uno está en el grupo equivocado? %s sobre él y elige su grupo."
L["Your own groups as text to copy: paste it on another character, or give it to a friend."] = "Tus propios grupos, como texto para copiar: pégalo en otro personaje, o dáselo a un amigo."
L["Your own groups: their names, searches and the items you moved to them. Ctrl+C to copy, then share it."] = "Tus propios grupos: sus nombres, búsquedas y los objetos que has movido a ellos. Ctrl+C para copiar y luego compártelo."
L["Which of the six squares the rows below set."] = "Cuál de los seis cuadrados ajustan las filas de abajo."
L["Only while you lead"] = "Solo mientras lideras"
L["A party's tank too"] = "También el tanque del grupo"
L["Everyone in a party"] = "Todos en el grupo"
L["This bar's own outline, corners and shadow, to match a power bar of its own or stand apart."] = "El contorno, las esquinas y la sombra propios de esta barra, para igualar una barra de poder con los suyos o para que destaque."
L["Gives this bar the border, corners and shadow below. When off, it follows General > Appearance."] = "Da a esta barra el borde, las esquinas y la sombra de abajo. Desactivado, sigue a General > Apariencia."

-- DaylightUI 1.6.9

