L["Raid 20 frames sit in a spot of their own, with their own handle when you unlock (/dui unlock), so a bigger raid can go where it fits. Off, they sit where Raid 10's do."] = "Los marcos de Banda 20 tienen un sitio propio, con su propio tirador al desbloquear (/dui unlock), para que una banda más grande quepa donde convenga. Desactivado, se quedan donde los de Banda 10."
L["Raid 40 frames sit in a spot of their own, with their own handle when you unlock (/dui unlock), so a bigger raid can go where it fits. Off, they sit where Raid 10's do."] = "Los marcos de Banda 40 tienen un sitio propio, con su propio tirador al desbloquear (/dui unlock), para que una banda más grande quepa donde convenga. Desactivado, se quedan donde los de Banda 10."
L["Gold characters"] = "Personajes del oro"
L["Every character"] = "Todos los personajes"
L["This faction"] = "Esta facción"
L["Whose gold the Gold text's tooltip lists and adds up: every character, or only those of the faction you're playing. A character counts for its faction once it has logged in after this update."] = "Qué oro lista y suma el aviso del texto de Oro: el de todos los personajes, o solo el de la facción con la que juegas. Un personaje cuenta en su facción en cuanto entra una vez después de esta actualización."
L["Same as General"] = "Igual que General"
L["Conversation opens"] = "La conversación se abre"
