L["Above the chat"] = "Encima del chat"
L["Where you dragged it"] = "Donde la arrastraste"
L["Conversation height"] = "Alto de la conversación"
L["The height of a whisper conversation above the chat or dragged away. Beside the chat it's as tall as the chat."] = "El alto de una conversación de susurros encima del chat o apartada. Junto al chat tiene la misma altura que el chat."
L["Where a whisper conversation opens. Drag one by its top to put it anywhere on your screen, and drag its corner to resize it."] = "Dónde se abre una conversación de susurros. Arrastra una por arriba para ponerla en cualquier sitio de la pantalla, y arrastra su esquina para cambiar el tamaño."
L["The width of a whisper conversation."] = "El ancho de una conversación de susurros."
L["A one-minute walk past what DaylightUI adds: the damage meter, buff and bag groups, moving frames and these options."] = "Un minuto para ver lo que añade DaylightUI: el medidor de daño, los grupos de beneficios y de bolsas, mover los marcos y estas opciones."

L["%d of %d"] = "%d de %d"
L["%s and %s"] = "%s y %s"
L["%s · %s"] = "%s · %s"
L["%sClick|r%s: details  ·  |r%sShift-click|r%s: report|r"] = "%sClic|r%s: detalles  ·  |r%sMayús+clic|r%s: informe|r"
L["ABSORBS"] = "ABSORCIONES"
L["A border and shadow around the window."] = "Un borde y una sombra alrededor de la ventana."
L["A friendly player's buffs as a row of small icons, so you can see what they're missing before you rebuff. Not in combat: the game hides other players' buffs then."] = "Los beneficios de un jugador aliado, en una fila de iconos pequeños, para ver qué le falta antes de volver a lanzárselos. En combate no: el juego oculta entonces los beneficios de los demás jugadores."
L["A small diamond by the names of the players in your party or raid, so they stand out in a crowd while their names keep their class color."] = "Un rombo pequeño junto a los nombres de los jugadores de tu grupo o banda, para que destaquen entre la multitud mientras sus nombres conservan el color de clase."
L["A square filled with the mood's color, or the pet's mood face edged in it."] = "Un cuadrado relleno con el color del ánimo, o la cara de ánimo de la mascota con el borde de ese color."
L["A thin line across the bars where your threat would pull the mob: 110% of the tank's in melee, 130% at range. Not shown against a boss, whose numbers the game keeps hidden."] = "Una línea fina atravesando las barras donde tu amenaza haría que el enemigo cambiara de objetivo: 110% de la del tanque en cuerpo a cuerpo, 130% a distancia. No se muestra contra un jefe, cuyas cifras el juego oculta."
L["A window showing an earlier fight goes back to this fight (or Overall) as the next one starts."] = "Una ventana que muestra un combate anterior vuelve a este combate (o a Total) cuando empieza el siguiente."
L["All meters"] = "Todos los medidores"
L["Always show yourself"] = "Mostrarte siempre"
L["Amounts shortened (12.3K) or in full (12,345), on every meter, the breakdowns and reports."] = "Cantidades abreviadas (12.3K) o completas (12,345), en todos los medidores, los desgloses y los informes."
L["An Alliance or Horde crest by the names of players of the other faction, on enemy and friendly plates alike."] = "Un emblema de la Alianza o de la Horda junto a los nombres de los jugadores de la otra facción, en placas enemigas y aliadas."
L["Angled bar ends"] = "Extremos de barra en ángulo"
