L["Ctrl+C to copy, then paste it in a bug report on the Daylight UI Discord. After that, /reload."] = "Ctrl+C para copiarlo y pégalo en un informe de error en el Discord de Daylight UI. Después, /reload."
L["Custom overshield color"] = "Color personalizado del sobreescudo"
