L["DPS"] = "DPS"
L["Damage or healing per second, in brackets after the total."] = "Daño o sanación por segundo, entre paréntesis tras el total."
L["Damage per second"] = "Daño por segundo"
L["Damage, healing and more for every fight, beside the minimap: the mode, the fight and its length on top, and its buttons there while the mouse is over it (which fight, what it counts, %s, reset, %s). Hover a name for their spells; click it for everything. More windows: %s."] = "Daño, sanación y más de cada combate, junto al minimapa: el modo, el combate y su duración arriba, y sus botones ahí mientras el ratón está encima (qué combate, qué cuenta, %s, reiniciar, %s). Pasa el ratón sobre un nombre para ver sus hechizos; haz clic para verlo todo. Más ventanas: %s."
L["Damage, healing and threat meters: the one in the info panel, the threat meter beside it, and as many windows of your own as you like."] = "Medidores de daño, sanación y amenaza: el del panel de información, el de amenaza a su lado, y tantas ventanas propias como quieras."
L["Dark end"] = "Extremo oscuro"
L["Deadly"] = "Letal"
L["Death"] = "Muerte"
L["Defensive Stance"] = "Actitud defensiva"
L["Each bar in its player's class color or all in one color; a threat meter can color each bar by how close that player is to pulling."] = "Cada barra en el color de clase de su jugador, o todas en un solo color. Un medidor de amenaza puede colorear cada barra según lo cerca que esté ese jugador de atraer al enemigo."
L["Each player's place, before their icon."] = "El puesto de cada jugador, delante de su icono."
L["Each player's share of everyone's total, in brackets. The game hides the numbers during a fight, so it shows once the fight is over."] = "La parte de cada jugador sobre el total de todos, entre paréntesis. El juego oculta las cifras durante el combate, así que se ve cuando termina."
L["Each player's total, the first number on their bar."] = "El total de cada jugador, el primer número de su barra."
L["Everyone's total for the fight, beside its length."] = "El total de todos en el combate, junto a su duración."
L["Every number, by player"] = "Cada cifra, por jugador"
L["Fall"] = "Bajada"
L["Fight on: updates when it ends."] = "Combate en curso: se actualiza al terminar."
L["Fight summary"] = "Resumen del combate"
L["Finish the setup guide first."] = "Termina primero la guía de preparación."
L["Flare"] = "Destello"
L["Fountain"] = "Fuente"
L["Friendly NPCs' names when Name color is Custom."] = "Nombres de los PNJ aliados cuando Color del nombre está en Personalizado."
L["Friendly players' names when Name color is Custom."] = "Nombres de los jugadores aliados cuando Color del nombre está en Personalizado."
L["Gives this window its own background opacity, set in the row below. When off, it's as see-through as the info panel's boxes (General page)."] = "Da a esta ventana su propia opacidad de fondo, la de la fila de abajo. Desactivada, es tan transparente como las cajas del panel de información (página General)."
L["Green when done"] = "Verde al completar"
