L["Hold: %s"] = "Mantener: %s"
L["How big the arrows are."] = "El tamaño de las flechas."
L["How big your target's name is. 0 keeps it the same as every plate's Name size."] = "El tamaño del nombre de tu objetivo. 0 lo deja igual que el Tamaño del nombre de todas las placas."
L["How much a plate lights up while your mouse is over it. At 0% it doesn't light up."] = "Cuánto se ilumina una placa mientras el ratón está encima. Al 0% no se ilumina."
L["How solid the empty part of every health and power bar is. Lower lets the world show through it, like the game's own frames."] = "Cómo de opaca es la parte vacía de cada barra de salud y de poder. Más bajo deja ver el mundo a través, como los marcos del juego."
L["How solid the empty part of every plate's health and power bar is. Lower lets the world show through it, like the game's own plates."] = "Cómo de opaca es la parte vacía de la barra de salud y de poder de cada placa. Más bajo deja ver el mundo a través, como las placas del juego."
L["How solid this window's background is: 0 is fully see-through, leaving only the bars."] = "Cómo de opaco es el fondo de esta ventana: 0 es del todo transparente y deja solo las barras."
L["How tall the window is. Dragging its corner in unlock mode sets it too."] = "La altura de la ventana. Arrastrar su esquina en el modo de desbloqueo también la ajusta."
L["How thick the ring is. A thicker ring leaves a smaller picture inside. The red aggro ring and its lights follow it."] = "El grosor del anillo. Un anillo más grueso deja una imagen más pequeña dentro. El anillo rojo de amenaza y sus luces lo siguen."
L["How wide the window is. Dragging its corner in unlock mode sets it too."] = "La anchura de la ventana. Arrastrar su esquina en el modo de desbloqueo también la ajusta."
L["In a group or with a pet"] = "En grupo o con mascota"
L["In the middle, the swing timers fanning out under it."] = "En el centro, con los tiempos de golpe abriéndose debajo."
L["Info Panel > Meters"] = "Panel de información > Medidores"
L["Its bag, bank and guild bank windows, slots and buttons. Another look can still be picked in Bagnon's own options."] = "Sus ventanas de bolsas, banco y banco de hermandad, ranuras y botones. En las opciones de Bagnon se puede seguir eligiendo otro aspecto."
L["Its bag, bank and guild bank windows, slots, buttons and settings, while its own Blizzard look is picked."] = "Sus ventanas de bolsas, banco y banco de hermandad, ranuras, botones y ajustes, mientras esté elegido su aspecto de Blizzard."
L["Killing blow"] = "Golpe de gracia"
L["Left end"] = "Extremo izquierdo"
