L["NPC names"] = "Nombres de PNJ"
L["Names of the other faction's players you can't attack (not flagged for PvP) when Name color is Custom."] = "Nombres de los jugadores de la otra facción a los que no puedes atacar (sin marcar para JcJ) cuando Color del nombre está en Personalizado."
L["Names on friendly plates in their class or reaction color, a class gradient, or plain white. Reaction: players in green too. Custom: pick a color for players, NPCs and the other faction below."] = "Nombres en las placas aliadas en su color de clase o de reacción, un degradado de clase, o blanco. Reacción: los jugadores también en verde. Personalizado: elige abajo un color para jugadores, PNJ y la otra facción."
L["Never shown solo: then everything is on you. The threat meter beside the meter slides back once the fight ends, and a click on its tab overrides this until the next fight. A threat window of your own set to Never shows in every fight in a group."] = "Nunca se muestra en solitario: entonces todo está sobre ti. El medidor de amenaza junto al medidor se repliega al terminar el combate, y un clic en su pestaña lo deja así hasta el siguiente combate. Una ventana de amenaza propia puesta en Nunca se muestra en todos los combates en grupo."
