L["Players' last names after their first on the threat meters. When off, first names only, which fit the narrow rows better."] = "Los apellidos detrás del nombre en los medidores de amenaza. Desactivado, solo el nombre, que cabe mejor en las filas estrechas."
L["Pop"] = "Salto"
L["Portrait rings"] = "Anillos de retrato"
L["Powershifting: the game takes a moment to confirm a new form, and shows your caster bar until it does. Put /click DaylightUICat (or DaylightUIBear, DaylightUIMoonkin) at the top of your shift macro and this bar swaps the moment you press it."] = "Cambio de forma: el juego tarda un momento en confirmar una forma nueva y muestra tu barra de lanzador hasta entonces. Pon /click DaylightUICat (o DaylightUIBear, DaylightUIMoonkin) al principio de tu macro de cambio y esta barra cambia en el momento en que pulsas."
L["Prowl"] = "Acechar"
L["Quest list beside the map"] = "Lista de misiones junto al mapa"
L["Rank numbers"] = "Números de puesto"
L["Rare elite"] = "Élite raro"
L["Reaction"] = "Reacción"
L["Reaction: every enemy name in red, players too, so friend and foe tell apart at a glance. Or players in their class color, a class gradient, or plain white."] = "Reacción: todos los nombres enemigos en rojo, también los jugadores, para distinguir amigo y enemigo de un vistazo. O los jugadores en el color de su clase, un degradado de clase, o blanco."
L["Red to green by count"] = "De rojo a verde según la cantidad"
L["Removes this window and its settings. Click twice."] = "Quita esta ventana y sus ajustes. Haz clic dos veces."
L["Report to chat"] = "Informar en el chat"
L["Reset every fight"] = "Reiniciar cada combate"
L["Right end"] = "Extremo derecho"
L["Right of the frame"] = "A la derecha del marco"
L["Right-click: pick which attack power"] = "Clic derecho: elegir qué poder de ataque"
L["Right-click: pin, invite, note, ignore, close"] = "Clic derecho: fijar, invitar, nota, ignorar, cerrar"
L["Ring thickness"] = "Grosor del anillo"
L["Rise"] = "Subida"
L["Same as shields"] = "Igual que los escudos"
L["Settings"] = "Ajustes"
L["Show only in an instance"] = "Mostrar solo en una instancia"
L["Show per second"] = "Mostrar por segundo"
L["Show share"] = "Mostrar la parte"
L["Show this window"] = "Mostrar esta ventana"
L["Show totals"] = "Mostrar totales"
L["Size of the names and numbers on the bars."] = "El tamaño de los nombres y los números de las barras."
L["Skip tour"] = "Saltar recorrido"
L["Slam"] = "Golpe"
L["Slides out from"] = "Sale desde"
L["Slides out from under your frame as you cast."] = "Sale de debajo de tu marco mientras lanzas."
L["Spells"] = "Hechizos"
L["Stack"] = "Apilado"
L["Stealth"] = "Sigilo"
L["Switched off, the window is gone (its settings stay). The threat meter beside the meter shows by its own rules below."] = "Desactivada, la ventana desaparece (sus ajustes se quedan). El medidor de amenaza junto al medidor se muestra según sus propias reglas, abajo."
L["Takes the bars out from under the player frame so you can move them together (/dui unlock); they slide out of their own box. When off, they hang under the player frame, under the cast bar while it hangs there, even with the cast bar detached. With your cast bar between your frame and the target's, they fan out under it instead, each a little wider."] = "Saca las barras de debajo del marco del jugador para moverlas juntas (/dui unlock); salen de su propia caja. Desactivado, cuelgan bajo el marco del jugador, bajo la barra de lanzamiento mientras esta cuelga ahí, aunque la barra de lanzamiento esté separada. Con la barra de lanzamiento entre tu marco y el del objetivo, se abren debajo de ella, cada una un poco más ancha."
L["Takes the damage meter out of the panel into its own window in the bottom-right corner; move it in unlock mode."] = "Saca el medidor de daño del panel y lo lleva a su propia ventana, en la esquina inferior derecha; muévelo en el modo de desbloqueo."
L["Target arrows"] = "Flechas del objetivo"
L["Target: name size"] = "Objetivo: tamaño del nombre"
L["Targets"] = "Objetivos"
L["Taken"] = "Recibido"
L["The arrows in your accent color, or one you pick below."] = "Las flechas en tu color de acento, o en uno que elijas abajo."
L["The arrows' color when Arrow color is Own color."] = "El color de las flechas cuando Color de la flecha está en Color propio."
L["The bars' filled part ends in a slanted edge. When off, it ends square."] = "La parte llena de las barras acaba en un borde inclinado. Desactivado, acaba recto."
L["The color of the names on the bars."] = "El color de los nombres de las barras."
L["The color of your party and raid members' names (with Group names on) and of the Group mark."] = "El color de los nombres de los miembros de tu grupo y banda (con Nombres del grupo activo) y de la Marca de grupo."
L["The game hides who's who here for now: it updates once it can."] = "El juego oculta de momento quién es quién: se actualiza en cuanto puede."
L["The last one follows your target when you can attack it, else the mob your friendly target is on: handy for a healer watching the tank."] = "La última sigue a tu objetivo cuando puedes atacarlo; si no, al enemigo al que ataca tu objetivo aliado: útil para un sanador que vigila al tanque."
L["The line on top: the mode, the fight and its length (a meter), or the mob and your own threat (a threat meter). A meter's buttons show in it while the mouse is over the window."] = "La línea de arriba: el modo, el combate y su duración (un medidor), o el enemigo y tu propia amenaza (un medidor de amenaza). Los botones de un medidor se ven ahí mientras el ratón está sobre la ventana."
L["The most group members it lists at once."] = "El máximo de miembros del grupo que lista a la vez."
L["The most group members it lists under the damage meter."] = "El máximo de miembros del grupo que lista bajo el medidor de daño."
L["The outline round the time and stack count on buffs and debuffs, apart from General > Appearance's, so the time stays easy to read over any icon."] = "El contorno del tiempo y del número de acumulaciones en beneficios y perjuicios, aparte del de General > Apariencia, para que el tiempo se lea bien sobre cualquier icono."
L["The overshield grows from where the health starts instead of from the frame's end."] = "El sobreescudo crece desde donde empieza la salud, en vez de desde el extremo del marco."
L["The overshield in the absorb shields' color, or a color of its own."] = "El sobreescudo en el color de los escudos de absorción, o en un color propio."
L["The overshield's color when Overshield color is Custom color."] = "El color del sobreescudo cuando Color del sobreescudo está en Color personalizado."
L["The overshield's look: the same as the shield texture, or its own."] = "El aspecto del sobreescudo: el mismo que la textura del escudo, o el suyo."
L["The player frame"] = "El marco del jugador"
L["The power bar"] = "La barra de poder"
L["The profile this character uses while the game's controller UI is on (Settings > Gameplay > Gamepad). Turning it on or off asks to switch. None: the same profile as without it."] = "El perfil que usa este personaje mientras la interfaz de mando del juego está activa (Opciones > Juego > Mando). Al activarla o desactivarla pregunta si cambias. Ninguno: el mismo perfil que sin ella."
L["The ring round every portrait, on every frame. Each frame picks its ring's color on its own page."] = "El anillo alrededor de cada retrato, en todos los marcos. Cada marco elige el color de su anillo en su propia página."
L["The role, marker and crown ride with the name tab or portrait until you pick a spot for them. The dispel icon sits in a corner."] = "El rol, el marcador y la corona van con la pestaña del nombre o el retrato hasta que les eliges un sitio. El icono de disipación se queda en una esquina."
L["The small square before each name: the player's class icon, or nothing."] = "El cuadrado pequeño delante de cada nombre: el icono de clase del jugador, o nada."
L["The space between two bars."] = "El espacio entre dos barras."
L["The thin dark line round the middle of the ring. When off, the ring is one smooth band."] = "La línea oscura y fina en el centro del anillo. Desactivada, el anillo es una banda lisa."
L["The threat meter and your threat windows fade together, apart from the panel."] = "El medidor de amenaza y tus ventanas de amenaza se desvanecen juntos, aparte del panel."
L["The window hides outside dungeons, raids, battlegrounds and arenas."] = "La ventana se oculta fuera de mazmorras, bandas, campos de batalla y arenas."
L["The window hides while you play solo."] = "La ventana se oculta mientras juegas en solitario."
L["Their buffs"] = "Sus beneficios"
L["There are already %d meter windows of your own: remove one to make another."] = "Ya tienes %d ventanas de medidor propias: quita una para crear otra."
L["Thick outline"] = "Contorno grueso"
L["Threat meter fade"] = "Desvanecimiento del medidor de amenaza"
L["Threat meter position"] = "Posición del medidor de amenaza"
L["Threat meter rows under the meter"] = "Filas del medidor de amenaza bajo el medidor"
L["Travel Form"] = "Forma de viaje"
L["Turn off"] = "Desactivar"
L["Turn on"] = "Activar"
L["Under the frame"] = "Bajo el marco"
L["Under the meter it rises out of the damage meter's bottom, as wide as the meter. Docked, it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode."] = "Bajo el medidor sale del borde inferior del medidor de daño, con su misma anchura. Acoplado, solo se muestra mientras el medidor de daño está abierto. Su propia ventana va a cualquier sitio: muévela en el modo de desbloqueo."
L["Under your frame"] = "Bajo tu marco"
L["Up to %d of your own, each with its own settings and spot. Move them in unlock mode."] = "Hasta %d propias, cada una con sus ajustes y su sitio. Muévelas en el modo de desbloqueo."
L["Usable"] = "Utilizable"
L["Utility"] = "Utilidad"
L["What this meter lists: damage, DPS, healing, absorbs, damage taken, interrupts, dispels, deaths and more. The button in its header changes it too."] = "Qué lista este medidor: daño, DPS, sanación, absorciones, daño recibido, interrupciones, disipaciones, muertes y más. El botón de su encabezado también lo cambia."
L["When a shield is bigger than the health missing, the part that doesn't fit runs back over the health with a bright line. When off, only the shield that fits shows."] = "Cuando un escudo es mayor que la salud que falta, la parte que no cabe vuelve sobre la salud con una línea brillante. Desactivado, solo se muestra el escudo que cabe."
L["When I'm the tank"] = "Cuando soy el tanque"
L["When you learn a new rank of a spell, it takes the place of the rank before it on your bars. A lower rank you keep on purpose, like rank 1 to save mana, stays. Not macros."] = "Cuando aprendes un rango nuevo de un hechizo, ocupa el sitio del rango anterior en tus barras. Un rango inferior que dejas a propósito, como el rango 1 para ahorrar maná, se queda. Las macros no."
L["When you'd be scrolled out of view, your bar stays in the last row with your place."] = "Cuando quedarías fuera de la vista al desplazarte, tu barra se queda en la última fila con tu puesto."
L["Whether the summary shows this column."] = "Si el resumen muestra esta columna."
L["Whether this window counts the fight you're in or every fight since the last reset."] = "Si esta ventana cuenta el combate en el que estás o todos los combates desde el último reinicio."
L["Which ends of each line are cut at an angle. The other end stays straight."] = "Qué extremos de cada línea se cortan en ángulo. El otro extremo se queda recto."
L["Which page of buttons this bar shows while you hold Shift. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra mientras mantienes Mayús. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows while you hold Ctrl. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra mientras mantienes Ctrl. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows while you hold Alt. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra mientras mantienes Alt. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows while you prowl. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra mientras acechas. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows in Cat Form. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Forma de gato. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows in Bear Form. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Forma de oso. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows in Stealth. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Sigilo. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows in Battle Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Actitud de batalla. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows in Defensive Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Actitud defensiva. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Which page of buttons this bar shows in Berserker Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Qué página de botones muestra esta barra en Actitud rabiosa. Tus atajos lanzan lo que muestra la barra. Sin cambios mantiene los botones propios de la barra."
L["Whose threat"] = "Amenaza de quién"
L["Window header"] = "Encabezado de la ventana"
L["Windows show the same fight"] = "Las ventanas muestran el mismo combate"
L["With more than one of these on, it shows only when all of them hold."] = "Con más de una de estas activa, solo se muestra cuando se cumplen todas."
L["With the map maximized, the quest list opens beside it, as it does on the small map, instead of taking its room from the map. On a narrow screen the map gives up only what doesn't fit."] = "Con el mapa maximizado, la lista de misiones se abre a su lado, como en el mapa pequeño, en vez de quitarle sitio al mapa. En una pantalla estrecha el mapa solo cede lo que no cabe."
L["With the power bar on its own (Player > Power bar), the cast bar and the swing timer under it can slide out from under the power bar instead of the frame."] = "Con la barra de poder por su cuenta (Jugador > Barra de poder), la barra de lanzamiento y el tiempo de golpes que hay debajo pueden salir de debajo de la barra de poder en vez del marco."
L["Without the controller, this character uses the profile %s. Switch to it?"] = "Sin el mando, este personaje usa el perfil %s. ¿Cambiar a él?"
L["Your focus"] = "Tu foco"
L["Your target"] = "Tu objetivo"
L["Your target, else your target's target"] = "Tu objetivo, o si no el objetivo de tu objetivo"
L["Your windows"] = "Tus ventanas"
L["new window"] = "ventana nueva"

-- A few lines change with the character's sex. The sex is only known once the
-- player is in the world, and every one of these is read when it's drawn, so
-- swapping them in at login is enough. UnitSex can be secret in a PvP match:
-- then the lines above stay as they are.
local FEMININE = {
    ["Rested"] = "Descansada",
    ["Fully rested. Go spend it!"] = "Totalmente descansada. ¡Ve a gastarlo!",
    ["Ready when you are"] = "Lista cuando tú lo estés",
    ["%s away. Your character is getting stiff."] = "%s ausente. Tu personaje se está poniendo rígida.",
    ["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tanque sosegado para las misiones: tus barras de acción y tu propio marco se desvanecen un rato después de un combate (vuelven bajo el ratón, en combate o cuando estás herida), el medidor de daño empieza plegado (un clic en la pestaña del panel lo hace aparecer), el minimapa es un poco más pequeño y la barra de PE muestra su porcentaje. Nada se desvanece en mazmorras, bandas, campos de batalla o arenas (General > Apariencia, Desvanecer solo en mundo abierto). Elígelo arriba para usarlo. Si el perfil actual tiene barras de acción movidas, ofrece llevarlas consigo.",
    ["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tanque con tu grupo y tu banda como casillas cuadradas debajo de ti (tú incluida, con la salud perdida en ellas y las disipaciones bien visibles), y tu marco y el de tu objetivo un poco elevados. Todo lo que ajusta está en las secciones Grupo y Banda; mueve cualquiera de ellos en modo de desbloqueo. Elígelo arriba para usarlo. Si el perfil actual tiene barras de acción movidas, ofrece llevarlas consigo.",
}
local login = CreateFrame("Frame")
login:RegisterEvent("PLAYER_LOGIN")
login:SetScript("OnEvent", function(self)
    self:UnregisterEvent("PLAYER_LOGIN")
    local sex = UnitSex("player")
    if issecretvalue and issecretvalue(sex) then return end
    if sex ~= 3 then return end
    for key, text in pairs(FEMININE) do L[key] = text end
end)
